(47, 'Inverted Microscope', 16, 0, 29, 50, 119, 1, 'Leica', 'Leeica DM IL', '0000', '', '                                                                                                                                                                                                                                                                                                                    With high-performance optics and ergonomic design, the Leica DM IL LED is ideal for cell culture, micromanipulation, documentation of immunostained specimens, and routine live cell examinations. The Leica DM IL LED features a comprehensive set of contrast methods to monitor your specimen the way you need                                                                                                                                                                                                                                                                                        ', '', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, 'Yes', 0, 'Treasury funds', '0000-00-00', 1, 'Dr. M A B Ranatunga', 'mahasenab@yahoo.com', '0522222601', '0718501298', '                                                                                                                                                                                                                                                                                               Cytology                                                                                                                                                                                                                                                                                                                                                    ', NULL, 'Inverted_Microscope.jpg', '', '', '', 0, 22, '2022-07-28 14:56:20', 22, '2022-09-02 15:19:06', NULL, NULL, NULL),
(48, 'Inverted Microscope and Leika DC-160 camera ', 17, 15, 30, 48, 5, 1, 'Leica', 'Leica DM E  / Leica DC-160', '0000', '', '                                                                                                                                    Leica Microscope is highly efficient illumination system with a more powerful halogen lamp than any other microscope in this class provides consistent color and intensity throughout the whole lamp life (over 2000 hours). The Leica DM E will enhance the quality of your microscopy work. The Leica DC160 camera system combines the · best elements of micro and macro photography.                                                                                                                                                     ', '', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, 'Yes', 0, 'Treasury funds', '2008-05-01', 1, 'Dr. M A B Ranatunga', 'mahasenab@yahoo.com', '0522222601', '0718501298', '                                                                                                                           Cytology                                                                                                                                                                               ', NULL, 'Inverted_Microscope_and_Leika_DC-160_camera_(2)1.jpg', '', '', '', 0, 22, '2022-07-28 15:02:32', 1, '2022-08-31 23:37:06', NULL, NULL, NULL),
(49, 'Optika Microscope and Height-performance FULL HDMI camera', 16, 0, 29, 50, 119, 1, 'Optika Microscope', 'B-500 TPL / OPTIKAM PRO HDMI', '0000', '', '                                                                                                                                                                                An optical microscope creates a magnified image of an object specimen with an objective lens and magnifies the image further more with an eyepiece to allow the user to observe it by the naked eye.. The Camera offers the highest quality images through a simple connection to projector, TV monitor or PC monitor.                                                                                                                                                                                                        ', '', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, 'Yes', 0, 'Treasury funds', '2014-11-14', 1, 'Dr. M A B Ranatunga', 'mahasenab@yahoo.com', '0522222601', '0718501298', '                                                                                                                                                                    Cytology                                                                                                                                                                ', NULL, 'Optika_Microscope_and_Hight-performance_FULL_HDMI_camera.jpg', '', '', '', 0, 22, '2022-07-28 15:08:22', 22, '2022-09-02 15:19:23', NULL, NULL, NULL),
