(207, 'Refrigerated Centrifuge', 16, 0, 26, 42, 95, 2, 'SORVALL ', 'RC-26 PLUS', '1998', '', '                                                                                                                                    A refrigerated centrifuge is a laboratory equipment used for the separation of microliter temperature-sensitive heterogeneous mixtures or samples. This device works by spinning the samples loaded in a rotor at high speed.                                                                                                                                                                                      ', '', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, 'Yes', 1, 'Treasury funds', '0000-00-00', 1, 'Dr. K. G. Nelum P. Piyasena', 'nelumpriya@yahoo.com', '0522258201', '0702703306', '                                                                                                                                                                                                                                                                                                                                       ', NULL, 'sorvall.jpg', '', '', '', 0, 22, '2022-08-10 15:48:45', 22, '2022-09-02 16:23:05', NULL, NULL, NULL),
(208, 'Bench-top Centrifuge', 16, 0, 26, 42, 95, 1, 'U-THERM INTERNATIONAL (H.K.) LIMITED', 'SE-CF-TD6', '2017', '', '                                                                                                                                    A integral piece of laboratory equipment that is driven by an electric motor that puts an object in rotation around a fixed axis, applying a force perpendicular to the axis.                                                                                                                                                                     ', '', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, 'Yes', 1, 'Treasury funds', '2017-10-18', 1, 'Dr. K. G. Nelum P. Piyasena', 'nelumpriya@yahoo.com', '0522258201', '0702703306', '                                                                                                                                                                                                                                                                                                                                       ', NULL, 'bench_top_centrifuge.jpg', '', '', '', 0, 22, '2022-08-10 15:54:51', 22, '2022-09-02 16:25:00', NULL, NULL, NULL),
(209, 'Micro centrifuge', 16, 0, 26, 42, 95, 1, 'Brinkmann Instruemnts, INC.', '5415', '1988', '', '                                            A microcentrifuge is an important piece of equipment for any laboratory, as it is used for spinning a variety of samples at high speed, enabling, for example, the pelleting of nucleic acids or proteins from solution, microfiltration of small aqueous samples and gathering liquid into the bottom of a tube to avoid wastage.                                                                                     ', '', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, 'Yes', 1, 'Treasury funds', '0000-00-00', 1, 'Dr. K. G. Nelum P. Piyasena', 'nelumpriya@yahoo.com', '0522258201', '0702703306', '                                                                                                                                                                     ', NULL, 'micro_centrifuge.jpg', '', '', '', 0, 22, '2022-08-10 15:59:03', 22, '2022-09-02 16:25:38', NULL, NULL, NULL),
(210, 'Universal Oven', 16, 0, 26, 42, 95, 1, 'Memmert GmbH', 'UF-260', '0000', '', '                                                                   Used to expose materials to a hot environment. Ovens contain a hollow chamber and provide a means of heating the chamber in a controlled way.                                                                                                     ', '', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, 'Yes', 1, 'Treasury funds', '2018-02-21', 1, 'Dr. K. G. Nelum P. Piyasena', 'nelumpriya@yahoo.com', '0522258201', '0702703306', '                                                                                                                                                                     ', NULL, 'oven_memmert.png', '', '', '', 0, 22, '2022-08-10 16:02:59', 22, '2022-09-02 16:26:16', NULL, NULL, NULL),
(211, 'Muffle furnace', 16, 0, 26, 42, 95, 1, 'Nabertherm GmbH', 'L 40/11', '0000', '', '                                            A Muffle furnace allows rapid high-temperature heating, recovery, and cooling in self-contained, energy-efficient cabinets. A muffle furnace separates the object to be heated from all byproducts of combustion from the heat source.                                                                                                     ', '', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, 'Yes', 1, 'Treasury funds', '2016-12-22', 1, 'Dr. K. G. Nelum P. Piyasena', 'nelumpriya@yahoo.com', '0522258201', '0702703306', '                                                                                                                                                                     ', NULL, 'muffle_furnace.jpg', '', '', '', 0, 22, '2022-08-10 16:08:06', 22, '2022-09-02 16:26:35', NULL, NULL, NULL),
(212, 'Waterbath', 16, 0, 26, 42, 95, 1, 'MEMMERT GmbH Co.KG', '', '1998', '', '                                            A laboratory equipment that is used to incubate samples at a constant temperature over a long period of time. Water bath is a preferred heat source for heating flammable chemicals instead of an open flame to prevent ignition.                                                                                        ', '', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, 'Yes', 1, 'Treasury funds', '0000-00-00', 1, 'Dr. K. G. Nelum P. Piyasena', 'nelumpriya@yahoo.com', '0522258201', '0702703306', '                                                                                                                                                                     ', NULL, 'Memmert-Waterbath.jpg', '', '', '', 0, 22, '2022-08-10 16:11:47', 22, '2022-09-02 16:26:53', NULL, NULL, NULL),
(213, 'Low Temperature Incubator', 16, 0, 26, 42, 106, 1, 'JETO Tech Co. Ltd. - South Korea', '1L-11-2C', '0000', '', '                                            Low-temperature Incubators are designed to maintain temperatures below ambient to as low as about 10°C. An incubator is a device used to grow and maintain microbiological cultures or cell cultures and maintains optimal temperature, humidity and other conditions such as the CO2 and oxygen content of the atmosphere inside.                                                                                         ', '', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, 'Yes', 1, 'Treasury funds', '2017-05-23', 1, 'Dr. K. G. Nelum P. Piyasena', 'nelumpriya@yahoo.com', '0522258201', '0702703306', '                                                                                                                                                                     ', NULL, 'INCUBATOR.jpg', '', '', '', 0, 22, '2022-08-10 16:15:50', 22, '2022-09-02 16:27:14', NULL, NULL, NULL),
(214, 'Vertical Laminar Flow Cabinet', 16, 0, 26, 42, 106, 1, 'ESCO Micro Pte Ltd', 'LVG-4AG-F8', '2017', '', '                                            A containment equipment which provides zoned unidirectional down-flow airflow to a working area or zone underneath it for protection of processes. This unidirectional airflow positively pressurizes and purges the working environment from contaminants which enhances the aseptic work zone.                                                                     ', '', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, 'Yes', 1, 'Treasury funds', '2017-07-11', 1, 'Dr. K. G. Nelum P. Piyasena', 'nelumpriya@yahoo.com', '0522258201', '0702703306', '                                                                                                                                                                     ', NULL, 'LAMINAR_FLOW.jpg', '', '', '', 0, 22, '2022-08-10 16:18:55', 22, '2022-09-02 16:27:32', NULL, NULL, NULL),
(215, 'Fumehood', 16, 0, 26, 42, 95, 1, 'ESCO Micro Pte Ltd', 'EQU/05-EFH', '2004', '', '                                            A fume hood is a type of local ventilation device that is designed to limit exposure to hazardous or toxic fumes, vapors or dusts.                                                                                                          ', '', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, 'Yes', 1, 'Treasury funds', '0000-00-00', 1, 'Dr. K. G. Nelum P. Piyasena', 'nelumpriya@yahoo.com', '0522258201', '0702703306', '                                                                                                                                                                     ', NULL, 'FUME_CUPBOARD.jpg', '', '', '', 0, 22, '2022-08-10 16:21:47', 22, '2022-09-02 16:27:50', NULL, NULL, NULL),
(216, 'Ice flake machine', 16, 0, 26, 42, 106, 1, 'SCOTSMAN - Italy', 'AF 10ASE 0600', '0000', '', '                                            Ice Flake Machines produce ice in granular flakes. They are ideal for providing a cool bedding for food, including fish and gourmet delicacies. The weight and volume of the ice flakes are tailored to suit your storage, transport and dosing needs.                                                                                         ', '', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, 'Yes', 1, 'Treasury funds', '0000-00-00', 1, 'Dr. K. G. Nelum P. Piyasena', 'nelumpriya@yahoo.com', '0522258201', '0702703306', '                                                                                                                                                                     ', NULL, 'ICE_FLAKE_MACHINE.jpg', '', '', '', 0, 22, '2022-08-10 16:24:22', 22, '2022-09-02 16:28:10', NULL, NULL, NULL),
(217, 'Ultrasonic Cleaner', 16, 0, 26, 42, 95, 1, 'LabTech', 'LUC-405/410/420', '0000', '', '                                                                   Ultrasonic cleaning uses high-frequency, high-intensity sound waves in a liquid to facilitate or enhance the removal of foreign contaminants from surfaces submerged in an ultrasonically activated liquid.                                                                                                     ', '', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, 'Yes', 1, 'Treasury funds', '2009-07-07', 1, 'Dr. K. G. Nelum P. Piyasena', 'nelumpriya@yahoo.com', '0522258201', '0702703306', '                                                                                                                                                                     ', NULL, 'sonicator.jpg', '', '', '', 0, 22, '2022-08-10 16:26:44', 22, '2022-09-02 16:28:36', NULL, NULL, NULL),
(218, 'UV Viewing Cabinet', 16, 0, 26, 42, 106, 1, 'Vilber lourmat-France', 'CN-6', '0000', '', '                                            UVP Mini Chromato-Vue Viewing Cabinets provide a compact darkroom environment for viewing materials. All cabinets feature a contrast control filter that absorbs UV energy to protect the eyes.                                                                         ', '', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, 'Yes', 1, 'Treasury funds', '2019-03-22', 1, 'Dr. K. G. Nelum P. Piyasena', 'nelumpriya@yahoo.com', '0522258201', '0702703306', '                                                                                                                                                                     ', NULL, 'vilber-uv-darkroom-viewing-cabinets.jpg', '', '', '', 0, 22, '2022-08-10 16:30:48', 22, '2022-09-02 16:29:29', NULL, NULL, NULL),
(219, 'ECM Equipment', 16, 0, 26, 42, 106, 1, 'Teacraft Ltd.', '', '0000', '', '                                            The ECM System is a precisely controlled integrated miniature factory. By using it your mini-manufacture results are dependable time after time because the confounding effect of ambient conditions is virtually eliminated. Process conditions are tightly controlled and closely simulate the real life factory.                                                                                                             ', '', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, 'Yes', 1, 'Treasury funds', '0000-00-00', 1, 'Dr. K. G. Nelum P. Piyasena', 'nelumpriya@yahoo.com', '0522258201', '0702703306', '                                                                                                                                                                     ', NULL, 'ECM.jpg', '', '', '', 0, 22, '2022-08-10 16:34:46', 22, '2022-09-02 16:29:57', NULL, NULL, NULL),
(220, 'Vacuum Rotary Evaporator', 16, 0, 26, 42, 106, 1, 'W. Buchi-Switzerland', 'Rotavapor - SB', '0000', '', '                                                                        A rotary evaporator is a device used in chemical laboratories for the efficient and gentle removal of solvents from samples by evaporation.                                                                                                ', '', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, 'Yes', 1, 'Treasury funds', '0000-00-00', 1, 'Dr. K. G. Nelum P. Piyasena', 'nelumpriya@yahoo.com', '0522258201', '0702703306', '                                                                                                                                                                     ', NULL, 'Rotary-Evaporator.jpg', '', '', '', 0, 22, '2022-08-10 16:37:00', 22, '2022-09-02 16:31:24', NULL, NULL, NULL),
(221, 'Multi-Position Hotplate Stirrer', 16, 0, 26, 42, 95, 1, 'DAIHAN LAB TECH CO.LTD.', 'LMS-3006', '0000', '', '                                                                                        Multi-position digital magnetic hotplate stirrers are designed for synchronous heating and stirring, suitable for continuous operation. Large top plates with position indicators are easy to clean and provide a reflective surface, and can accommodate a number of stirring vessels simultaneously.                                                                                                              ', '', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, 'Yes', 1, 'Treasury funds', '2013-02-15', 1, 'Dr. K. G. Nelum P. Piyasena', 'nelumpriya@yahoo.com', '0522258201', '0702703306', '                                                                                                                                                                                                                                                      ', NULL, 'HOTPLATE.jpg', '', '', '', 0, 22, '2022-08-10 16:41:34', 22, '2022-09-02 16:31:41', NULL, NULL, NULL),
(222, 'PCR / Thermal Cyclers ', 7, 6, 13, 37, 71, 1, 'BIO-RAD', 'My Cycler Thermal Cycler', '2011', '', '<p>PCR system with a gradient feature used for gene amplification. This compact thermal cycler features intuitive programming of temperatures, times, and protocols with ready-made templates for ease of viewing, editing, and running protocols.</p>\r\n', 'https://www.bio-rad.com/webroot/web/pdf/lsr/literature/Bulletin_2855F.pdf', '', '', 1000000.00, 0.00, 'P & T Trading (Pvt)Ltd', '0112807076', 'https://ptt.lk/', 96, 0, 0, '', 'Yes', 1, 'University Fund', '2011-09-19', 1, 'Mrs. H.C.D. Wijewardene', 'dwdarshani@yahoo.com', '0252221611', '', '                                                                                                                             96-well PCR system with a gradient feature used for gene amplification, Program protocols with as many as 9 cycles with 9 steps each and repeats up to 99 times per cycle.                                                                                                                                                                                                                                                    ', NULL, 'PCR_1.jpg', 'PCR_2.jpg', 'PCR_3.jpg', '', 0, 46, '2022-08-11 13:04:49', 36, '2023-01-04 15:27:44', NULL, NULL, NULL),
(223, 'Grain Moisture Meter', 7, 6, 13, 37, 22, 1, 'G-WON HITECH', 'GMK-303A', '2013', '', '                                                                                                                                                                                                                                                                        This meter checks the moisture content in grains and seeds accurately and quickly, it is compact, easy to use and the moisture measurement readings are instant. It helps decide the ideal time to harvest the crops and helps keep a constant moisture content of the grains and seeds.                                                                                                                                                                                                                                                 ', 'https://www.google.com/search?q=Seed+Moisture+meter+G-WON+GMK-303A&ei=b7X0Ys-IBJOjoATD3pyoAg&ved=0ahUKEwiP_Nerp775AhWTEYgKHUMvByUQ4dUDCA0&uact=5&oq=Seed+Moisture+meter+G-WON+GMK-303A&gs_lcp=Cgdnd3Mtd2l6EAM6BwghEKABEAo6CAghEB4QFhAdOgUIIRCgAUoECEEYAUoECEYYAFDYAljxigFgzpsBaARwAHgAgAHxAogB7AuSAQUyLTIuM5gBAKABAaABAsABAQ&sclient=gws-wiz', '', '', 67292.00, 0.00, 'Analytical Instruments (PVT)LTD', '0112639000', 'http://www.aipl.lk/', 1, 50, 5, NULL, 'Yes', 1, 'University Fund', '2013-02-26', 1, 'Dr. D.A.U.D. Devasinghe', 'udenidevasinghe@yahoo.com ', '0252221611', '', '                                         Moisture, Seed Paddy, Rice, Soybean, Barley, Wheat, Maize                                                                                                                                                                                                                                                                                                                                 ', NULL, 'Grain_Moisture_Meter_GMK_303.jpg', '', '', '', 0, 46, '2022-08-11 14:08:59', 36, '2022-09-13 22:47:13', NULL, NULL, NULL)