(344, 'Autoclave', 3, 36, 74, 104, 127, 1, 'Tuttnauer', '3850ELV-D', '2016', '3850ELV-D', '                                            Tuttnauer vertical laboratory autoclaves are top loading autoclaves available in chamber sizes between 31 to 160 liters. ELV models have an advanced microprocessor control panel and chamber made of 316L stainless steel.  Tuttnauer laboratory autoclaves have been designed to provide high quality repeatable performance and accountability for a wide range of applications used in modern laboratories.\r\n\r\n                                        ', 'https://tuttnauer.com/laboratory-autoclaves/laboratory-research/vertical-autoclaves/elv-d-line', 'lab_line_nb_english-31-10-21.pdf', '', 0.00, 0.00, 'Delmage Forsyth & co Ltd', '0112686838', 'https://delmege.com/company/medical-equipment/', 10, 2, 3, NULL, 'No', 0, 'Austrian Grant', '2019-01-11', 1, 'Dr. Kavinda Tissera', 'kavindatissera@ahs.pdn.ac.lk', '0812065788', '0702797348', '                                                                                                                                                                     ', NULL, '3870elv-d-lab-autoclave-sterilizer_0.png', '', '', '', 0, 174, '2022-09-09 14:07:34', 173, '2022-09-11 10:28:29', NULL, NULL, NULL),
(345, 'Co2 Incubator', 3, 36, 74, 104, 126, 1, 'BIOBASE', 'BJPX-C160', '2017', '84362100', 'Carbon dioxide (CO2) incubators provide optimal growing conditions and contamination prevention for valuable cell cultures.BIOBASE provides a wide range of CO2 incubators, ranging from a small capacity and volume to a large scale capacity cabinet. All the CO2 incubators are build with the patented Water Jacket and Air Jacket systems, which minimizes the risk of condensation at the present and in the future.\r\n', 'https://www.biobase.cc/CO2-Incubator-BJPX-C-pd41086305.html', '1-2_CO2_Incubator_(1).jpg', '', 0.00, 0.00, 'Ims Holding (pvt) Ltd', '0115554400', 'https://www.linkedin.com/company/ims-holdings-private-limited', 100, 100, 24, NULL, 'No', 0, '', '2020-01-01', 1, 'Dr.Kawinda Thisera', 'kavindatissera@ahs.pdn.ac.lk', '0812065788', '0702797348', 'Senior Lecture,\r\nDept of MLS                                                      ', NULL, '2587-202110181518449625.jpg', 'Biobase-Air-Jacketed-50-160L-Touch-Screen-Microprocessor-Control-Laboratory-CO2-Incubator.jpg', 'images3.jpg', NULL, 0, 174, '2022-09-09 14:30:59', NULL, NULL, NULL, NULL, NULL),
