(374, 'Gel Doc™ EZ Imager - Bio-Rad', 27, 39, 91, 142, 81, 1, 'Bio-Rad', '', '0000', '', '                                                                                        Gel documentation, or gel imaging, systems are used to record and measure labeled nucleic acid and protein in various types of media such as agarose, acrylamide or cellulose                                                                                                                                                                                                                                                                                                                                      ', 'https://www.bio-rad.com/webroot/web/pdf/lsr/literature/Bulletin_6026A.pdf', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, '', '', '', '', '                                                                                                                                                                                                                                                                                                                                                                                                                        ', NULL, 'lse_geldoc_pd.jpg', 'Bio-Rad-Gel-Doc-EZ-Imager1.jpg', 'Bio-Rad-Gel-Doc-EZ-Imager.jpg', '', 0, 93, '2022-09-10 15:55:31', 93, '2022-09-11 09:18:12', NULL, NULL, NULL),
(375, 'Zeiss Stemi 305 Stereo Microscope', 27, 39, 91, 142, 81, 1, 'Zeiss', '305', '0000', '', '                                            The Zeiss Stemi 305 stereo microscope is mounted on an ergonomic post stand and paired with a dual LED pipe light that attaches to the post stand. This Greenough stereo microscope has a 5:1 zoom for industrial inspection and quality control.                                                                                                                                                                  ', '', '', '', 0.00, 0.00, '', '', 'https://www.zeiss.com/microscopy/en/products/light-microscopes/stereo-and-zoom-microscopes/stemi-305.html#documentation', 0, 0, 0, NULL, 'Yes', 0, 'Government', '0000-00-00', 0, '', '', '', '', '                                         Stereo Microscope;                                         ', NULL, '180_2_.jpg', '180_3_.jpg', '180_5_.jpg', '', 0, 93, '2022-09-11 09:02:16', 93, '2022-09-11 09:18:52', NULL, NULL, NULL),
(376, 'Shaking Water Bath ', 27, 39, 91, 142, 81, 1, 'BIOBASE', 'SWB-C', '0000', '', 'The purpose of a water bath shaker is to steadily shake and mix samples while maintaining a constant temperature. They are used for application such as culturing cells, hybridization, and molecular biology assays.                                                                                                                                                                                                                                                    ', 'https://img.waimaoniu.net/', '', '', 0.00, 0.00, 'BIOBASE', 'export@biobase.com', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'Deshani Perera', 'deshanisanthika@gmail.com	', '', '', 'Water Bath, Shaking Incubator                                                                                                                                                                                                                                                     ', NULL, '2587-202110160940502331.jpg', '2587-202110160940511664.jpg', '2587-202110160940515310.jpg', '', 0, 93, '2022-09-11 09:16:14', 207, '2022-09-30 14:38:14', NULL, NULL, NULL),
(377, 'UV/VIS Nano Spectrophotometer', 27, 39, 91, 142, 81, 1, 'Nabi', '', '0000', '', '                                                                                                                                                                                Nabi – UV/VIS Nano Spectrophotometer is a compact absorbance measuring device that can process cuvettes and micro-volume samples in one instrument, and can measure more precisely and conveniently from single wavelength to spectrum analysis using spectrometer technology.\r\n\r\nIt is a stand-alone system through a 7.0” touch LCD screen, and data can also be easily backed up through USB.                                                                                                                                                                                                                                         ', 'https://pdf.medicalexpo.com/pdf/microdigital-co-ltd/nabi-catalog/118845-243835.html#open843402', '', '', 0.00, 0.00, '', '', 'https://md-best.com/board/bbs/board.php?bo_table=kor_product&wr_id=6', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'Deshani Perera', 'Deshanisanthika@gmail.com', '', '', '                                                                                                                                                                          DNA/RNA, Protein, Cell, End point, Kinetic, Spectrum                                                                                                                                                                ', NULL, '919MFHY2KMMwMcZqP5d.png', 'Screenshot_2022-09-11_101148.jpg', 'thumb-1028343255_sYFmeX5O_ce31397d7dd1d1b9f398c5c83f7e97dee6eaec6d_600x624.png', '', 0, 93, '2022-09-11 10:32:09', 207, '2022-09-12 09:43:12', NULL, NULL, NULL),
