(389, 'Sensitometer', 3, 36, 76, 113, 114, 1, '', 'sensi C', '2018', '', '                                                      Sensitometer for displaying a scale of 21 gray levels on the film\r\n\r\nADVANTAGES :\r\n· No preheating required Operational immediately.\r\n· Powered by standard 1 x 9V Alkaline battery or AC adapter supplied.\r\n· 21 Reference ranges with an accuracy of 0.15 OD between each rung in accordance with DIN 6868/55\r\n· Homogeneity of each level of DD = ± 0.01OD\r\n· Width of each rung: 5mm\r\n· Blue wavelength - 460 nm or Green - 510 nm, according to DIN 6868/2\r\n· Exposure time of 100 ± 30 ms for G (green) and (B) blue modes.\r\n· Repeatability of exposure, D log H inf. ± 0.02\r\n· Stability of exposure, D log H inf. ± 0.02\r\n· Nominal operating temperature 23°C ± 3°C                              ', '', NULL, '', 477894.10, 0.00, '', '', '', 0, 0, 0, NULL, '', 1, 'Faculty Funds', '0000-00-00', 1, '', '', '', '', '                              Sensitometer for displaying a scale of 21 gray levels on the film                                                      ', NULL, 'se.jpg', NULL, NULL, NULL, 1, 177, '2022-09-12 10:00:47', NULL, NULL, 177, '2022-09-12 12:03:14', NULL),
(390, 'Cooling Incubator', 27, 39, 91, 142, 81, 1, 'Huanghua faithful Instrument Co., Ltd', 'SPX-250BIII', '2019', '', '                                            Cooling incubator maintains relatively low temperature inside the chamber ranging from -5 °C to 100 °C. The cooling incubator is specially used for stable incubation processes. The incubator is coated in two layers with mild steel material to ensure the effective protection to the incubator against any external damaging factors.                                                      ', 'http://www.labinstrument.cn/', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'Deshani Perera', 'Deshanisanthika@gmail.com', '', '', '                                         Cooling incubator; tissue culture; plant germination; microorganism culture                                                                                                   ', NULL, 'Capture1.JPG', 'CE-Vertical-Type-Laminar-Flow-Cabinet-CJ-1D-CJ-1S-CJ-2D-_(1)1.jpg', 'One-Person-One-Side-Vertical-Type-Lab-Clean-Cabinet1.jpg', 'One-Person-One-Side-Vertical-Type-Lab-Clean-Cabinet2.jpg', 0, 207, '2022-09-12 10:13:32', 93, '2022-09-12 10:27:54', NULL, NULL, NULL);
