(413, 'pH Meter ', 3, 36, 72, 102, 114, 1, 'APERA', 'pH700', '0000', '', '                                                                                                                                                                        ', 'https://aperainst.com/ph700-benchtop-ph-meter-tester-kit', 'PH700-v3_2_31.pdf', '', 79109.48, 0.00, 'Lab Link PVT Ltd', '02, Bandaranayake Mawatha,  Biyagama Road,  Kelaniya,  Sri Lanka.   +94117208119, +94112991906   info@lablink.lk', 'https://www.lablink.lk/', 0, 0, 0, NULL, 'Yes', 1, 'University Research Grant', '2021-05-03', 1, 'Dr. R.D.V.S.Ranasinghe', ' vindyas@ahs.pdn.ac.lk', '081 206578', '0773 66925', '                                                                                                                                                                     ', NULL, '', '', '', '', 0, 172, '2022-09-12 13:23:29', 172, '2022-09-12 13:37:14', NULL, NULL, NULL),
(414, 'Centrifuge machine', 27, 39, 91, 142, 125, 1, 'HERMLE Labortechnik GmbH', 'Z 216 M', '2018', '', 'A centrifuge is a device that uses centrifugal force to separate various components of a fluid. This is achieved by spinning the fluid at high speed within a container, thereby separating fluids of different densities (e.g. cream from milk) or liquids from solids. It works by causing denser substances and particles to move outward in the radial direction. At the same time, objects that are less dense are displaced and moved to the centre. In a laboratory centrifuge that uses sample tubes, the radial acceleration causes denser particles to settle to the bottom of the tube, while low-density substances rise to the top.                                                                                                                                                                                                                            ', 'https://www.hermle-labortechnik.de/', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'Deshani Perera', 'Deshanisanthika@gmail.com', '', '', 'centrifuging, density, separation                                                                                                                                                                                                                                          ', NULL, '111.jpg', '29.jpg', '38.jpg', '41.png', 0, 207, '2022-09-12 13:33:04', 207, '2022-09-30 15:17:26', NULL, NULL, NULL),
