(417, 'Spectrophotometer', 27, 39, 91, 142, 81, 1, 'RIGOL TECHNOLOGIES', 'Ultra-3660', '0000', '', 'Ultra-3660 UV-VIS Spectrophotometer could help you to accomplish various analysis by its advanced design and user-friendlyinterface. With it’s build-in high resolution color screen and water-proof keyboard, you can easily scan spectrum, monitor kinetic curve, measure unknown sample concentration or even print the report directly via simple operation.                                                                                                                                                                                                                                                                                                  ', 'https://www.scientechworld.com/test-and-measurement-solutions/analytical-solutions/uv-vis-spectrophotometer', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'Deshani Perera', 'Deshanisanthika@gmail.com', '', '', 'Spectrophotometer, UV-Vis, electromagnetic spectrum. colorimetric                                                                                                                                                                                                                                                                                                                           ', NULL, '110.jpg', '28.jpg', '37.jpg', '45.jpg', 0, 207, '2022-09-12 13:38:38', 207, '2022-09-30 15:02:15', NULL, NULL, NULL),
(418, 'Sonicator', 27, 39, 91, 142, 125, 1, 'Labtron Equipment Ltd., UK', 'LUHS-A16', '2021', '', 'Ultrasonic Homogenizer (Sonicator) LUHS-A15 is a table-top, multi-function & multi-purpose unit, comes with 1200 ml of process capacity and adjustable ultrasonic power of 20 to 1200 W. Features 0 to 100°C of temperature control range with adjustable time range and 19.5 to 20.5 kHz frequency with automatic tracking. Incorporated with 4.3 inch TFT touch screen, data storage for up to 20 sets and print function, this unit has self-diagnostic function along with login password protection. With Φ20 mm horn, this ultrasonic homogenizer uses high strength ultrasonic power for cavitation effect in liquid and for material ultrasonic processing with protection against program automatic error, over-load, and over- temperature.                                                                                                                                                                        ', 'https://www.labtron.com/ultrasonic-homogenizer-sonicator/luhs-a15', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'Deshani Perera', 'Deshanisanthika@gmail.com', '', '', '                                                                                                                                                                     ', NULL, '', '', '', '', 0, 207, '2022-09-12 13:42:01', 207, '2022-09-12 14:40:14', NULL, NULL, NULL),
(419, 'Nano spectrophotometer', 27, 39, 91, 142, 81, 1, 'Nabi', '', '0000', '', 'Nabi™ is a miniature UV/Vis spectrophotometer that can measure cuvette and microvolume samples. Using the spectrometer technology, it can accurately and efficiently measure/analyze single wavelengths as well as spectrums.                                                                                                                                                                                                                                                                                                 ', 'https://www.msesupplies.com/products/nabi-ultraviolet-visible-uv-vis-nano-spectrophotometer?variant=39655763869754', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'Deshani Perera', 'Deshanisanthika@gmail.com', '', '', 'nano volume, spectrophotometer, wavelength                                                                                                                                                                                                                                                                                        ', NULL, '237-nabi-nanodrop-1.jpg', 'NABI.jpg', 'Nabi-Uv-Vis-Nano-Spectrophotometer.png', '19.jpg', 0, 207, '2022-09-12 13:44:12', 207, '2022-09-30 14:42:49', NULL, NULL, NULL),
