(421, 'Shaking water bath', 27, 39, 91, 142, 125, 1, 'Biobase Biodustry (Shandong) Co., Ltd', 'SWB-C', '2016', '', 'Stepless speed regulation\r\nHigh-transparency Cover for direct observation of the samples inside\r\nForce convection ensure a better heat mixture and temperature uniformity within the chamber.                                                                                                                                                                   ', 'https://biobase.en.made-in-china.com/product-group/UMLxzonEurYd/Water-Bath-1.html', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'Deshani Perera', 'Deshanisanthika@gmail.com', '', '', '                                                                                                                                                                     ', NULL, 'Biobase-Hot-Sales-Thermostatic-Shaking-Water-Bath.jpg', 'Shz-82-Laboratory-Thermostatic-Shaking-Water-Bath-Flask-Shaker.jpg', '', '', 0, 207, '2022-09-12 13:46:54', 207, '2022-09-12 14:27:35', NULL, NULL, NULL),
(422, 'Rotary Evaporator', 27, 39, 91, 148, 89, 1, 'BIOBASE', 'RE-201D/301/501', '0000', '', 'A rotary evaporator (rotovap) is a device used in chemical laboratories for the efficient and gentle removal of solvents from samples by evaporation.                                                   ', 'https://biobase.en.made-in-china.com/product/iXVEugqPHDcI/China-Biobase-Re-201d-301-501-Rotary-Evaporator-0-120rpm.html', NULL, '', 0.00, 0.00, 'BIOBASE', '', 'https://biobase.en.made-in-china.com/product/iXVEugqPHDcI/China-Biobase-Re-201d-301-501-Rotary-Evaporator-0-120rpm.html', 0, 0, 0, NULL, '', 1, '', '0000-00-00', 0, 'Dishan Subasinghe', 'dishan@sjp.ac.lk', '', '', '                                                                                    ', NULL, 'Biobase-Rotary-Evaporator-with-Vacuum-Pump.jpg', 'Biobase-Re-301-Rotary-Evaporator.jpg', 'Biobase-0-098MPa-Vacuum-Degree-Rotary-Evaporator-with-1L-Collecting-Bottle.jpg', 'Biobase-Vacuum-Distillation-1L-3L-5L-10L-20L-50L-Rotary-Evaporator.jpg', 0, 207, '2022-09-12 13:47:25', NULL, NULL, NULL, NULL, NULL),
(423, 'Microwave oven', 27, 39, 91, 142, 125, 1, 'SINGER', '', '0000', '', 'A microwave oven (commonly referred to as a microwave) is an electric oven that heats and cooks food by exposing it to electromagnetic radiation in the microwave frequency range.[1] This induces polar molecules in the food to rotate and produce thermal energy in a process known as dielectric heating. Microwave ovens heat foods quickly and efficiently because excitation is fairly uniform in the outer 25–38 mm (1–1.5 inches) of a homogeneous, high water content food item.                                                                                                                                                                                                                                         ', 'https://www.singersl.com/', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'Deshani Perera', 'Deshanisanthika@gmail.com', '', '', 'microwave oven, drying sample, electromagnetic radiation                                                                                                                                                                                                                    ', NULL, '18.jpg', '22.PNG', '36.jpg', '43.jpg', 0, 207, '2022-09-12 13:48:49', 207, '2022-09-30 14:36:05', NULL, NULL, NULL),
(424, 'Magnetic stirrer', 27, 39, 91, 142, 81, 1, 'Huanghua Faithful Instrument Co., Ltd', 'SH-4C', '2017', '', 'Heating power and stirring speed is stepless adjustable. With adjustable Thermometer Rack, Stainless Steel Rods and the Stir Bar.\r\n\r\n                                                                                                                                                                                                          ', 'https://www.faithful.cc/', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'Deshani Perera', 'Deshanisanthika@gmail.com', '', '', 'Mixing, magnetic stirrer, homogeneous                                                                                                                                                                                   ', NULL, '11.PNG', '26.jpg', '35.jpg', '41.PNG', 0, 207, '2022-09-12 13:50:59', 207, '2022-09-30 14:17:47', NULL, NULL, NULL),
(425, 'Laboratory refrigerator', 27, 39, 91, 142, 81, 1, 'Haier', 'HRF-220BC-SKD', '2018', '', 'Adjustable set temperature range is 3°C to 16°C. A smart temperature control system keeps the internal temperature variation within ±3°C inside the chamber. The hydrocarbon refrigeration system operates at a much higher efficiency and reduces the energy consumption by about 50 percent.                                                                                                                                                                                                                                                                                                               ', 'https://www.haier.com/pk/refrigerators/', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'Deshani Perera', 'Deshanisanthika@gmail.com', '', '', 'Cooling, refrigerants, preserving                                                                                                                                                                                                                                                                             ', NULL, '1.png', '25.jpg', '', '4.png', 0, 207, '2022-09-12 13:53:14', 207, '2022-09-30 14:07:43', NULL, NULL, NULL),
(426, 'COD reactor and test tube heater', 27, 39, 91, 149, 81, 1, 'HANNA instruments', 'HI839800', '0000', '', '                                                             The test tube heater automatically heats up to the set temperature, holding it until the countdown timer has finished. Once the timer has ended, a beep will sound and the heating element will turn off. The outer casing of the HI839800 remains cool to the touch, even during timed digestion.                                                                                                           ', 'https://www.hannainst.com/hi839800-cod-test-tube-heater.html', '', '', 0.00, 0.00, 'HANNA instruments', '', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'W.P.T .Thathsarani ', 'thathsarani89121@gmail.com', '', '', '                                                                   COD reactor, Test tube heater, Temperature                                                                                                  ', NULL, '20220915_100556.jpg', '20220915_100602.jpg', '20220915_100607.jpg', '20220915_100611.jpg', 0, 207, '2022-09-12 13:53:30', 207, '2022-09-15 12:18:12', NULL, NULL, NULL),
(427, 'Laboratory freezer', 27, 39, 91, 142, 125, 1, 'LABTRON ', '5W1-L15-P', '2021', '', '-25°C Chest Freezer LCF-A12 is a 508 L comprised low temperature biomedical freezer, features -25°C of cooling performance with direct cooling method and manual defrost mode. Incorporated with microprocessor control for -10 to -25°C temperature range and R290 as refrigerant, has CFC-free polyurethane foam technology and 70 mm thick insulating layer. Designed with Powder coated materialized housing and interior, has upward door opening with balancing door hinge. Equipped with digital display and advanced alarm system, also supports turn-on delay and stopping interval protection function, ensures reliable and stable performance under targeted refrigeration.', 'https://www.labtron.com/Freezers', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'Deshani Perera', 'Deshanisanthika@gmail.com', '', '', 'Biomedical freezer; Cooling, defrost mode, low temperature                                                                                                                                                                                          ', NULL, '', '', 'Solar-Eco-Freezer-LSEF-D11-250x250.jpg', 'Solar-freezer-LSF-A11-250x250.jpg', 0, 207, '2022-09-12 13:56:17', 207, '2022-09-30 13:55:10', NULL, NULL, NULL),
(428, 'Advanced Beam Testing Apparatus', 42, 40, 97, 146, 141, 1, 'P.A.Hilton Ltd', 'HSM1cD', '2004', '', '                                                                                                                                                                                                                              For  beam experiments to measure support reactions, deflections and rotations                                                                                                                                                                                                                                                                             ', '', '', '', 0.00, 0.00, 'P.A.Hilton Ltd', 'International +44 1794 388382 Fax No. +44 1794 388129 E-mail: sales@p-a-hilton.co.uk', 'https://www.p-a-hilton.co.uk', 0, 0, 0, NULL, 'Yes', 1, 'Contact the university ', '0000-00-00', 1, 'Ms.Nirosha Dilrangi', 'niroshad@sltc.ac.lk', '0112100500', '', '                                                                                                                           Beam testing, Deflection,  Simply supported, fixed and two-span continuous beams, simple and propped cantilevers                                                                                                                        ', NULL, '11download_(1).jpg', 'download3.jpg', '', '', 0, 219, '2022-09-12 13:56:54', 1, '2022-09-23 10:27:29', NULL, NULL, NULL),
