(438, 'Incubator', 27, 39, 91, 149, 89, 1, 'POL-EKO-APARATORA SP.J.', 'CLW 115 IG SMART', '0000', '', '                                                A laboratory incubator is a heated, insulated box used to grow and maintain microbiological or cell cultures. The incubator maintains optimal temperature, humidity and gaseous content of the atmosphere inside.                                    ', 'https://www.pol-eko.com.pl/model/laboratory-incubator-clw/laboratory-incubator-clw-115/', NULL, '', 0.00, 0.00, 'POL-EKO-APARATORA SP.J.', '', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'W.P.T .Thathsarani ', 'thathsarani89121@gmail.com', '', '', '                                          Incubator,  Microbiological or cell cultures,  Optimal temperature, Humidity                               ', NULL, NULL, NULL, NULL, NULL, 0, 207, '2022-09-12 14:20:11', NULL, NULL, NULL, NULL, NULL),
(439, 'pH Meter', 30, 0, 46, 66, 144, 1, 'Eutech', 'pH 700', '2010', '', '                                            The pH 700 measures pH, mV (ORP), and temperature (ºC or ºF). In addition to these parameters, the Ion 700 features direct ion concentration measurement of various ions (mono and divalent).                                                                                                                                               ', 'https://manualmachine.com/eutechinstruments/ph700/9646655-manual/', '', '', 0.00, 0.00, 'HEMSONS INTERNATIONAL', '+94 772 271 766', 'https://hemsons.lk', 0, 0, 0, NULL, 'Yes', 1, 'Treasury Funds', '0000-00-00', 1, 'Ms.B.P.Udani', 'udani@iim.cmb.ac.lk', '0112692385', '0761941202', '                                           pH/Ion/mV                                                                                                                                                                    ', NULL, 'ph_3.jpg', 'ph_1.jpg', 'ph_2.jpg', '', 0, 83, '2022-09-12 14:21:39', 83, '2022-09-12 15:01:47', NULL, NULL, NULL),
