(441, 'Spray Dryer', 27, 39, 91, 148, 89, 1, 'KODI china', '', '0000', '', 'KODI Spray dryer is a wide applied process in liquid process shaping and drying industry. Particularly it is suitable for producing powder, granule or block solid product from solution, emulsion, suspending liquid and pumped paste liquid. Therefore when the distribution of granule size, final moisture, bulk density, granule shape of finished product must be conformed to accuracy standard, the spray drying is an ideal process.                                                         ', 'https://www.kodichina.com/productshow.asp?pclassname=16&pid=131', NULL, '', 0.00, 0.00, 'KODI', 'service@kodichina.com', 'https://www.kodichina.com', 0, 0, 0, NULL, '', 1, 'World Bank', '0000-00-00', 0, 'Dishan Subasinghe', 'dishan@sjp.ac.lk', '', '', '                                                                                    ', NULL, 'download4.jpg', 'H38530c73f7f04af99a54fd7605fb302cy.jpg', 'Hd06cbf8b75e84b6abf9a7c05d6c90034L.jpg', 'maxresdefault.jpg', 0, 207, '2022-09-12 14:24:21', NULL, NULL, NULL, NULL, NULL),
(442, 'Laminar flow cabinet', 27, 39, 91, 149, 89, 1, 'BIOBASE', 'BBS/V1300', '2021', '', '                           A laminar flow cabinet is a ventilation device used within the lab to provide an aseptic work area that helps protect both the laboratory personnel and the materials they are working with. Hoods are classified as either Class I, II, or III depending on the level of protection they offer.                                                         ', 'https://www.biobase.cc/Vertical-Laminar-Flow-Cabinet-BBS-V1300-BBS-V1800-pd45137422.html', NULL, '', 0.00, 0.00, 'BIOBASE', '', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'W.P.T .Thathsarani ', 'thathsarani89121@gmail.com', '', '', '                                     Laminar flow cabinet,  Ventilation device, Aseptic work area ', NULL, NULL, NULL, NULL, NULL, 0, 207, '2022-09-12 14:26:27', NULL, NULL, NULL, NULL, NULL),
