(452, 'Water Activity Meter', 27, 39, 91, 148, 89, 1, 'MOXA', '', '0000', '', ' Water Activity (aw) Meters measure the unbound water vapor pressures to determine microbial spoilage, chemical and physical stability.                                                                                                 ', 'https://www.google.com/search?q=MOXA+water+activity+meter&sxsrf=ALiCzsbfb3xdd_OMZ7eTKopqsdmTCgwH9w:1662973406565&source=lnms&tbm=isch&sa=X&ved=2ahUKEwji7KzZ8o76AhVp7zgGHdbCC7gQ_AUoAXoECAEQAw&biw=1366&bih=568&dpr=1#imgrc=vrV4eOI7yqLvVM', NULL, '', 0.00, 0.00, 'Moxa', 'https://www.moxa.com/about/Contact_Moxa.aspx', 'https://www.moxa.com', 0, 0, 0, NULL, '', 1, '', '0000-00-00', 0, 'Dishan Subasinghe', 'dishan@sjp.ac.lk', '', '', '                                                                                                                                                                        ', NULL, 'aqualab-series-4te-water-activity-meter-p901-1334_zoom.jpg', '20191212_140937-min_(1).jpg', 'extruder-for-waste-plastic-recycling-250x2501.jpg', '64142-8604589.jpg', 0, 207, '2022-09-12 14:57:33', NULL, NULL, NULL, NULL, NULL),
(453, 'TLC Scanner', 30, 0, 46, 66, 144, 1, 'CAMAG', 'CAMAG TLC scanner 4', '2010', '', '                                                                                        The CAMAG TLC SCANNER 4  is designed for densitometric\r\nmeasurement of thin-layer chromatograms and other objects up\r\nto 200x200 mm in size.                                                                                                                                                                  ', 'https://www.camag.com/product/camag-tlc-scanner-4', '', '', 0.00, 0.00, 'HEMSONS INTERNATIONAL', '+94 772 271 766', 'https://hemsons.lk', 0, 0, 0, NULL, 'Yes', 1, 'Treasury Funds', '0000-00-00', 1, 'Ms.B.P.Udani', 'udani@iim.cmb.ac.lk', '0112692385', '0761941202', ' TLC, calibration, Spectrum, chromatogram                                                                                                                                                                    ', NULL, 'tlc_3.jpg', 'tlc_2.png', '', '', 0, 83, '2022-09-12 15:01:05', 83, '2022-09-12 15:03:40', NULL, NULL, NULL),
(454, 'Laboratory Drying Oven -L series', 42, 40, 97, 146, 173, 1, 'CONTROLS', 'L series', '0000', '', '                                            For  sample preparation and conditioning of construction materials, such as cement, concrete, asphalt, bitumen, rock, soil and aggregate                                                                                                                           ', '', 'CONTROLS-CG-A4-Ovens-L-H-Q-EN-v0_6.pdf', '', 0.00, 0.00, 'Controls', 'Controls Group T +39 02 92184 1 F +39 02 92103 333 E sales@controls-group.com www.controls-group.com', 'https://www.controls-group.com/', 0, 0, 2, NULL, 'Yes', 1, 'Contact the university ', '0000-00-00', 1, 'Ms.Nirosha Dilrangi', 'niroshad@sltc.ac.lk', '', '', '                                           Material conditioning , Temperature control                                                                                                                          ', NULL, 'download_(5.jpg', '', '', '', 0, 219, '2022-09-12 15:09:23', 201, '2022-09-13 12:11:25', NULL, NULL, NULL),
(455, 'Viscosity Meter', 27, 39, 91, 148, 89, 1, 'VEVOR', 'Ndj-9s', '0000', '', 'A viscometer, viscosity meter or rheometer is a measuring instrument used to determine a fluid\'s internal flow resistance or viscosity. The term viscosity typically refers to shear viscosity, i.e., how a material reacts to being sheared.                                                                                 ', 'https://www.vevor.com/viscometer-c_11084/ndj-9s-digital-rotational-viscosity-meter-newton-liquid-viscometer-tester-meter-p_010481636098', NULL, '', 0.00, 0.00, 'VEVOR', '855-385-1880', 'https://www.vevor.com/', 0, 0, 0, NULL, '', 1, '', '0000-00-00', 0, 'Dishan Subasinghe', 'dishan@sjp.ac.lk', '', '', '                                                                                    ', NULL, 'Ndj-5s-Ndj-8s-Ndj-9s-DV-1-High-Stable-Speed-Digital-Rotational-Petroleum-Viscometer-Machine.jpg', 'download5.jpg', 'download_(1)2.jpg', '716iJRFTgJL__SL1500_.jpg', 0, 207, '2022-09-12 15:10:48', NULL, NULL, NULL, NULL, NULL),
(456, 'Electronic Pasta Maker', 27, 39, 91, 148, 89, 1, 'Hamilton Beach', '', '0000', '', '                                            They typically consist of two stainless-steel rollers with adjustable settings, which knead and stretch the pasta dough. Pasta machines are often sold with an additional removable cutter that creates pasta shapes such as spaghetti and linguini.                                                                                                                         ', 'https://www.amazon.com/Hamilton-Beach-86650-Electric-Automatic/dp/B07HJTYLGX', '', '', 0.00, 0.00, 'Hamilton Beach', '', 'https://HamiltonBeach.com', 0, 0, 0, NULL, '', 1, '', '0000-00-00', 0, 'Dishan Subasinghe', 'dishan@sjp.ac.lk', '', '', '                                                                                                                                                                     ', NULL, '512y9+26gmL__AC_SS450_.jpg', 'download_(1)3.jpg', 'download6.jpg', 'pasta-maker-86650-02.jpg', 0, 207, '2022-09-12 15:20:18', 207, '2022-09-12 15:23:31', NULL, NULL, NULL),
(457, 'Bag Mixer', 27, 39, 91, 148, 89, 1, 'Interscience', '', '0000', '', 'The BagMixer paddle blender is used for microbiological analyses in the food, environmental, pharmaceutical, veterinary industries and in public research institutes. It is used for the preparation of samples for quality control of raw materials, products in production and the control of finished products                                                                                    ', 'https://www.interscience.com/IMG/pdf/interscience_bagmixer_400_brochure_en_web.pdf', NULL, '', 0.00, 0.00, 'Interscience', 'info@interscience.com', 'https://www.interscience.com/', 0, 0, 0, NULL, '', 1, '', '0000-00-00', 0, '', '', '', '', '                                                                                    ', NULL, '51Zvxe31hDL.jpg', 'download_(1)4.jpg', 'download_(2).jpg', 'download7.jpg', 0, 207, '2022-09-12 15:28:31', NULL, NULL, NULL, NULL, NULL),
(458, 'DO meter', 27, 39, 91, 149, 89, 1, 'Lutron', 'DO-5519', '0000', '', '                             Dissolved oxygen meters use an electrochemical, polarographic, amperometric, galvanic, or optical sensor to measure the amount of gaseous oxygen dissolved in a water sample. DO is an important water quality parameter that effects marine life, the taste of drinking water, and the corrosiveness of a water sample.                                                       ', 'https://www.amazon.com/Lutron-Electronic-DO-5519-Digital-Oxygen/dp/B0797N9BVX', NULL, '', 0.00, 0.00, 'Lutron', '', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'W.P.T .Thathsarani ', 'thathsarani89121@gmail.com', '', '', '                                                                                    Dissolved oxygen meters,  Dissolved gaseous oxygen, Water sample, Taste of drinking water', NULL, NULL, NULL, NULL, NULL, 0, 207, '2022-09-12 15:31:08', NULL, NULL, NULL, NULL, NULL),
