(461, 'Dehydrator', 27, 39, 91, 148, 89, 1, 'LabTech', '', '0000', '', 'A dehydrator is a small appliance that uses hot air to remove the water from foods like fruits, meats and vegetables. From beef jerky to dehydrated banana chips, easily create your favorite dried foods with a food dehydrator.                                                                                    ', 'https://www.acrossinternational.com/ai-250-c-2-5-cu-ft-7-shelves-max-forced-air-convection-oven-110v.html', NULL, '', 0.00, 0.00, 'LabTech', '', '', 0, 0, 0, NULL, '', 1, '', '0000-00-00', 0, 'Dishan Subasinghe', 'dishan@sjp.ac.lk', '', '', '                                                                                    ', NULL, '41oIu2ZbD9L.jpg', '61lj6MwL2kL__SX425_.jpg', '9070-open.jpg', '9070-front_3__fo19070_1.jpg', 0, 207, '2022-09-12 15:38:00', NULL, NULL, NULL, NULL, NULL),
(462, 'pH meter', 27, 39, 91, 149, 89, 1, 'EUTECH INSTRUMENTS', 'CyberScan PC 650', '0000', '', '                    A pH meter is an instrument used to measure the acidity or alkalinity of a solution - also known as pH. pH is the unit of measure that describes the degree of acidity or alkalinity. It is measured on a scale of 0 to 14.                                                                ', 'http://www.eutechinst.com/pdt-para-multi-cyberscanpc650.html', NULL, '', 0.00, 0.00, 'EUTECH INSTRUMENTS', '', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'W.P.T .Thathsarani ', 'thathsarani89121@gmail.com', '', '', '                    pH meter,  Degree of acidity,  Degree of alkalinity, Temperature                                                  ', NULL, NULL, NULL, NULL, NULL, 0, 207, '2022-09-12 15:38:13', NULL, NULL, NULL, NULL, NULL),
(463, 'Refrigerator', 27, 39, 91, 149, 89, 1, 'ARCTIKO', 'FLEXA PRE440', '0000', '', '                                                                          A  refrigerator is a common laboratory appliance that consists of a thermally insulated compartment and a heat pump (mechanical, electronic, or chemical) which transfers heat from the inside of the unit to its external environment so that the inside is cooled to a temperature below the ambient temperature          ', 'https://www.arctiko.com/products/plus1plus10-c-pharmaceutical-medical-refrigerators/pre-440/', NULL, '', 0.00, 0.00, 'ARCTIKO', '', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'W.P.T .Thathsarani ', 'thathsarani89121@gmail.com', '', '', '                                        Refrigerator, Thermal insulation, Cooling                                                 ', NULL, NULL, NULL, NULL, NULL, 0, 207, '2022-09-12 15:48:05', NULL, NULL, NULL, NULL, NULL),
