(489, 'FT-IR', 2, 0, 2, 202, 160, 1, 'Bruker', 'Tensor II', '2017', '', '                                            Attenuated Total Reflectance (ATR) is the most often used sampling technique. With the Platinum ATR Bruker offers a single reflection diamond ATR accessory that is designed to significantly ease your daily routine. Its ergonomic one-finger clamp mechanism and the unobstructed access simplifies the infrared analysis of solid and liquid samples. A pure diamond crystal design allows measurements in the near, mid- and far Infrared. The extremely robust ATR-assembly allows the application of exceptional high pressure so that even very hard samples can be measured. Furthermore, a high chemical resistance is achieved                                                                                                                            ', '', '', '', 0.00, 0.00, 'Hemsons International (Pte) Ltd', '+94 772 271 766', 'https://hemsons.lk/', 0, 0, 0, NULL, '', 1, 'Government Grant', '0000-00-00', 0, 'Mr Dimuthu Hasantha', 'dimuthuh@iti.lk', '+ 94 11 23', '0714867139', '                                         FT-IR,  Pharmaceuticals                                                                                                                            ', NULL, 'itiftir.jpg', '', '', '', 0, 211, '2022-09-12 22:49:08', 211, '2022-09-13 20:35:27', NULL, NULL, NULL),
(490, 'Double Beam Tensile Machine', 27, 39, 95, 157, 146, 1, '', '', '0000', '', '                                                                                    ', '', NULL, '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, '', 1, 'government fund', '0000-00-00', 0, 'P A D C P Piyarathne', 'chamodi@sjp.ac.lk', '', '', '                                                                                    ', NULL, NULL, NULL, NULL, NULL, 0, 213, '2022-09-12 22:54:32', NULL, NULL, NULL, NULL, NULL),
(491, 'LCMS-MS', 2, 0, 2, 203, 162, 1, 'AB SCIEX', 'AB SCIEX QTRAP 4500', '2014', '', '                                            Known as the LC-MS/MS workhorse, this is the intelligently re-engineered design of the 4000 QTRAP Platform, and sets a new benchmark for robust quantitation and library searching. \r\nThe system is ideal for laboratories requiring ultimate robustness, ruggedness, and reliability for high-throughput screening of many compounds in many samples every day.\r\n                                                                                                                            ', '', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, '', 1, 'Government Grant', '2015-01-01', 0, 'Mr M N A Mubarak', 'dir_ral@iti.lk', '+94 11 237', '+94 71 635', '                                         LCMS-MS, Residue Analysis, Aflatoxins, Pesticides, Histamine, DCD, Melamine, PAHs, PCBs, Phthalates                                                                                                                            ', NULL, 'itilcmsms.png', '', '', '', 0, 211, '2022-09-12 23:01:36', 211, '2022-09-13 20:32:39', NULL, NULL, NULL),
