(627, 'Inductively coupled plasma mass spectrometry (ICP-MS)', 2, 0, 2, 203, 210, 1, 'Agilent', 'Agilent 7900', '2015', '', '<p>The Agilent 7900 ICP-MS (Inductively Coupled Plasma - Mass Spectrometry) is a flexible single quadrupole ICP mass spectrometer that provides the industry&rsquo;s best matrix tolerance, most effective helium collision mode, lowest detection limits, and widest dynamic range. As a result, you can be confident you are reporting accurate data every time, even at trace levels, whatever your sample types. The 7900 ICP Mass Spec provides the highest performance for demanding commercial and industrial applications, with the flexibility needed for research and advanced analysis such as speciation. High sensitivity and fast acquisition of transient signals &ndash; necessary for analysis of single nanoparticles (spICP-MS), single cells, and for laser ablation &ndash; give you the edge over the competition</p>\r\n', '', '', '', 0.00, 0.00, 'Techno Instruments (Pvt) Ltd', ' 0112765557', 'https://www.technoinstruments.com/', 0, 0, 0, '', '', 1, 'Government Grant', '2016-01-01', 0, 'Mr M N A Mubarak', 'dir_ral@iti.lk', '0112379921', '0716353009', '                                                                                                                              ICP-MS, Metal Analysis                                                                                                                                                                                                            ', NULL, '7900_ICP-MS_iti.jpg', 'ICP-MS_ITI.jpg', 'iti_icp.jpg', '', 0, 211, '2022-09-14 09:47:47', 79, '2024-01-29 13:17:52', NULL, NULL, NULL),
(628, 'Shaking Incubator', 3, 34, 139, 174, 139, 1, 'JEIOTECH Co, Ltd.', 'IST - 3075', '0000', '', '                                              This instrument provides a suitable environment for the cultivation of organisms through controlling constant temperature shaking speed. The main uses of this  instrument are cell culture , extraction, solubility studies, hybridization, plasmid purification and protein expression .                                                                                                                        ', '', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, 'Yes', 1, '', '0000-00-00', 1, 'Prof J.A.M.S.Jayatilake', 'sumedhaj@pdn.ac.lk', '081 239724', '', '                                                                                                                                                                     ', NULL, '', '', '', '', 0, 226, '2022-09-14 10:31:13', 226, '2022-09-14 11:28:58', NULL, NULL, NULL),
(629, 'Microscope', 24, 29, 60, 150, 143, 1, 'Carl Zeiss Microscopy GmbH', 'Zeiss Axio Scope A1', '2018', '', '                                                                                                                               Typical tasks and applications \r\n• Imaging and analysis of microstructure of metal materials \r\n• Quantitative microstructure analysis \r\n• Evaluation according to international standards \r\n• Grain size analysis • Multiphase analysis\r\n Get these benefits from ZEISS Axioscope\r\n• Reveal microstructural information using different contrast methods.\r\n• Use brightfield contrast to get information about the overall number, size and shape of features within    a material. \r\n• Enhance grain boundaries and particle edges with darkfield contrast to reveal sharper features and clearer definition of interfaces. \r\n• With Circular Differential Interference Contrast (C-DIC) your sample surface appears as a 3D relief. You can easily detect polishing marks. \r\n• Encoded components assure¬ that you always get the right light intensity and scaling to provide reproducible results.\r\n                                                                                                                            ', '', '', '', 0.00, 0.00, 'Analytical Instruments (Pvt) Ltd', '+94 11 263 9000', '', 0, 0, 0, NULL, '', 1, 'University fund', '0000-00-00', 0, 'Head of the Department', 'hod@mme.ruh.ac.lk', '0912245765', '', '                                                                                                 Microscope                                                                                                                                                     ', NULL, 'Mcp-11.jpg', 'Mcp-111.jpg', 'Mcp-1111.jpg', 'Mcp-11111.jpg', 0, 112, '2022-09-14 10:32:26', 112, '2022-09-14 11:30:55', NULL, NULL, NULL),
