(646, 'Thermal imager ', 24, 29, 60, 150, 143, 1, '', 'testo 871', '0000', '', '                                                                                                                                    The testo 871 thermal imager combines high infrared resolution with professional measuring performance and easy handling. Its high-specification 240 x 180 pixel detector, an integrated digital camera and, last but not least, the innovative functions are the features that impress. The testo Thermography App enables the testo 871 to offer smart thermography to meet professional requirements in industry and trade. The case supplied with the thermal imager means it can be conveniently transported, so it is always there for you when needed.  \r\n\r\nImage resolution : 240 x 180 detector with Super-Resolution feature to give 480 x 360 image quality, 90mK NETD. Fixed-focus 35 degree lens.                                                                                                                                                                                                                                                                 ', '', '', '', 0.00, 0.00, 'Orel cooperation (Pvt) Ltd.', '0114792100', '', 0, 0, 0, NULL, '', 1, 'University fund', '2020-05-19', 0, 'Head of the Department', 'hod@mme.ruh.ac.lk', '0912245765', '', '                                                                                                                                                                    Thermography, Thermal image                                                                                                                                                                                                                                ', NULL, 'T1.jpg', 'T2.jpg', 'T3.jpg', '', 0, 112, '2022-09-14 13:18:24', 112, '2022-09-15 13:29:17', NULL, NULL, NULL),
(647, 'Distilled water plant', 30, 0, 46, 66, 55, 1, 'Stuart', 'D4000', '2017', '', 'The Distinction D4000 is a simple glass water still with a silica sheathed heating element which ensures top purity distillate.                                                                                                                                                      The Distinction is supplied complete with a \'reservoir level control\' which fits into the distillate collecting vessel and will turn off the heating element when the vessel is full. Prevents overflow if the still is inadvertently left switched on when unattended. With two independent safety thermostats to prevent over heating in the event of an interruption to the water supply.\r\n\r\n\r\n                                                                                    ', 'https://cdn.images.fecom-media.com/FE00001775/documents/D4000_D4000_EURO_05_2018.pdf', 'D4000Manual.pdf', '', 0.00, 0.00, 'HEMSONS INTERNATIONAL', '+94 772 271 766', 'https://hemsons.lk', 0, 0, 0, NULL, 'Yes', 1, 'Treasury Funds', '0000-00-00', 1, 'Ms .B. P.Udani', 'udani@iim.cmb.ac.lk', '', '0702438170', 'water distillation                                                                     ', NULL, 'distilled_water_3.jpg', 'distilled_water_2.jpg', 'distilled_water_1.jpg', NULL, 0, 83, '2022-09-14 16:10:15', NULL, NULL, NULL, NULL, NULL),
(648, 'Microplate reader', 30, 0, 46, 66, 144, 1, 'Thermofisher Scientific', 'Multiskan SkyHigh with touchscreen, cuvette and μDrop Duo Plate', '2017', '', '                                            Multiskan SkyHigh Microplate Spectrophotometer is a UV/Vis microplate reader designed to be convenient and easy to use for any photometric absorption or turbidimetric research applications and especially DNA, RNA and protein analysis. This microplate reader is ideal for multi-user environments where a variety of endpoint, kinetic and spectral assays are performed. Multiskan SkyHigh is available in different configurations. Touchscreen models offer the flexibility to use the system as stand-alone, or together with Thermo Scientific™ SkanIt Software for PC control. A model with a cuvette reading option is also available. For convenient data handling, Multiskan SkyHigh has an option to access to Thermo Fisher Connect and Microsoft OneDrive cloud-based tools.                                                                                                                                                                                                            ', '', '', '', 0.00, 0.00, 'Annalytical Instrument', '0773612654', 'http://aipl.lk', 96, 0, 0, NULL, 'yes', 1, 'Treasury Funds', '0000-00-00', 0, 'Ms .B.P.Udani', 'udani@iim.cmb.ac.lk', '0112687063', '0702438170', '                                             96 well plate, Cuvettes , Linearity ,wave length                                                                                                                                                                                                            ', NULL, 'micro_plate_reader_1.jpg', 'micro_plate_reader_4.jpg', 'micro_plate_reader_5.jpg', 'micro_plate_reader_3.jpg', 0, 83, '2022-09-14 16:28:31', 83, '2022-09-22 10:16:40', NULL, NULL, NULL),
