(665, 'HIGH PERFORMANCE LIQUID CHROMOTOGRAPHY', 27, 60, 144, 185, 159, 1, 'Thermo Scientific', 'Ultimate 3000', '0000', '', 'Enjoy cost effective access to automated UHPLC separations in a simple, expandable system. The Thermo Scientific™ UltiMate™ 3000 Basic Automated system offers unique LC and entry level UHPLC capabilities without compromise. The integrated autosampler and thermostatted column compartment deliver retention time precision and the ability to fine tune backpressure, resolution and speed. With adjustable gradient delay volume, quaternary or isocratic pump, and excellent flow stability, the Automated Basic system is perfect for teaching or moderate sample throughput, routine applications.                                                                                                                                                                                                                                                                                                                      ', 'https://www.thermofisher.com/order/catalog/product/IQLAAAGABHFAPBMBFC?SID=srch-srp-IQLAAAGABHFAPBMBFC', '', '', 0.00, 0.00, 'Analytical Instruments PVT LTD', '0112 639000', 'http://www.aipl.lk/', 0, 0, 0, NULL, '', 1, 'NRC', '2022-09-17', 1, 'Dr. Anushka U Rajapaksha', 'anurajapaksha@sjp.ac.lk', '0774125340', '0774125340', 'Pharmaceuticals,  identification, Organic compounds, Liquid analysis                                                                                                                                                                                                                                                                                                                                                                                                                                                             ', NULL, '', '', '', '', 0, 154, '2022-09-15 22:05:40', 154, '2022-09-17 11:28:42', NULL, NULL, '2022-11-02 15:31:53'),
(666, 'MINI CENTRIFUGE – MYSPIN 12', 27, 60, 144, 185, 81, 1, 'Thermoscientific', 'MYSPIN 12', '0000', '', '                                                                                        The Thermo Scientific mySPIN 12 mini centrifuge is designed to give you maximum speed and flexibility in a minimized footprint. Its compact, ergonomic design fits on any workstation and is comfortable and easy for anyone to operate. Safety features help ensure it will not operate when the lid is open, a rotor is jammed, or the unit is out of balance. Ideal for most protocols requiring fast spins (12,500rpm / 9,800 xg), and appropriate for PCR, microfilter cell separation, and HPLC protocols.                                                                                                                                 ', 'https://www.thermofisher.com/order/catalog/product/75004081', '', '	75004081', 2300.00, 0.00, 'Analytical Instruments PVT LTD', '2639000', 'http://www.aipl.lk/', 12, 0, 0, NULL, '', 1, 'UNESCO-TWAS', '2022-09-16', 1, 'Dr. Anushka U Rajapaksha', 'anurajapaksha@sjp.ac.lk', '0774125340', '0774125340', '                                                                                  Centrifuge, Micro-centrifuge, Purification & Isolation                                                                                                                                                                    ', NULL, 'Micro_centrifuges_21.JPG', 'Micro_centrigufe_1.JPG', '', '', 0, 154, '2022-09-16 10:53:29', 154, '2022-09-16 10:56:24', NULL, NULL, NULL),
