(787, 'Auto Level', 27, 39, 94, 264, 206, 1, 'Topcon', 'AT - B3A', '0000', '', '          An automatic level is an optical instrument used to establish or verify points in the same horizontal plane in a process known as leveling and is used in conjunction with a leveling staff to establish the relative heights levels of objects or marks\r\n                                                                            ', 'https://www.topcon.co.jp/en/positioning/products/pdf/AT-B2_AT-B3A_AT-B4A_E.pdf', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, 'yes', 1, 'Accelerating Higher Education Expansion and Development ', '2017-04-29', 1, 'Dr. Sankha Widisinghe', 'sankha@sjp.ac.lk', '', '', '                                                          Survey, Level, Auto level\r\n                                                                                                           ', NULL, 'Auto_level_1_29_09_2022.jpg', 'Auto_level_2_29_09_2022.jpg', 'Auto_level_3_29_09_2022.jpg', 'Auto_level_4_29_09_2022.jpg', 0, 107, '2022-09-29 10:38:50', 107, '2022-09-29 11:24:22', NULL, NULL, NULL),
(788, 'Digital Theodolite', 27, 39, 94, 264, 206, 1, 'Topcon', 'DT - 202', '0000', '', '        Digital theodolites consist of a telescope that is mounted on a base, as well as an electronic readout screen that is used to display horizontal and vertical angles. Digital theodolites are convenient because the digital readouts take the place of traditional graduated circles and this creates more accurate readings.\r\n                                                                                                                                                                ', 'https://www.topcon.co.jp/en/positioning/products/pdf/DT-200_Taiwan_E.pdf', 'DT-200_Taiwan_E.pdf', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, 'yes', 1, 'Accelerating Higher Education Expansion and Development ', '0000-00-00', 0, 'Dr. Sankha Widisinghe', 'sankha@sjp.ac.lk', '', '', '                                                                                 The survey, Horizontal angle, Vertical Angle, Theodolite\r\n                                                                                    ', NULL, 'TL_1_2022_09_29.jpg', 'TL_2_2022_09_29.jpg', 'TL_3_2022_09_29.jpg', 'TL_4_2022_09_29.jpg', 0, 107, '2022-09-29 10:58:10', 107, '2022-09-29 11:25:09', NULL, NULL, NULL),
(789, 'Total Station (On Board)', 27, 39, 94, 264, 206, 1, 'Topcon', 'OS - 101', '0000', '', '                                            Total station is a surveying equipment combination of Electromagnetic Distance Measuring Instrument and electronic theodolite. It is also integrated with microprocessor, electronic data collector and storage system. The instrument can be used to measure horizontal and vertical angles as well as sloping distance of object to the instrument.\r\n                                                                                                                            ', 'https://www.abreco.com.mx/manuales_topografia/teodolitos_estaciones/Topcon/Topcon_OS_series_E.pdf', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, 'yes', 1, 'Accelerating Higher Education Expansion and Development ', '2017-09-29', 0, 'Dr. Sankha Widisinghe', 'sankha@sjp.ac.lk', '', '', '                Survey, Totion Station, Angle Measuring, Distance Measuring\r\n                                                                                                                                                     ', NULL, 'TS_1_2022_09_29.jpg', 'TS_2_2022_09_29.jpg', 'TS_3_2022_09_29.jpg', 'TS_4_2022_09_29.jpg', 0, 107, '2022-09-29 11:23:08', 107, '2022-09-29 11:26:36', NULL, NULL, NULL),
