(800, 'Palm Micro Centrifuge', 27, 39, 91, 142, 81, 1, 'Biologix', '01-800X', '2018', '', '               The Palm Micro Centrifuge is a very small, compact centrifuge ideal for microfiltration and quick spins. Microcentrifuges operate on the principle of sedimentation; the denser substances are moved in the radial direction due to the centripetal acceleration and the liquid components are separated.                                                               ', 'http://biologixgroup.com/', NULL, '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'Deshani Perera', 'deshanisanthika@gmail.com', '', '', '                                                                                    ', NULL, '17.jpg', '24.jpg', '31.PNG', '42.jpg', 0, 207, '2022-09-30 13:29:06', NULL, NULL, NULL, NULL, NULL),
(801, 'Heating block', 27, 39, 91, 142, 81, 1, 'Daihan Scientific', 'MaXtable H10', '2020', '', 'A heat block, otherwise known as a dry bath incubator, is a microprocessor-controlled heating block with heater technology. It’s a safe and convenient tool used to heat samples in flasks, tube, and vials, which is ideal for obtaining consistent results and precise temperature stability. It has a number of features, including a built-in temperature calibration and protection device for safety and reliability, automatic fault detection, and a buzzer alarm function. Additionally, the instrument has a simultaneous time and temperature display with an easy-to-use interface, simplifying laboratory procedures and digital accuracy, and a fast, accurate heating system.                                          ', 'http://www.daihan-sci.com/', NULL, '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'Deshani Perera', 'deshanisanthika@gmail.com', '', '', 'Heat block, temperature stability, heating,  consistency, vials', NULL, '1.PNG', '21.PNG', '34.jpg', NULL, 0, 207, '2022-09-30 13:46:00', NULL, NULL, NULL, NULL, NULL);
