(802, 'Internal Mixer', 27, 60, 113, 226, 156, 1, 'CHAREON TUT CO., LTD', 'MX300 - TQ', '0000', '', '                                                                                         CT Internal Mixer is suitable for many applications:\r\nPolymer and/or rubber compound.\r\nPolymer and/or rubber composite.\r\nPolymer and/or rubber blend.\r\n\r\nCT Internal Mixer is a machine for melt blending that involves the intimate mixing of polymer and additives or between different kinds of polymers over a wide range of shear rates and temperatures. Obtaining the well dispersion, polymer compounds and polymer composites are the proper products to the successful final fabrication.                                                                                                                                                               ', 'http://www.chareontut.com/filesdirectserver/itp1/z_itp_30032021gq52/CTInternalMixerz-z343328868504.pdf', 'CTInternalMixerz-z343328868504.pdf', '', 13.00, 1500.00, 'S & D Associates', '0114 515 544', 'https://sdcheme.com/', 0, 0, 0, NULL, 'Yes', 1, 'Accelerating Higher Education Expansion and Development (AHEAD) ', '0000-00-00', 0, 'Dr. Sampath Gunathilake ', 'sgunathilake@yahoo.com', '', '0704809162', '                                                                                    Internal Mixer                                                                                                                                                                   ', NULL, 'Internal_mixer_web_picture.PNG', '', '', '', 0, 95, '2022-09-30 14:22:53', 95, '2022-09-30 15:09:32', NULL, NULL, NULL),
(803, 'Ultrasonic Homogenizer', 27, 39, 91, 142, 81, 1, 'Labtron Equipment Ltd., UK', 'LUHS-A16', '2020', '', 'Ultrasonic homogenizers can be used to homogenize samples, lyse cells, reduce particle size, extract biological material, refine chemical processes and more, but only with liquid (or mostly liquid) samples. Basically, an ultrasonic homogenizer has a tip which very rapidly vibrates, causing bubbles in the surrounding solution to rapidly form and collapse. This creates shear and shock waves which tear apart cells and particles.                      ', 'https://www.labtron.com/', NULL, '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'Deshani Perera', 'deshanisanthika@gmail.com', '', '', 'Sonicator, homogenizer, ultrasonic                                                               ', NULL, NULL, '27.jpg', NULL, '42.PNG', 0, 207, '2022-09-30 14:54:28', NULL, NULL, NULL, NULL, NULL),
(804, 'Two roll mill ', 27, 60, 113, 226, 156, 1, 'DALIAN D&T RUBBER & PLASTIC MACHINERY CO., LTD', '160', '0000', '', ' Using for rubber or plastic mixing, rubber or plastic sheeting.                                                                                                                                                               ', '', '', '', 0.00, 0.00, 'Camso Loadstar Pvt. LTD ', '0114 837 900', 'https://www.srilankabusiness.com/exporters-directory/company-profiles/camso-loadstar-pvt-ltd/', 0, 0, 0, NULL, 'Yes', 1, 'Donated by Loadstar Pvt. LTD ', '0000-00-00', 0, 'Dr. Sampath Gunathilake ', 'sgunathilake@yahoo.com', '', '0704809162', '                                                                                  Two roll mill      \r\nMixing mill                                                                                                                                                             ', NULL, 'open-mixing-mill-160-5882341.jpg', '', '', '', 0, 95, '2022-09-30 15:08:34', 95, '2022-09-30 15:30:13', NULL, NULL, NULL),
(805, 'Shaking water bath', 27, 39, 91, 142, 81, 1, '', '', '2018', '', 'A water bath is a laboratory equipment that is used to incubate samples at a constant temperature over a long period of time. Shaking Water Baths are ideal for thawing, heating, mixing and shaking samples. Some applications include hybridization, bacterial culturing, cell aeration and molecular biology assays. Capacity can vary between vendors from small bench top models to large, industrial size models. The interior of the shaking water bath should be stainless steel for sanitary and longevity reasons. Water bath is a preferred heat source for heating flammable chemicals instead of an open flame to prevent ignition.                                                  ', '', NULL, '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'Deshani Perera', 'deshanisanthika@gmail.com', '', '', 'incubation, thawing, heating, mixing, constant temperature, long time                                                                       ', NULL, NULL, NULL, NULL, NULL, 0, 207, '2022-09-30 15:09:41', NULL, NULL, NULL, NULL, NULL),
(806, 'Compression molding machine ', 27, 60, 113, 226, 156, 1, 'DALIAN D&T RUBBER & PLASTIC MACHINERY CO., LTD', '400x400', '0000', '', 'Rubber sheets, bush, button manufacturing and curing                                                 ', '', NULL, '', 0.00, 0.00, 'Camso Loadstar Pvt. LTD ', '0114 837 900', 'https://www.srilankabusiness.com/exporters-directory/company-profiles/camso-loadstar-pvt-ltd/', 0, 0, 0, NULL, 'Yes', 1, 'Donated by Loadstar Pvt. LTD ', '0000-00-00', 0, 'Dr. Sampath Gunathilake ', 'sgunathilake@yahoo.com', '', '0704809162', ' Compression mold \r\nRubber press                                                                     ', NULL, NULL, NULL, NULL, NULL, 0, 95, '2022-09-30 15:49:03', NULL, NULL, NULL, NULL, NULL),
(807, 'Distillation apparatus', 27, 39, 91, 142, 81, 1, 'Nuve', 'NS-103', '0000', '', 'Water distiller is a machine which is used to purify water using distillation process, which is related to first boiling impure water after that collecting condensed water in a separate container.                                                           ', 'https://nuve.com.tr/tr', NULL, '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'Deshani Perera', 'deshanisanthika@gmail.com', '', '', 'distillation, water purification, analytical grade                                                                 ', NULL, '13.PNG', '2.png', NULL, '47.jpg', 0, 207, '2022-09-30 15:51:35', NULL, NULL, NULL, NULL, NULL),
(808, 'Atomic Absorption Spectrophotometer ', 43, 0, 217, 294, 55, 1, '', 'NoVAA 400 P', '0000', '', '                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ', '', '', '', 0.00, 0.00, '', '', '', 15, 30, 3, NULL, 'Yes', 1, 'commercial', '0000-00-00', 1, '', '', '', '', '                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       ', NULL, '', '', '', '', 0, 218, '2022-09-30 16:05:47', 1, '2022-12-01 14:59:45', NULL, NULL, NULL),
(809, 'Portable CO2 Analyzer', 27, 39, 91, 142, 127, 1, 'Quentek Designs Pvt. Ltd', 'Model 908', '0000', '', '                                            The Quantek Model 908 CO2 Analyzer is designed for spot measurement and analysis of carbon dioxide levels. Analysis ranges of 0-2000ppm up to 0-100% vol/vol. Simply introduce your sample gas flow into the inlet of the Model 908 portable CO2 analyzer, and see results on the LCD within 15-20 seconds. The inlet accepts a flow rate of 50cc/min to 1000 cc/min. If you don’t have a source of flow or positive pressure, the analyzer can be equipped with an internal pump to draw in sample gas for analysis.                                                                                                                             ', 'https://provo.com.au/industry/quantek-908-portable-co2-analyser/', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'Deshani Perera', 'deshanisanthika@gmail.com', '', '', '                                           Carbon dioxide, Portable, Head space gas analysis, Pressure, Gas flow                                                                                                                     ', NULL, '908-quantek-908-portable-co2-head-space-gas-analyser.jpg', 'f5881cf84c1fde8360e772add374731f.jpg', 'maxresdefault1.jpg', 'Quantek-instruments-Model-905-Oxygen-Analyzer-1-600x600.jpg', 0, 207, '2022-10-01 19:40:08', 207, '2022-10-01 19:41:20', NULL, NULL, NULL),
(810, 'Benchtop pH/ MV meter', 27, 39, 91, 142, 125, 1, 'SPER Scientific Ltd', '1219B77EA', '0000', '', 'Automatic or manual temperature compensation, Automatic or manual ranging, N.I.S.T. buffer recognition, Digital and analog outputs, Min/Max and 99 data points, Data Hold, 5 calibration points, Electrode status indication                                                                                 ', 'https://sperdirect.com/en-ca/products/lcd-display-benchtop-ph-mv-meter-0-to-14-ph-range', NULL, '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'Deshani Perera', 'deshanisanthika@gmail.com', '', '', 'pH,  pH electrode,   buffer recognition,  calibration,  temperature compensation                                            ', NULL, 'raw.jpg', 'H0ebf5384197644ecb6eac91f32aad683U.jpg', NULL, 'H0ebf5384197644ecb6eac91f32aad683U1.jpg', 0, 207, '2022-10-01 20:01:19', NULL, NULL, NULL, NULL, NULL),
(811, 'Flask and container ', 27, 39, 91, 142, 125, 1, 'Day Impex Ltd', '', '0000', '', 'A range of low-cost utility Dewar flasks specially designed for laboratory, hospital and industrial use. Safe for use with all liquid gases and ideal for cold traps.\r\n\r\nHigh-quality borosilicate glass inner flasks, ultra-low evacuated in attractive blue stove-enamelled steel outer container, available in 8 capacities.\r\n\r\nThere are also 4 sizes in this multi-purpose range with models that have an insulated lid, fold-down carrying handle and cushioned base to prevent benchtop damage.                                                                                    ', 'https://www.day-impex.co.uk/laboratory/dilvac-dewar-flasks/', NULL, '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'Deshani Perera', 'deshanisanthika@gmail.com', '', '', ' Liquid gases,   cold traps,    inner flasks,  outer container,   insulated lid                                                                ', NULL, '51-1625-0041_L.jpg', 'blue-dewar-flasks.jpg', 'Blue-Dewar-with-insulated-lid-handle-and-cushion-base.jpg', 'Blue-enamelled-Steel-Dewar-flask-with-wide-and-narrow-mouth.jpg', 0, 207, '2022-10-01 20:15:18', NULL, NULL, NULL, NULL, NULL),
(812, 'Stereo Microscope', 27, 39, 91, 142, 127, 1, 'Euromex', 'SB.1302', '0000', '', ' Euromex BlueLine offers a high-quality range of stereo microscope models, which are specifically meant for laboratory and higher education use\r\n\r\nStereoBlue microscopes are especially developed for laboratory applications, education and greatly appreciated by biologists, entomologists, geologists, mechanical and electronic engineers and other professionals like jewelers and dental technicians. These microscopes are available with dual pair of objectives or zoom objective for magnifications from 3.5x to 135x and incident and transmitted LED illuminations.                                                                                   ', 'https://www.euromex.com/en/products/products/stereo-microscopes/stereo-microscopes-life-science/stereoblue/', NULL, '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'Deshani Perera', 'deshanisanthika@gmail.com', '', '', 'Stereo,  magnifications,   Zoom models, LED illumination,  high resolution                                                                                ', NULL, 'SB_1302_(1).jpg', 'SB_1302.jpg', NULL, 'wpbab44578_05_06.jpg', 0, 207, '2022-10-01 20:32:08', NULL, NULL, NULL, NULL, NULL),
(813, 'Gel Documentation System', 27, 39, 91, 142, 127, 1, 'Bio-Rad Laboratories ', '1708270', '0000', '', 'The Gel Doc EZ System is a compact and automated gel imaging instrument designed to yield publication-quality images and analyzed results with just the push of a button. The Gel Doc EZ System provides unparalleled flexibility with the use of four application-specific trays:\r\n\r\n- UV tray for ethidium bromide staining of DNA gels and fluorescence imaging\r\n- White tray for Coomassie, copper, silver, and zinc stains\r\n- Blue tray for nucleic acid applications with SYBR stains\r\n- Stain-free tray for stain-free imaging with Bio-Rad stain-free gels\r\n\r\nThe intuitive Image Lab Software bundled with the Gel Doc EZ Gel Imaging System includes capabilities such as auto image capture, auto analysis, user preferences, and many other features, making gel imaging and analysis incredibly easy.                                                                                   ', 'https://www.bio-rad.com/en-lk/product/gel-doc-ez-gel-documentation-system?ID=O4950KKG4', NULL, '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'Deshani Perera', 'deshanisanthika@gmail.com', '', '', 'Gel imaging,  Gel documentation,  Image resolution,   Fluorescence                                                                                ', NULL, '170-8270_tn.jpg', 'Bio-Rad-Gel-Doc-EZ-Imager2.jpg', 'geldocez.jpg', 'lse_geldoc_pd1.jpg', 0, 207, '2022-10-02 13:29:46', NULL, NULL, NULL, NULL, NULL),
(814, 'Mini–Shaker', 27, 39, 91, 142, 127, 1, 'BioSan', '', '0000', '', '“Sunflower” 3D Mini–Shaker provides adjustable three-dimensional smooth rotation of the platform and is designed for mixing blood  samples, for minigel staining and destaining, sample washing, blot hybridization reactions.\r\n\r\nMini–Shaker is a compact device with low energy consumption. The use of direct drive and brushless motor allows continuous mixing up to 7 days and ensures reliable, trouble-free operation for more than 2 years.\r\n\r\nNon–slip, temperature resistant, silicone mat located on the shaker’s platform provides stable position for vessels during shaking. The platform is suitable for placing a versatile dimpled PDM mat for different size tubes.\r\n\r\nMini–Shaker can be used in cold rooms or incubators, operating at ambient temperature range +4°C to +40°C.\r\n\r\nOptional dimpled mat PDM prevents different size tubes from rolling around the platform.                                                                                    ', 'https://biosan.lv/products/3d-sunflower-mini-shaker-/', NULL, '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'Deshani Perera', 'deshanisanthika@gmail.com', '', '', 'Speed control range, shaking,   smooth rotation, Fixed tilt angle,  Platform working area                                                                                 ', NULL, '3d_1.png', '3d_op_AIBTtha_JPG_1200x1200_q85.jpg', 'boeco-04400029-icm.jpg', 'boeco-sunflower-mini-shaker-3d-1091.jpg', 0, 207, '2022-10-02 13:43:38', NULL, NULL, NULL, NULL, NULL),
(815, 'DNA electrophoresis kit', 27, 39, 91, 142, 127, 1, 'Cleaver Scientific', '', '0000', '', 'The Education Lab sets from Cleaver Scientific are complete low cost DNA electrophoresis kits. This kit contains all the hardware required to run DNA gels (except the reagents/consumables)\r\n\r\nLab Set 1 Includes:\r\n\r\nnanoPAC-300P, 2 outlet power supply\r\nMini Gel Tank, MSMINI10 X 2\r\nCleaver Pipette -Volume; 2 – 20ul, CV20 X 2\r\nMS7-8-1 X 8 (Gel tank Combs)\r\nCSL-EDUPACK Reagents kit\r\n\r\n\r\nLab Set 2 Includes:\r\n\r\nPowerPro 300, 5 ou8tlet power supply-\r\nMini Gel Tank, MSMINI10 X 4\r\nCleaver Pipette -Volume; 2 – 20ul, CV20 X 4\r\nMS7-8-1 X 16 (Gel tank Combs)\r\nCSL-EDUPACK Reagents kit                                                           ', 'https://www.cleaverscientific.com/electrophoresis-products/labset1/', NULL, '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'Deshani Perera', 'deshanisanthika@gmail.com', '', '', ' Electrophoresis,  DNA,   power supply,  Gel Tank,   sample loading                                                                             ', NULL, 'MULTISUB4-1_WEB_.jpg', 'cleaverscientificpr1-image.jpg', 'MSMINI-3_WEB_.jpg', 'MULTISUB4-1_WEB_1.jpg', 0, 207, '2022-10-02 13:58:37', NULL, NULL, NULL, NULL, NULL),
(816, 'Laminar Flow Cabinet', 27, 39, 91, 142, 81, 1, 'Jinan Biobase Biotech Co., Ltd.', 'BBS-V1300', '2020', '', 'Laminar Flow Cabinet – is used only for sample protection. Laminar Flow Cabinet is a work bench or similar enclosure, which creates a particle-free working environment by taking air through a filtration system and exhausting it across a work surface in a laminar or unidirectional air stream.                                                                                                                       ', 'https://www.biobase.cc/Horizontal-Laminar-Flow-Cabinet-BBS-H1300-BBS-H1800-pd45916495.html', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'Deshani Perera', 'deshanisanthika@gmail.com', '', '', '                                         Airflow Velocity, Pre-filter, Work Surface Height, LED Lamp, UV Lamp, sample protection                                                                                                                            ', NULL, 'Biobase-Vertical-Laminar-Flow-Cabinet-Laminar-Air-Flow-Biosafety-Cabinet.jpg', '84845-8879606.jpg', 'Biobase-BBS-V1800-Vertical-Laminar-Flow-Cabinet.jpg', 'Biobase-Laboratory-Equipment-Air-Protect-Clean-Bench-Vertical-Laminar-Flow-Cabinet.jpg', 0, 207, '2022-10-02 14:13:41', 207, '2022-10-03 11:35:37', NULL, NULL, NULL),
(817, 'Constant temperature Incubator', 27, 39, 91, 142, 127, 1, 'Faithful ', 'PCD-D80000', '0000', '', '                                             1. New panel 5 degree angle, new glass inner door knob switch.\r\n\r\n2. The double door structure adopts high quality glass, easy to observe samples, the door with magnetic strip is easy to be opened and closed, good sealing and open door power-off function.                                                                                                                           ', 'https://www.alibaba.com/product-detail/Faithful-Lab-65L-Constant-temperature-Incubators_60196401679.html', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'Deshani Perera', 'deshanisanthika@gmail.com', '', '', '                                          Incubation,   good sealing, constant temperature,  observing samples                                                                                                                    ', NULL, 'CE-Desktop-Constant-Temperature-Incubator-18L.jpg', 'Constant-Temperature-Incubators-WP25AB-Lab-Incubator.jpg', 'Constant-Temperature-Incubators-WPL-Lab-Incubator.jpg', 'CE-Desktop-Constant-Temperature-Incubator-18L1.jpg', 0, 207, '2022-10-02 14:25:54', 207, '2022-10-03 13:00:26', NULL, NULL, NULL),
(818, 'Autoclave', 27, 39, 91, 142, 81, 1, 'Biobase Biodustry (Shandong) co., Ltd', 'BKQ-BSOII', '2016', '', ' Water inlet filter to keep high water quality/ Optional printer for recording sterilization data/ LED screen display all steps of full process as well as error codes/ Independent quick service window, easy for repairing and maintenance/ Automatic selecting quick or low exhaust to avoid sterilization liquid overflowing/ Sterilization programs for dressings, equipment, rubber, culture medium, waste, etc/ Hand wheel type of quick-open door structure, self-expandable sealing ring, easy operating and safe/Complete process of filling water, dynamic pulse exhaust, heating, sterilizing, draining and drying runs automatically/ Adopting certain temperature (98-102˚C) exhausted method and dynamic pulse exhaust method to completely empty the cold air inside chamber for ensuring steam saturability/ Inner stainless steel water tank for water and steam to circulate inside. Steam does not exhaust during sterilization, so as to keep the outside clean and dry.\r\n                                                                                                                                                                                                                                                                                                                                                                  ', 'https://www.biobase.cc/BIOBASE-BIODUSTY-SHANDONG-Co-Ltd-id3152231.html', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'Deshani Perera', 'deshanisanthika@gmail.com', '', '', 'Autoclave; Wet heat sterilization; Pressure                                                                                                                                                                                                                                       ', NULL, '', '', '', '', 0, 207, '2022-10-03 11:39:18', 207, '2022-10-03 11:44:44', NULL, NULL, NULL),
(819, 'Climate Incubator', 27, 39, 91, 142, 81, 1, 'Biobase Biodustry (Shandong) co., Ltd', 'BJPX-A250', '0000', '', 'An incubator is a device used to grow and maintain microbiological cultures or cell cultures. The incubator maintains optimal temperature, humidity and other conditions such as the CO2 and oxygen content of the atmosphere inside. Incubators are essential for much experimental work in cell biology, microbiology and molecular biology and are used to culture both bacterial and eukaryotic cells. An incubator is made up of a chamber with a regulated temperature. Some incubators also regulate humidity, gas composition, or ventilation within that chamber.                                                    ', 'https://www.biobase.cc/BIOBASE-BIODUSTY-SHANDONG-Co-Ltd/', NULL, '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'Deshani Perera', 'deshanisanthika@gmail.com', '', '', 'Climate incubator; tissue culture; plant germination; microorganism culture                                                 ', NULL, '113.jpg', '23.PNG', '32.PNG', '44.PNG', 0, 207, '2022-10-03 12:02:27', NULL, NULL, NULL, NULL, NULL),
(820, 'Compact microscope', 27, 39, 91, 142, 81, 1, 'Zeiss Primostar', '415500-0057-0000', '0000', '', 'A compound microscope is a high power (high magnification) microscope that uses a compound lens system. A compound microscope has multiple lenses: the objective lens (typically 4x, 10x, 40x or 100x) is compounded (multiplied) by the eyepiece lens (typically 10x) to obtain a high magnification of 40x, 100x, 400x and 1000x. Higher magnification is achieved by using two lenses rather than just a single magnifying lens. While the eyepieces and the objective lenses create high magnification, a condenser beneath the stage focuses the light directly into the sample.                                                ', 'https://www.zeiss.com/microscopy/en/products/light-microscopes/widefield-microscopes/primostar-3.html', NULL, '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, '', 0, 'Government', '0000-00-00', 0, 'Deshani Perera', 'deshanisanthika@gmail.com', '', '', 'magnification; condenser                   ', NULL, '114.jpg', '24.PNG', '310.jpg', '45.PNG', 0, 207, '2022-10-03 12:16:23', NULL, NULL, NULL, NULL, NULL),
(821, 'Atomic Absorption Spectrophotometer (AAS)', 36, 66, 166, 219, 202, 1, 'Analytic Jena', 'Zeenit 700P', '0000', '', '<p>Functioning well. Need to clean mirrors</p>\r\n', '', '', '', 0.00, 0.00, '', '', '', 15, 15, 0, '', 'yes', 0, 'University Capital Allocation', '', 1, 'Head/ Department of Nanoscience Technology', 'dnst@wyb.ac.lk', '0372284780', '', '                                                                                                                                                                                                                                                      ', NULL, 'zeenit_700p.jpg', '', '', '', 0, 307, '2022-10-04 09:59:51', 307, '2022-12-19 08:23:29', NULL, NULL, NULL),
