(957, 'ThermoFisherScientific Antaris II FT- NIR Spectrophotometer', 2, 0, 2, 202, 140, 1, '', '', '0000', '', 'FT- NIR (Fourier Transform – Near Infra-Red) uses the spectral range of 12000 – 3800 cm-1 and providing laboratory-based FT- NIR performance in a ready for plant package.                                                                                                                          ', '', NULL, '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, '', 1, 'ITI funds', '0000-00-00', 0, 'Mr Dimuthu', 'dimuthuh@iti.lk', '011-237980', '', '                                                 •	Organic compounds\r\n•	Food\r\n•	Active ingredients\r\n•	Excipients\r\n                                                                                                                       ', NULL, NULL, NULL, NULL, NULL, 0, 211, '2022-11-30 13:40:58', NULL, NULL, NULL, NULL, NULL),
(958, 'Waters – Aquity UPLC with Aquity  QDA mass  detector', 2, 0, 2, 202, 140, 1, '', '', '0000', '', '                                                                                                                                                                                 Liquid Chromatography – Mass spectrometry is an analytical technique which combines the physical separation capabilities of liquid chromatography with mass analysis capabilities of mass spectrometry. Existing LC-MS system of Industrial technology institute is equipped with Aquity H class quaternary solvent manager, Aquity PDA detector, Aquity H class sample manager and AquityQDA detector.                                                                                                                                                                                                                                             ', '', NULL, '', 0.00, 0.00, '', '', '', 0, 0, 0, NULL, '', 1, 'ITI funds', '0000-00-00', 0, 'Mr Dimuthu', 'dimuthuh@iti.lk', '0112379800', '', '                                                                                                                                                                                  •	Cosmetics\r\n•	Ingredients used in cosmetics\r\n•	Active pharmaceutical ingredients\r\n•	Excipients\r\n                                                                                                                                                                                                                                                  ', NULL, NULL, NULL, NULL, NULL, 0, 211, '2022-11-30 13:50:33', NULL, NULL, NULL, NULL, NULL),
(959, 'Photometric Measurement System (Integrating Sphere, Spectrometer with Software)', 50, 0, 223, 336, 244, 1, 'Labsphere Inc. USA', 'Integrating Sphere - LMS760, Spectrometer - CDS2100 Software - LightMtrix ', '2011', '', '<p>Photometric Measurement System (Integrating Sphere, Spectrometer with Software) can be used to measure the Photometric parameters (Luminous flux, Radiant Flux, CCT, CRI, Chromaticity coordinates and Spectral Flux distribution) of Lamps. Using these measured parameters can calculate the Efficacy, Performance Grading and SDCM of lamps.</p>\r\n', '', '', '', 0.00, 6000.00, '', '', '', 1, 5, 8, '<p>Luminous Flux&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;-&nbsp;100-5000 lm</p>\r\n\r\n<p>Colour temperature&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- 2000-10000K</p>\r\n\r\n<p>Chromaticity Coordinates&nbsp; &nbsp; &nbsp;- CIE 1931, 2Degree xy Chromaticity Diagram</p>\r\n\r\n<p>Colour Rendering Index&nbsp; &nbsp; &nbsp; &nbsp;- 0-100</p>\r\n', 'Yes', 0, 'Capital 2011', '2012-08-13', 1, 'H D C Hettiarachchi', 'dilrukshi@nerdc.lk', '0112236307', '0712270261', '                                                                                                                                                                     Lamp, Light, Instrument, Luminous Flux, Photometric                                                                                                                                                                                                                                                                                            ', NULL, '20221208_091836.jpg', '20221208_091736.jpg', '20221208_092139.jpg', '20221208_092616.jpg', 0, 327, '2022-12-08 11:48:38', 327, '2022-12-12 10:00:40', NULL, NULL, NULL),
(960, 'Power Analyzer', 50, 0, 223, 336, 246, 1, 'ZEZ ZIMMER Electronic Systems GmbH', 'LMG640', '2018', '', '<p>Can be used to measure all electrical parameters related to Voltage, Current, Wattage, Power Factor and Harmonics. 3 power measurement channels are available. The scope function can be used for waveform analysis.</p>\r\n', 'https://www.zes.com/en/Products/Predecessor-Products/Energy-and-Power-Meters/LMG640', '', '', 0.00, 0.00, '', '', '', 0, 0, 8, '<p>Refer Catalog using the below link</p>\r\n\r\n<p>https://www.zes.com/en/Products/Predecessor-Products/Energy-and-Power-Meters/LMG640</p>\r\n', 'Yes', 0, 'Capital 2019', '2019-05-21', 1, 'H D C Hettiarachchi', 'dilrukshi@nerdc.lk', '0112236307', '0712270261', '                                                                                                                                                                                                                                                                                                Power Analyzer, Voltage, Current, Wattage, Power Factor, THD, Harmonics                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               ', NULL, '20221208_092259.jpg', '20221208_092337.jpg', 'DSC08480.JPG', '', 0, 327, '2022-12-08 14:19:21', 327, '2022-12-12 12:26:20', NULL, NULL, NULL),
