(1009, 'Real-Time PCR System', 3, 25, 39, 167, 300, 1, 'Thermo Fisher Scientific ', 'QuantStudio 5 ', '2020', '', '<p>The Applied Biosystems QuantStudio 5 Real-Time PCR System for Human Identification with laptop computer is the latest addition to our human identification (HID) real-time PCR family of products. This instrument is designed for both new and experienced users who need a simple, reliable, and affordable real-time PCR system that doesn&rsquo;t require compromise on performance or quality. When used with our latest advances in quantification chemistry and HID Real-Time PCR Analysis Software, this system offers a sensitive, robust solution for forensic DNA quantification. It also helps prepare laboratories for future quantification technologies. With maximum dye versatility, this HID solution offers accurate, trusted results in a small benchtop footprint.</p>\r\n', 'https://assets.thermofisher.com/TFS-Assets/LSG/manuals/MAN0017162_QS5HIDInstrument_UG.pdf', '', '', 10.00, 0.00, 'Analytical Instruments (Pvt) Ltd', '0112 639 000', 'https://aipl.lk/', 96, 0, 0, '<p><strong>Real-Time PCR applications</strong><br />\r\nReal-time PCR is a flexible technique that can be used for multiple forensic applications:<br />\r\n&bull; Forensic database<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;--Laboratories without direct amplification workflows<br />\r\n&bull; Forensic casework<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;--Confirmatory screening of male DNA<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;--Sexual assault sample workflow<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;--Quality and quantity sample assessment</p>\r\n', 'Yes', 1, 'Food and Agriculture Organization', '', 1, 'Prof. Pradeepa Bandaranayake', 'agbc@agri.pdn.ac.lk', '0812387180', '', '                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ', NULL, '001.jpg', '002.jpg', '', '', 0, 350, '2022-12-20 13:37:42', 1, '2024-08-23 13:37:50', NULL, NULL, NULL),
(1010, 'Cable Locator', 50, 0, 222, 338, 246, 1, 'AXIOMET ', 'AX-T2090', '0000', '', '<table>\r\n	<tbody>\r\n		<tr>\r\n			<td>Non-contact voltage and cable detector</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n', 'https://www.tme.eu/Document/8c7b3a568c2f4c3aae59b1fd99f5935c/INSTR-AX-T2090%20-%20EN.pdf', NULL, '', 0.00, 0.00, '', '', '', 0, 0, 0, '<table border=\"0\" cellpadding=\"5\" cellspacing=\"1\">\r\n	<tbody>\r\n		<tr>\r\n			<td style=\"vertical-align:top\"><strong>Type of tester</strong></td>\r\n			<td style=\"vertical-align:top\">non-contact voltage and cable detector</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"vertical-align:top\"><strong>Kind of display used</strong></td>\r\n			<td style=\"vertical-align:top\">bargraph, LCD</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"vertical-align:top\"><strong>Detected voltage range</strong></td>\r\n			<td style=\"vertical-align:top\">12...400V AC</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"vertical-align:top\"><strong>Freq. range of detect. volt.</strong></td>\r\n			<td style=\"vertical-align:top\">0...60Hz</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"vertical-align:top\"><strong>Output signal</strong></td>\r\n			<td style=\"vertical-align:top\">125kHz</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"vertical-align:top\"><strong>Operating temperature</strong></td>\r\n			<td style=\"vertical-align:top\">0...40&deg;C</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"vertical-align:top\"><strong>Conform to the norm</strong></td>\r\n			<td style=\"vertical-align:top\">EN61010 300V CAT III</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"vertical-align:top\"><strong>Transmitter dimensions</strong></td>\r\n			<td style=\"vertical-align:top\">130x69x32mm</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"vertical-align:top\"><strong>Receiver dimensions</strong></td>\r\n			<td style=\"vertical-align:top\">192x61x37mm</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"vertical-align:top\"><strong>Transmitter weight</strong></td>\r\n			<td style=\"vertical-align:top\">130g</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"vertical-align:top\"><strong>Receiver weight</strong></td>\r\n			<td style=\"vertical-align:top\">180g</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"vertical-align:top\"><strong>Power supply</strong></td>\r\n			<td style=\"vertical-align:top\">battery 6F22 9V x2</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"vertical-align:top\"><strong>Battery/ rechargeable battery</strong></td>\r\n			<td style=\"vertical-align:top\">battery 6F22 9V x2</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"vertical-align:top\"><strong>Pollution degree</strong></td>\r\n			<td style=\"vertical-align:top\">2</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p><strong>Detection</strong>:</p>\r\n\r\n<ul>\r\n	<li>localizes cable routes in ground</li>\r\n	<li>localizes routes of metal pipes for water and central heating systems</li>\r\n	<li>localizes given electric circuit protection</li>\r\n	<li>voltage at depth up to 40cm</li>\r\n	<li>conductors at depth up to 0,5m (2-pole application)</li>\r\n	<li>conductors at depth up to 2m (1-pole application)</li>\r\n</ul>\r\n\r\n<p><strong>Features</strong>:</p>\r\n\r\n<ul>\r\n	<li>automatic power-off</li>\r\n	<li>detects discontinuities and short circuits in cables</li>\r\n	<li>detects cables in walls</li>\r\n	<li>set consisting of transmitter and receiver</li>\r\n</ul>\r\n\r\n<p><strong>Equipment</strong>:</p>\r\n\r\n<ul>\r\n	<li>test probes</li>\r\n	<li>crocodile clips</li>\r\n	<li>test leads Heavy Duty</li>\r\n	<li>hard case</li>\r\n</ul>\r\n', '', 1, 'NERDC', '', 1, 'HoD Electrical Department', 'electrical@nerdc.lk', '', '', '                                                                                    ', NULL, NULL, NULL, NULL, NULL, 0, 301, '2022-12-20 16:12:28', NULL, NULL, NULL, NULL, NULL),
(1011, 'Stereo Microscope( with Image Projection)', 16, 0, 253, 362, 106, 1, 'Germany', 'Zeiss stemi 305', '0000', '', '<p>Stemi 305 is compact, easy-to-use stereo microscope with 5:1 zoom. Everything is integrated: long-living LED illumination for reflected and transmitted light and documentation.</p>\r\n', '', NULL, '', 0.00, 0.00, '', '', '', 0, 0, 0, '', 'Yes', 1, 'Treasury funds', '', 1, 'Dr. Padmini Senanayake', 'padmitri98@yahoo.com', '0522258201', '0718189661', '                                                                                    ', NULL, 'Stereo_microscope_with_image_projection.jpg', NULL, NULL, NULL, 0, 22, '2022-12-20 16:15:46', NULL, NULL, NULL, NULL, NULL),
(1012, 'Light Microscope', 16, 0, 253, 362, 106, 1, 'Euromax, Holand', 'IS1152-PLI', '0000', '', '<p>Configured with an ergonomic tilting head with optional photo attachment the Euromex iScope comes with Plan Achromat Infinity Corrected IOS 4x, 10x, 40x, and 100x oil objectives. The ergonomic tilting head tilts from 5-35 degrees for adjustable and comfortable viewing.&nbsp;The 1.25 N.A. condenser has a full travel range and has a slot to accept sliders. The illumination system is a kohler NeoLED system designed to provide high resolution images.</p>\r\n', '', NULL, '', 0.00, 0.00, '', '', '', 0, 0, 0, '', 'Yes', 1, 'Treasury funds', '', 1, 'Dr. Padmini Senanayake', 'padmitri98@yahoo.com ', '0522258201', '0718189661', '                                                                                    ', NULL, 'Euromax_microscope.jpg', NULL, NULL, NULL, 0, 22, '2022-12-21 09:32:01', NULL, NULL, NULL, NULL, NULL),
