(1040, 'CNC milling machine ', 50, 0, 224, 334, 52, 1, 'DMG MORI SEIKI', 'DMU 125T Hi-dyn', '1998', '', '<p>Manufacturer: Deckel Maho<br />\r\nModel: DMU 125 T<br />\r\nYear of construction: 1998<br />\r\nControl: Mill Plus<br />\r\nTraverse paths: X/Y/Z 1250 mm x 880 mm x 800 mm<br />\r\nSpeed range: 20-12000 rpm<br />\r\nWith the following accessories:<br />\r\nTable size 1500 mm x 1050 mm<br />\r\nSpindle with 12,000 rpm SK 40 (new)<br />\r\n30-fold tool changer<br />\r\nThe machine only processed plastic<br />\r\nchip conveyor<br />\r\nelectr. handwheel<br />\r\ninfrared probe<br />\r\nPrepared for 4 axis divider</p>\r\n', 'http://en.dmgmori.com', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, '<p>Manufacturer: Deckel Maho<br />\r\nModel: DMU 125 T<br />\r\nYear of construction: 1998<br />\r\nControl: Mill Plus<br />\r\nTraverse paths: X/Y/Z 1250 mm x 880 mm x 800 mm<br />\r\nSpeed range: 20-12000 rpm<br />\r\nWith the following accessories:<br />\r\nTable size 1500 mm x 1050 mm<br />\r\nSpindle with 12,000 rpm SK 40 (new)<br />\r\n30-fold tool changer<br />\r\nThe machine only processed plastic<br />\r\nchip conveyor<br />\r\nelectr. handwheel<br />\r\ninfrared probe<br />\r\nPrepared for 4 axis divider</p>\r\n', '', 1, 'ADB', '', 1, 'Mr  Vishvanath ', 'tinerdc@gmail.com', '0112236284', '', '                                                                                                                                                                                                                                                         ', NULL, '', '', '', '', 0, 377, '2022-12-21 11:31:43', 377, '2022-12-21 11:36:51', NULL, NULL, '2022-12-21 15:05:17'),
(1041, 'Roky-DR Rockwell Hardness Tester', 50, 0, 224, 334, 211, 1, 'QUALITEST', 'Rocky- DR Rockwell Hardness Tester', '2010', '', '<p>rocky can be used directly to measure Rockwell hardness and plastic Rockwell hardness.and it canchange the value of Rockwell hardness into HB, HV, HLD, HK value</p>\r\n\r\n<p>automatic loding unloding and measuring result digitally display and automatic printing.</p>\r\n\r\n<p>the tester suitable for the hardness testing of carbon steel, alloy steel, cast iron, non ferrous metal,engineering plastic and etc.</p>\r\n', '', NULL, '', 0.00, 0.00, '', '', '', 0, 0, 0, '<table border=\"1\">\r\n	<tbody>\r\n		<tr>\r\n			<td colspan=\"2\"><strong>Conforms to ASTM E-18, ISO 6508</strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td colspan=\"2\"><strong>Digital readout</strong></td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Hardness Resolution:</strong></td>\r\n			<td>0.1 of Rockwell unit</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Display:</strong></td>\r\n			<td>Matrix backlit LCD</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Languages:</strong></td>\r\n			<td>English, French, German</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Data Entry:</strong></td>\r\n			<td>Membrane keypad, Menu driven</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Load Selection:</strong></td>\r\n			<td>Automatic</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Load duration:</strong></td>\r\n			<td>2 &ndash; 50 seconds, can be adjusted</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Data Output:</strong></td>\r\n			<td>RS232 and USB data output for PC / Printer</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Power supply:</strong></td>\r\n			<td>110/220V 50/60Hz, 4A</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Menu Features:</strong></td>\r\n			<td>- Hardness tolerance setting (Upper and Lower limits)- Conversions: Vickers, Brinell, Rockwell, Superficial, UTS - Statistical data: X-bar, s, max, min - Automatic curvature correction for cylindrical and spherical surfaces</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Frame Deformation</strong><br />\r\n			(ASTM E18-08 Requires less than +/-1%)</td>\r\n			<td style=\"vertical-align:top\">+/- 0.5%</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Transducer Accuracy</strong><br />\r\n			(ASTM E18-08 Requires +/- 1.0&mu;m Regular Rockwell, +/- 0.5&mu;m Superficial Rockwell)</td>\r\n			<td style=\"vertical-align:top\">+/- 0.3&mu;m Regular Rockwell<br />\r\n			+/- 0.5&mu;m Superficial Rockwell</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Repeatability</strong><br />\r\n			(ASTM E18-08 Requires, 1.0, 1.5 up to 2.0 on the HRC scale)</td>\r\n			<td style=\"vertical-align:top\">0.5 up to 1.0 (HRC Scale)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Tolerance of applied force</strong><br />\r\n			(ASTM E18-08 requires&nbsp; 0.6-0.75%)</td>\r\n			<td style=\"vertical-align:top\">Within 0.5%</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Dimensions of testing machine:</strong></td>\r\n			<td>Height 28.4&rdquo; (720mm), Width 8.0&rdquo; (200mm), Depth 21.7&rdquo; (550mm)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Maximum test height:</strong></td>\r\n			<td>8.0&rdquo; (200mm)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Horizontal Space&nbsp;</strong>(from center line):</td>\r\n			<td>6.5&rdquo; (165 mm)</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Net weight:</strong></td>\r\n			<td>220 lbs (100 kg)&nbsp;</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n', '', 1, 'NERD', '', 1, 'Mr  Vishvanath ', 'tinerdc@gmail.com', '0112236284', '', '                                                                                    ', NULL, NULL, NULL, NULL, NULL, 0, 377, '2022-12-21 12:20:08', NULL, NULL, NULL, NULL, '2022-12-21 15:04:43'),
