(1066, 'NMR Spectrometer ', 54, 0, 251, 344, 199, 3, 'Bruker', 'Bruker Ascend 400 NMR spectrometer ', '0000', '', '', '', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, '<p>&bull; UltraShieldTM Plus 9.4T magnet</p>\r\n\r\n<p>&bull; 5 mm BBFOPLUS probe, optimized for X-nuclei direct observation. Broad band in a frequency range between 31P and 15N. This probe has 2H &quot;lock&quot; channel and z gradient that allows us to carry out 2D spectroscopy and hetero correlation 19F/1H and 1H/19F. The BBFOPLUS probe also includes an automated tuning and matching device (ATM).</p>\r\n\r\n<p>&bull; Control temperature unit (from -50 &deg;C to 50 &deg;C)</p>\r\n\r\n<p><strong>Experimental Capabilities</strong></p>\r\n\r\n<p>&bull; 1D spectra 1H, 13C, 31P, 29Si</p>\r\n\r\n<p>&bull; 2D correlation 1H-1H: COSY, NOESY, ROESY, TOCSY</p>\r\n\r\n<p>&bull; 2D correlation 1H-X: HSQC, HMBC, HMQC</p>\r\n\r\n<p>&bull; Diffusion</p>\r\n', 'Yes', 1, 'Ministry of Science', '', 1, 'Ms. Wasana ', 'wasanak@slintec.lk', '0114650529', '0767604249', '                                                                                                                                                                                                                                                      ', NULL, 'NMR.jpg', '', '', '', 0, 373, '2022-12-22 15:17:23', 373, '2022-12-23 00:08:00', NULL, NULL, NULL),
(1067, 'X-ray Photoelectron Spectrometer (XPS)  ', 54, 0, 251, 344, 177, 3, 'Thermo Scientific', 'Thermo ScientificTM ESCALAB Xi+ X-ray Photoelectron Spectrometer (XPS)  ', '0000', '', '', '', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, '', '', 1, 'Ministry of Science', '', 1, 'Ms. Wasana ', 'wasanak@slintec.lk', '0114650529', '0767604249', '                                                                                                                                                                                                                                                                                                                                                                                                                        ', NULL, 'XPS2.png', '', '', '', 0, 373, '2022-12-22 15:27:33', 373, '2022-12-23 00:01:52', NULL, NULL, NULL),
