(1148, 'UV/Vis Spectrophotometer', 7, 6, 27, 476, 51, 1, 'Bibby Scientific Ltd.', 'Jenway 6850 UV/Vis', '0000', '', '<p>Double beam UV/ Visible Spectrophotometer.</p>\r\n', '', '', '', 1966790.00, 0.00, 'Hemsons International Pvt Ltd', '+94112332893', 'https://hemsons.lk', 0, 0, 0, '<table border=\"1\" cellpadding=\"1\" cellspacing=\"1\" style=\"height:80px; width:500px\">\r\n	<tbody>\r\n		<tr>\r\n			<td><strong>Wavelength</strong></td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Range</td>\r\n			<td>190 to 1100nm</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Resolution</td>\r\n			<td>0.1nm</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Accuracy</td>\r\n			<td>+/-0.3nm (at 0.5, 1nm bandwidth) +/-0.5nm (at 2, 4, 5nm bandwidth)</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Repeatability</td>\r\n			<td>+/- 0.2nm</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Photometrics</strong></td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Transmittance</td>\r\n			<td>0 to 200%</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Absorbance</td>\r\n			<td>-0.3 to 3.0A</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Quantitation</strong></td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Range</td>\r\n			<td>0 to 99999</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Data points</td>\r\n			<td>up to 3 wavelength</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Multi-wavelength</strong></td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Range</td>\r\n			<td>0 to 99999</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Data points</td>\r\n			<td>up to 10 wavelength</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Kinetics</strong></td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Measurement time</td>\r\n			<td>up to 12 hours</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Scan interval</td>\r\n			<td>0.1, 0.2, 0.5, 1, 2, 5, 10 or 30 seconds</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Spectrum</strong></td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Range</td>\r\n			<td>Any range between 190 to 1100nm</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Scan speed</td>\r\n			<td>100 to 2000nm/min</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>DNA</strong></td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Protein</strong></td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p>&nbsp;</p>\r\n', 'Yes', 1, 'AHEAD/ ELTA ELSE', '2021-05-20', 0, '', 'agroecologylabrusl@gmail.com', '0252235102', '', '                                         Spectrophotometer, UV/ Visible, Spectrophotometry                                                                                                                                                                                                             ', NULL, 'UV_Vis_Spectrophotometer.jpg', '', '', '', 0, 378, '2023-03-20 14:44:52', 378, '2023-04-03 14:03:51', NULL, NULL, NULL),
(1149, 'Electrical Test Equipment Calibrator', 52, 0, 231, 477, 0, 1, 'Transmille Ltd', '3200', '0000', '', '<p>The Transmille 3200 Series Electrical Calibrator provides fast and safe solutions for calibration of Loop, RCD, PAT&#39;s and insulation testers. Traditional testing practices require many items of test equipment and exposure to hazardous voltages, with a typical multifunction tester taking up to 45 minutes to test.&nbsp;Cost effective calibration can be put into practice easily, providing a fast return on investment.</p>\r\n\r\n<p>PAT testers plug directly into the 3200 IEC inlet socket using the calibrated lead supplied. The earth bond lead clips on to the earth bond post. This terminal is electrically floating with respect to mains earth allowing calibration of PATs which cannot be used on earthed appliances.</p>\r\n\r\n<p>For flash voltage measurement the external adapter allows the HV probe from the PAT to be pushed down onto a measurement point on the adapter.</p>\r\n', '', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, '<ol>\r\n	<li>Insulation Continuity Testers up to 5kV.</li>\r\n	<li>RCCB Testers.&nbsp;&nbsp;</li>\r\n	<li>Earth Testers.&nbsp;</li>\r\n	<li>Withstanding Voltage Testers up to 12kV.&nbsp;</li>\r\n	<li>Loop Testers.</li>\r\n	<li>Hipot Testers.&nbsp;</li>\r\n</ol>\r\n', '', 1, 'NA', '', 1, 'Ms.Vijayasothy Vijayagopal', 'vijayaaccimt@gmail.com, isdaccimt@gmail.com', '0112650678', '', '                                                                                      Insulation Test, RCCB Test, Earth Test, Loop Test, Hipot Test                                                                                                                                                          ', NULL, '', '', '', '', 0, 341, '2023-03-20 15:47:30', 618, '2025-12-18 12:21:44', NULL, NULL, NULL),
(1150, 'Multi-Product Calibrator', 52, 0, 231, 477, 414, 1, 'Fluke Corporation', '5520A', '0000', '', '<p><br />\r\nThe Fluke Model 5520A Multi-Product Calibrator is a precise instrument that calibrates a wide variety of electrical measuring instruments. With the 5520A Calibrator, we can calibrate precision multimeters that measure ac or dc voltage, ac or dc current, ac or dc power, resistance, capacitance, and temperature.</p>\r\n', '', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, '<ol>\r\n	<li>Analog&nbsp; and Digital Multimeters up to 6&nbsp; 1/2&nbsp; digits.</li>\r\n	<li>True RMS high performance hand held multimeters.</li>\r\n	<li>Bench/system Digital Multimeters up to 6&frac12; digits.</li>\r\n	<li>Clamp meters up to 1000A.</li>\r\n	<li>Analog and Digital storage oscilloscopes up to 300MHz.</li>\r\n	<li>Power Analyzers.</li>\r\n	<li>Thermometers -250 to&nbsp; 2316&nbsp; &deg;C, Using&nbsp; B,C,E, J, K, L,N,R,S,T &amp; U Thermocouples.</li>\r\n</ol>\r\n', '', 1, 'NA', '', 1, 'Ms.Vijayasothy Vijayagopal', 'vijayaaccimt@gmail.com, isdaccimt@gmail.com', '0112650678', '', '                                                                                                                                 ac or dc voltage, ac or dc current, ac or dc power, resistance, capacitance, temperature                                                                                                                                                                                                  ', NULL, '', '', '', '', 0, 341, '2023-03-20 15:52:19', 618, '2025-12-18 13:18:54', NULL, NULL, NULL),
(1151, 'Light Measurement System(LMS)', 52, 0, 231, 478, 0, 3, 'Lab sphere ', 'Lab sphere illumia+ LMS100', '2015', '', '<p>LMS laboratory established in the year 2015 to provide services to the customers who are involving import and manufacturing the lamps used for domestic purposes.In there we measure some of electrical &amp; photometric parameters and provide test report.The system contains power source, power analyzer, spectrometer, sphere, power module and relavant softwares.</p>\r\n', '', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, '<table align=\"left\" border=\"1\" cellpadding=\"1\" cellspacing=\"1\" style=\"width:500px\">\r\n	<thead>\r\n		<tr>\r\n			<th scope=\"col\"><strong>Parameter</strong></th>\r\n			<th scope=\"col\"><strong>Range</strong></th>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td style=\"border-bottom:1px solid black; border-left:1px solid black; border-right:1px solid black; border-top:1px solid black; height:30px; width:310px\">\r\n			<p>Wattage (W)</p>\r\n			</td>\r\n			<td>1-100</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:1px solid black; border-left:1px solid black; border-right:1px solid black; border-top:none; height:30px; width:310px\">\r\n			<p>Power Factor (PF)</p>\r\n			</td>\r\n			<td>0.00-1.00</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:1px solid black; border-left:1px solid black; border-right:1px solid black; border-top:none; height:30px; width:310px\">\r\n			<p>Luminous Flux (LF)</p>\r\n			</td>\r\n			<td>50-6000</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:1px solid black; border-left:1px solid black; border-right:1px solid black; border-top:none; height:30px; width:310px\">\r\n			<p>Lamp Voltage</p>\r\n			</td>\r\n			<td>230V <em>∓</em>&nbsp; 0.2%V</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:1px solid black; border-left:1px solid black; border-right:1px solid black; border-top:none; height:30px; width:310px\">\r\n			<p>Lamp Current</p>\r\n			</td>\r\n			<td>5-1000mA</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:1px solid black; border-left:1px solid black; border-right:1px solid black; border-top:none; height:30px; width:310px\">\r\n			<p>Ambient Temperature</p>\r\n			</td>\r\n			<td>25<em>&plusmn;</em>&nbsp;5<em>℃</em></td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:1px solid black; border-left:1px solid black; border-right:1px solid black; border-top:none; height:30px; width:310px\">\r\n			<p>Colour Temperature</p>\r\n			</td>\r\n			<td>1000 K-8000 K</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:1px solid black; border-left:1px solid black; border-right:1px solid black; border-top:none; height:30px; width:310px\">\r\n			<p>Chromaticity Coordinates</p>\r\n			</td>\r\n			<td>CIE 1931</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:1px solid black; border-left:1px solid black; border-right:1px solid black; border-top:none; height:30px; width:310px\">\r\n			<p>Colour Rendering Index</p>\r\n			</td>\r\n			<td>0-100</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:1px solid black; border-left:1px solid black; border-right:1px solid black; border-top:none; height:30px; width:310px\">\r\n			<p>Harmonics</p>\r\n			</td>\r\n			<td>0-300%</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p>&nbsp;</p>\r\n', '', 1, 'NA', '', 1, 'Mr. U. D. Niriella', 'niriellau@gmail.com, isdaccimt@gmail.com', '0112650678', '0772652073', '                                                                                                                                                                                                                                                          light measurement                                                                                                                                                                                                                                                                                                                                ', NULL, '', '', '', '', 0, 341, '2023-03-21 10:30:18', 618, '2025-12-18 12:24:15', NULL, NULL, NULL),
(1152, 'Sieve Shaker', 7, 6, 27, 476, 264, 1, 'Cisa', 'BA200N', '0000', '', '<p>Analysis of Particle size distribution. Solid/ Liquid materials can be sieved through standard test sieves stack with mesh sizes 2, 1, 0.5, 0.25, 0.125 and 0.063 mm</p>\r\n', 'https://www.cisa.net/wp-content/uploads/2020/06/ENG-BA200N.pdf', '', '', 746604.00, 0.00, 'Analytical Instruments (pvt) Ltd', '+94 11 2639000', 'https://www.aipl.lk', 0, 0, 0, '<table border=\"1\" cellpadding=\"1\" cellspacing=\"1\" style=\"width:500px\">\r\n	<tbody>\r\n		<tr>\r\n			<td><span dir=\"ltr\">Type of equipment:</span></td>\r\n			<td><span dir=\"ltr\">Electromagnetic. Compact</span></td>\r\n		</tr>\r\n		<tr>\r\n			<td><span dir=\"ltr\">Type of sieving</span></td>\r\n			<td><span dir=\"ltr\">Dry / Wet</span></td>\r\n		</tr>\r\n		<tr>\r\n			<td><span dir=\"ltr\">Application</span></td>\r\n			<td><span dir=\"ltr\">Granulometric separation</span></td>\r\n		</tr>\r\n		<tr>\r\n			<td><span dir=\"ltr\">Maximum weight of sample</span></td>\r\n			<td><span dir=\"ltr\">3 kg. (Depending on the characteristics of the product)</span></td>\r\n		</tr>\r\n		<tr>\r\n			<td><span dir=\"ltr\">Range of sieving</span></td>\r\n			<td><span dir=\"ltr\">20&mu;m to 125 mm</span></td>\r\n		</tr>\r\n		<tr>\r\n			<td><span dir=\"ltr\">Particle motion</span></td>\r\n			<td><span dir=\"ltr\">Three-dimensional</span></td>\r\n		</tr>\r\n		<tr>\r\n			<td><span dir=\"ltr\">Dynamic of sieving</span></td>\r\n			<td><span dir=\"ltr\">3000/3600 vibrations per minute, depending on the type of electrical</span><br />\r\n			<span dir=\"ltr\">system (50/60 Hz)</span></td>\r\n		</tr>\r\n		<tr>\r\n			<td><span dir=\"ltr\">Maximum vibration amplitude</span></td>\r\n			<td><span dir=\"ltr\">2 mm</span></td>\r\n		</tr>\r\n		<tr>\r\n			<td><span dir=\"ltr\">Time of test</span></td>\r\n			<td><span dir=\"ltr\">1 to 99 minutes</span></td>\r\n		</tr>\r\n		<tr>\r\n			<td><span dir=\"ltr\">Work cycle</span></td>\r\n			<td><span dir=\"ltr\">Continuous / discontinuous mode (with intervals of 10 seconds)</span></td>\r\n		</tr>\r\n		<tr>\r\n			<td><span dir=\"ltr\">Maximum number of sieves</span></td>\r\n			<td><span dir=\"ltr\">8 (&Oslash; 200/203 x 50 mm high)</span><br />\r\n			<span dir=\"ltr\">15 (&Oslash; 200/203 x 25 mm high)</span></td>\r\n		</tr>\r\n		<tr>\r\n			<td><span dir=\"ltr\">Diameter of sieves</span></td>\r\n			<td><span dir=\"ltr\">60 to 203 mm</span></td>\r\n		</tr>\r\n		<tr>\r\n			<td><span dir=\"ltr\">Power</span></td>\r\n			<td><span dir=\"ltr\">450 W</span></td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p>&nbsp;</p>\r\n', 'Yes', 1, 'AHEAD/ ELTA ELSE', '2022-06-01', 0, '', 'agroecologylabrusl@gmail.com', '0252235102', '', '                                         Particle size distribution,    Sieve analysis, test sieves                                                                                                                                                                                                          ', NULL, 'Sieve_shaker.jpg', '', '', '', 0, 378, '2023-03-27 14:53:41', 378, '2023-04-03 14:03:35', NULL, NULL, NULL),
(1153, 'Chlorophyll meter SPAD 502 Plus', 7, 6, 27, 476, 76, 1, 'Konica Minolta', 'SPAD-502Plus', '0000', '', '<p>Cholorophyll meter can be used to determine the amount of chlorophyll present in plant leaves. The amount of chlorophyll present in plant leaves can serve as an indicatorof the everoll condition of the plant itself.</p>\r\n\r\n<p>The SPAD value determined by the SPAD-502Plus provides an indication of the relative amount of chlorophyll present in plant leaves.</p>\r\n', 'https://www.konicaminolta.com/instruments/download/catalog/color/pdf/spad502plus_catalog_eng.pdf', '', '', 498999.00, 0.00, 'Laboratory Solutions International (pvt) Ltd.', '+94332289274', '', 0, 0, 0, '<p><strong><span dir=\"ltr\">Measurement subject</span></strong><span dir=\"ltr\"> </span><span dir=\"ltr\">Crop leaves</span><br />\r\n<strong><span dir=\"ltr\">Measurement method</span></strong><span dir=\"ltr\"> </span><span dir=\"ltr\">Optical density difference at 2 wavelengths</span><br />\r\n<strong><span dir=\"ltr\">Measurement area</span></strong><span dir=\"ltr\"> </span><span dir=\"ltr\">2</span><span dir=\"ltr\"> </span><span dir=\"ltr\">mm&times;3 mm</span><br />\r\n<strong><span dir=\"ltr\">Subject thickness</span></strong><span dir=\"ltr\"> </span><span dir=\"ltr\">1.2 mm maximum</span><br />\r\n<strong><span dir=\"ltr\">Subject insertion depth</span></strong><span dir=\"ltr\"> </span><span dir=\"ltr\">12 mm (with stopper having position adjustable from 0 to 6 mm)</span><br />\r\n<strong><span dir=\"ltr\">Light source</span></strong><span dir=\"ltr\"> </span><span dir=\"ltr\">2 LED elements</span><br />\r\n<strong><span dir=\"ltr\">Receptor</span></strong><span dir=\"ltr\"> </span><span dir=\"ltr\">1 SPD (silicon photodiode)</span><br />\r\n<strong><span dir=\"ltr\">Display</span></strong><span dir=\"ltr\"> </span><span dir=\"ltr\">LCD panel showing 4-digit measurement value (values shown to first decimal place) and 2-digit number of</span><span dir=\"ltr\"> measurements; Trend graph of values in memory can also be shown.</span><br />\r\n<strong><span dir=\"ltr\">Display range</span></strong><span dir=\"ltr\"> </span><span dir=\"ltr\">-9.9 to 199.9 SPAD units</span><br />\r\n<strong><span dir=\"ltr\">Memory function</span></strong><span dir=\"ltr\"> </span><span dir=\"ltr\">Memory capacity for up to 30 values; Calculation/display of average of data in memory also possible</span><br />\r\n<strong><span dir=\"ltr\">Power</span></strong><span dir=\"ltr\"> </span><span dir=\"ltr\">2 AA-size alkaline batteries</span><br />\r\n<strong><span dir=\"ltr\">Battery performance</span></strong><span dir=\"ltr\"> </span><span dir=\"ltr\">More than 20,000 measurements (when using new alkaline batteries under Konica Minolta test conditions)</span><br />\r\n<strong><span dir=\"ltr\">Minumum measurement interval</span></strong><span dir=\"ltr\"> </span><span dir=\"ltr\">Approx. 2 seconds</span><br />\r\n<strong><span dir=\"ltr\">Accuracy</span></strong><span dir=\"ltr\"> </span><span dir=\"ltr\">Within &plusmn;1.0 SPAD units (for SPAD value between 0.0 and 50.0 under normal temperature/humidity)</span><br />\r\n<span dir=\"ltr\">&ldquo;*&rdquo; added to display when measurement exceeds 50.0 SPAD units</span><br />\r\n<span dir=\"ltr\">Repeatability</span><span dir=\"ltr\"> </span><span dir=\"ltr\">Within &plusmn;0.3 SPAD units</span><span dir=\"ltr\"> </span><span dir=\"ltr\">For SPAD value between 0.0 and 50.0 (with no change in sample position)</span><br />\r\n<strong><span dir=\"ltr\">Reproducibility</span></strong><span dir=\"ltr\"> </span><span dir=\"ltr\">Within &plusmn;0.5 SPAD units</span><br />\r\n<strong><span dir=\"ltr\">Temperature drift</span></strong><span dir=\"ltr\"> </span><span dir=\"ltr\">Within &plusmn;0.04 SPAD units/&deg;C</span><br />\r\n<strong><span dir=\"ltr\">Operation temperature/humidity range</span></strong><span dir=\"ltr\"> </span><span dir=\"ltr\">0 to 50&deg;C; Relative humidity of 85% or less (at 35&deg;C) with no condensation</span><br />\r\n<strong><span dir=\"ltr\">Storage temperature/humidity range</span></strong><span dir=\"ltr\"> </span><span dir=\"ltr\">-20 to 55&deg;C; Relative humidity of 85% or less (at 35&deg;C) with no condensation</span><br />\r\n<span dir=\"ltr\"><strong>Size(WxHxD)</strong>, Weight</span><span dir=\"ltr\"> </span><span dir=\"ltr\">78 x 164 x 49 mm, 200g (excluding batteries)</span><br />\r\n<strong><span dir=\"ltr\">Other functions</span></strong><span dir=\"ltr\"> </span><span dir=\"ltr\">Warning buzzer; User compensation factor</span><br />\r\n&nbsp;</p>\r\n', 'Yes', 1, 'AHEAD/ Faculty DP', '2021-04-02', 0, '', 'agroecologylabrusl@gmail.com', '0252235102', '', '                                                                                                                                                                     ', NULL, 'Chlorophyll_meter.jpg', '', '', '', 0, 378, '2023-03-31 08:58:48', 378, '2023-04-03 14:03:20', NULL, NULL, NULL),
(1154, 'Light meter LI-250A', 7, 6, 27, 476, 265, 1, 'LI-COR', 'LI-250A', '0000', '', '<p>Light Meter displays measurements from LI-COR radiation sensors. The LI-250A provides high-resolution reading and conversion of microamp signals from the attached light sensor into suitable light measurement units.</p>\r\n\r\n<p>A quantum sensor measures photosynthetically active radiation (&micro;mol s -1 m-2 of PAR), a pyranometer measures solar radiation (W m-2 ), and a photometric sensor measures illuminance (lux).</p>\r\n', 'https://www.licor.com/env/products/light/light_meter', '', '', 545900.00, 0.00, 'Islandwide Scientific (pvt) Ltd', '+94112681150', '', 0, 0, 0, '<ul>\r\n	<li><strong>Accuracy:</strong>\r\n	<ul>\r\n		<li><strong>25 &deg;C:</strong> Typically &plusmn; 0.4% of reading &plusmn; 3 counts on the least significant digit displayed (all ranges).</li>\r\n		<li><strong>0 - 55 &deg;C:</strong> Typically &plusmn; 0.6% of reading &plusmn; 3 counts on the least significant digit displayed (all ranges).</li>\r\n	</ul>\r\n	</li>\r\n	<li><strong>Range Selection:</strong> Autoranging (3 ranges).</li>\r\n	<li><strong>Linearity:</strong> &plusmn; 0.05%.</li>\r\n	<li><strong>Sensors:</strong> Designed for type &quot;SA&quot; sensors; type &quot;SB&quot; and &quot;SL&quot; sensors with BNC connectors are also compatible when calconnector or millivolt adapter are removed.</li>\r\n	<li><strong>Sensor Calibration:</strong> Each sensor is supplied with a calibration multiplier. Calibration multipliers for two sensors can be stored in memory. Calibration multipliers are entered from the keypad.</li>\r\n	<li><strong>Signal Averaging:</strong> Sensor output can be collected and displayed as a 15-second average (approximately 60 readings). Averages are retained on the display in HOLD mode.</li>\r\n	<li><strong>Display:</strong> LCD display. Updated every 0.5 seconds in Instantaneous mode.</li>\r\n	<li><strong>Battery Life:</strong> 150 hours typical with continuous operation.</li>\r\n	<li><strong>Power Requirement:</strong> One 9V Alkaline battery.</li>\r\n	<li><strong>Operating Conditions:</strong> 0 to 55 &deg;C, 0 to 95% RH (non-condensing).</li>\r\n	<li><strong>Storage Conditions:</strong> -55 to 60 &deg;C, 0 to 95% RH (non-condensing).</li>\r\n	<li><strong>Size:</strong> 14 cm &times; 7.7 cm &times; 3.8 cm (5.5&quot; &times; 3&quot; x1.5&quot;).</li>\r\n	<li><strong>Weight:</strong> 0.26 kg (0.57 lbs).</li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<table>\r\n	<thead>\r\n		<tr>\r\n			<th>Sensor</th>\r\n			<th>Range</th>\r\n			<th>Resolution</th>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<th scope=\"row\">Quantum</th>\r\n			<td>0-199 &micro;mol s-1 m-2<br />\r\n			0-1999<br />\r\n			0-19999</td>\r\n			<td>0.01 &micro;mol s-1 m-2<br />\r\n			0.1<br />\r\n			1</td>\r\n		</tr>\r\n		<tr>\r\n			<th scope=\"row\">Pyranometer</th>\r\n			<td>0-19 W m-2<br />\r\n			0-199<br />\r\n			0-1999</td>\r\n			<td>0.001 W m-2<br />\r\n			0.01<br />\r\n			0.1</td>\r\n		</tr>\r\n		<tr>\r\n			<th scope=\"row\">Photometric</th>\r\n			<td>0-1999 lux<br />\r\n			0-19999 lux<br />\r\n			0-199 klux</td>\r\n			<td>0.1 lux<br />\r\n			1<br />\r\n			0.01 klux</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n', 'Yes', 1, 'HETC/QIG', '2014-07-21', 0, '', 'agroecologylabrusl@gmail.com', '0252235102', '', '                                                                                                                                                                     ', NULL, 'Light_meter.jpg', '', '', '', 0, 378, '2023-03-31 09:51:37', 378, '2023-04-03 14:03:07', NULL, NULL, NULL),
(1155, 'Soil Moisture meter TDR 150', 7, 6, 27, 476, 266, 1, 'Spectrum technologies Inc.', 'Fieldscout TDR 150', '0000', '', '<p>This meter can be used as a field equipment to determine the VWC, EC and Temperature in soil.</p>\r\n', 'https://www.specmeters.com/assets/1/22/TDR_150_Spec_Sheet.pdf', '', '', 280500.00, 0.00, 'Analytical Instruments (pvt) Ltd', '+94 11 2639000', 'https://www.aipl.lk', 0, 0, 0, '<table border=\"1\" cellpadding=\"1\" cellspacing=\"1\" style=\"width:500px\">\r\n	<tbody>\r\n		<tr>\r\n			<td><span dir=\"ltr\">Measurement</span><br />\r\n			<span dir=\"ltr\">Units</span></td>\r\n			<td><span dir=\"ltr\">Percent volumetric water content (VWC)</span><br />\r\n			<span dir=\"ltr\">Period (raw sensor reading)</span><br />\r\n			<span dir=\"ltr\">Electrical Conductivity (EC) in milliSiemens per</span><br />\r\n			<span dir=\"ltr\">centimeter</span></td>\r\n		</tr>\r\n		<tr>\r\n			<td><span dir=\"ltr\">Resolution,</span><br />\r\n			<span dir=\"ltr\">Accuracy and</span><br />\r\n			<span dir=\"ltr\">Range</span></td>\r\n			<td><span dir=\"ltr\">VWC</span><span dir=\"ltr\">: 0.1% increment &plusmn;3.0% @ &lt; 2 mS/cm</span><br />\r\n			<span dir=\"ltr\">0% to Saturation (</span><span dir=\"ltr\">Saturation is typically around</span><br />\r\n			<span dir=\"ltr\">50% volumetric water</span><span dir=\"ltr\">)</span><br />\r\n			<span dir=\"ltr\">EC</span><span dir=\"ltr\">: 0.01 increment ; &plusmn; 0.1 mS/cm; 0</span><span dir=\"ltr\"> </span><span dir=\"ltr\">-</span><span dir=\"ltr\"> </span><span dir=\"ltr\">5.5 range</span><br />\r\n			<span dir=\"ltr\">Temperature</span><span dir=\"ltr\">: 0.2 ̊F (0.1 ̊C) increment ; &plusmn; 1.8 ̊F</span><br />\r\n			<span dir=\"ltr\">(&plusmn; 1 ̊C);</span><span dir=\"ltr\"> </span><span dir=\"ltr\">-</span><span dir=\"ltr\">22 to 140 ̊F</span><span dir=\"ltr\"> </span><span dir=\"ltr\">(</span><span dir=\"ltr\">-</span><span dir=\"ltr\">30 to 60 ̊C)</span><br />\r\n			<span dir=\"ltr\">Thermistor based;</span></td>\r\n		</tr>\r\n		<tr>\r\n			<td><span dir=\"ltr\">Connectivity</span><span dir=\"ltr\"> </span></td>\r\n			<td><span dir=\"ltr\">USB Type A</span></td>\r\n		</tr>\r\n		<tr>\r\n			<td><span dir=\"ltr\">Log Capacity</span></td>\r\n			<td><span dir=\"ltr\">50,000 measurements</span></td>\r\n		</tr>\r\n		<tr>\r\n			<td><span dir=\"ltr\">Power</span></td>\r\n			<td><span dir=\"ltr\">4 AA batteries</span></td>\r\n		</tr>\r\n		<tr>\r\n			<td><span dir=\"ltr\">Available</span><br />\r\n			<span dir=\"ltr\">Rod</span><br />\r\n			<span dir=\"ltr\">Dimensions</span></td>\r\n			<td><span dir=\"ltr\">Turf</span><span dir=\"ltr\"> </span><span dir=\"ltr\">1.5&rdquo; (3.8</span><span dir=\"ltr\"> </span><span dir=\"ltr\">cm)</span><br />\r\n			<span dir=\"ltr\">Medium</span><span dir=\"ltr\"> </span><span dir=\"ltr\">4.8&rdquo; (12.2</span><span dir=\"ltr\"> </span><span dir=\"ltr\">cm)</span></td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p>&nbsp;</p>\r\n', 'Yes', 1, 'AHEAD/ ELTA ELSE', '2021-02-24', 0, '', 'agroecologylabrusl@gmail.com', '0252235102', '', '                                         Soil Moisture, VWC, TDR                                                                                                                            ', NULL, 'Soil_Moisture_meter_TDR_150.jpg', '', '', '', 0, 378, '2023-04-03 10:10:53', 378, '2023-04-03 14:02:32', NULL, NULL, NULL),
(1156, 'Soil Compaction meter', 7, 6, 27, 476, 267, 1, 'Innoquest Inc.', 'Spoton 29360', '0000', '', '<p>This meter can be used to measure the maximum compaction value in soil.</p>\r\n', 'https://innoquestinc.com/product-manuals/digital-soil-compaction-meter-product-manual/', '', '', 182000.00, 0.00, 'Laboratory Solutions International (pvt) Ltd.', '+94332289274', '', 0, 0, 0, '<table border=\"1\" cellpadding=\"1\" cellspacing=\"1\" style=\"width:500px\">\r\n	<tbody>\r\n		<tr>\r\n			<td>Usable Probe Length</td>\r\n			<td>30in (76cm)</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Range</td>\r\n			<td>0 to 825 PSI (0 to 5690 kPa)</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Resolution</td>\r\n			<td>1 PSL (7 kPa)</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Accuracy</td>\r\n			<td>+/- 15 PSI (100kPa)</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Power</td>\r\n			<td>2 AA size batteries</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p>&nbsp;</p>\r\n', 'Yes', 1, 'AHEAD/ ELTA ELSE', '2021-05-17', 0, '', 'agroecologylabrusl@gmail.com', '0252235102', '', 'Soil Compaction                                                                                                                                                                     ', NULL, 'Soil_Compaction_meter.jpg', '', '', '', 0, 378, '2023-04-03 12:13:27', 378, '2023-04-03 14:02:00', NULL, NULL, NULL),
(1157, '-25℃ Freezer', 7, 6, 27, 476, 121, 1, 'Suzhou Being Medical Device Co. Ltd', 'BDW-25L260', '0000', '', '<p>-25℃ Freezer is used for field samples storage</p>\r\n', '', NULL, '', 787590.00, 0.00, 'Research Instruments pvt Ltd.', '', '', 0, 0, 0, '<p>Temperature range〔℃〕:-10 ～ -25</p>\r\n\r\n<p>Effective volume 〔Liters〕 260</p>\r\n', '', 0, 'AHEAD/ ELTA ELSE', '2022-01-10', 0, '', 'agroecologylabrusl@gmail.com', '0252235102', '', '                                                                                    ', NULL, '-20C_freezer_260L.jpg', NULL, NULL, NULL, 0, 378, '2023-04-03 14:45:39', NULL, NULL, NULL, NULL, NULL),
(1158, 'Heating incubator', 7, 6, 27, 476, 269, 1, 'U-Therm International (h.K.) Ltd', 'Lab-kits ETI-LI-600', '0000', '', '<p>Incubator is used as a facility for growth of microorganisms under optimum environmental condition</p>\r\n', '', NULL, '', 440640.00, 0.00, 'Bhoomi-tech (pvt) Ltd.', '0112734551', 'https://www.bhoomitech.com', 0, 0, 0, '<table border=\"1\" cellpadding=\"1\" cellspacing=\"1\" style=\"width:500px\">\r\n	<tbody>\r\n		<tr>\r\n			<td>Temp. Range</td>\r\n			<td>RT +5 - 66 ℃</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Temp. Uniformity</td>\r\n			<td>+/- 1℃</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Temp. Fluctuation</td>\r\n			<td>+/- 0.5℃</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Chamber size (cm)</td>\r\n			<td>60x60x70</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p>&nbsp;</p>\r\n', 'Yes', 1, 'AHEAD/ ELTA ELSE', '2021-11-16', 0, '', 'agroecologylabrusl@gmail.com', '0252235102', '', '                                                                                                                                                                                                                                                            ', NULL, NULL, NULL, NULL, NULL, 0, 378, '2023-04-03 15:34:12', NULL, NULL, NULL, NULL, NULL),
(1159, 'Arc-Spark Optical Emission Spectrophotometer', 2, 0, 2, 479, 164, 1, 'Bruker Scientific', 'Q4 TASMAN 130', '2019', '', '<p>Description/ Function &ndash; Testing chemical composition of Iron, Copper and Aluminium alloys including pure metals complying with international standard specifications (BS, EN, ISO and ASTM). Able to measure Nitrogen in Iron alloys and Oxygen content in pure copper. Only instrument available in Sri Lanka which can measure Oxygen in Pure Copper. Analysis time is less than one minute. Has the ability to test 32 elements in Iron alloys including N, 27 elements in copper alloys including O, 34 elements in Aluminium alloys.</p>\r\n', '', '', '', 18.50, 0.00, 'Hemsons International', '', '', 0, 0, 0, '', 'Yes', 1, 'ITI Capital Budget', '', 0, 'Mr. Kosala Amaranayaka', 'kosalaml@iti.lk', '0112379927', '0702588503', '                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           ', NULL, '', '', '', '', 0, 211, '2023-04-25 11:07:45', 211, '2023-04-25 12:21:34', NULL, NULL, NULL),
(1160, 'Water Vapour Transmission Rate Tester', 2, 0, 2, 479, 0, 1, 'Labthink', 'W3/031', '0000', '', '<p>Water Vapor Transmission Rate Tester is based on the cup method, and is professionally applicable to the water vapor transmission rate test of plastic films, sheets and laminated materials in medical and construction field. Under a certain test temperature, a constant humidity difference is generated between two sides of the test specimen. The water vapor permeates through the specimen and into the dry side. By measuring the weight changes of the test dish in different time, water vapor transmission rate and other parameters can be obtained.</p>\r\n', '', '', '', 0.00, 13.00, '', '', '', 0, 0, 72, '', '', 1, '', '', 1, 'Ms Vindya Munasinghe', 'vindyam@iti.lk', '0112379800', '', '                                                                                                                                                                                                                                                      ', NULL, '', '', '', '', 0, 211, '2023-05-16 12:55:25', 79, '2024-01-30 14:33:56', NULL, NULL, NULL),
(1161, 'Oxygen / Gas Transmission Rate Tester', 2, 0, 2, 479, 272, 1, '', 'G2/132', '2018', '', '<p>This test concerns mainly the plastic flexible films and laminates. The Gas permeability is the ability of a barrier material to allow gases (O2, N2, CO2 etc.) to permeate through it in a specific time. Gas permeability may vary with temperature, humidity, pressure and specimen thickness. G2/132 is based on the differential pressure method and is professionally applicable to the determination of gas permeability of film specimens. It is equipped with three diffusion cells, which could generate test results of three equivalent specimens at one operation.</p>\r\n', '', '', '', 0.00, 13.00, '', '', '', 0, 0, 168, '', '', 1, 'UNIDO', '', 1, 'Ms Vindya Munasinghe', 'vindyam@iti.lk', '0112379800', '', '                                                                                                                                                                     ', NULL, '', '', '', '', 0, 211, '2023-05-16 13:49:57', 79, '2024-01-30 14:36:21', NULL, NULL, NULL),
(1162, 'Colorimeter', 2, 0, 2, 479, 273, 1, 'FRU', 'WR10-8', '0000', '', '<p>The colorimeter is a professional colorimeter designed and produced subject to the relevant national and international standards. The instrument is well designed and features in precision, stability, easy handling, easy to learn and cost-effective. This instrument applies to the color control, color difference control, color difference analysis, sampling testing and online testing for industries such as textile, printing and dyeing, garments, shoes, leather, chemicals, plastics, pigments, paints, inks, metal, photography and toys etc., as well as to the auxiliary color matching during the processes as injection, inking, painting and spraying coating etc.</p>\r\n', '', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, '', '', 1, 'UNIDO ', '', 0, 'Dr H P P S Somasiri', 'adg_ts@iti.lk', '+94 11 237', '', '                                                                                                                                                                                                                                                                                                                                                                                                                              ', NULL, '', '', '', '', 0, 211, '2023-05-16 13:57:23', 79, '2024-01-30 14:40:25', NULL, NULL, NULL),
(1163, 'Lightbooth', 2, 0, 2, 479, 273, 1, '', 'CV-6047', '2019', '', '<p>The&nbsp;Light Booth&nbsp;is an&nbsp;apparatus&nbsp;which simulates&nbsp;lighting&nbsp;conditions. This apparatus is used to test products under a variety of lighting conditions, meaning that the user can accurately show how that product will appear under a variety of conditions independent of&nbsp;environmental&nbsp;influences.&nbsp;Light booths are primarily used in the printing and packaging industry to visually check the appearance of the printing resolution and visual aspects of the printed packaging. It can be used for all packaging materials especially the printed cardboard, paper and flexible films</p>\r\n', '', '', '', 0.00, 1.00, '', '', '', 0, 0, 24, '', '', 1, 'UNIDO ', '', 0, 'Ms Vindya Munasinghe', 'vindyam@iti.lk', '011 237980', '', '                                                                                                                                                                     ', NULL, '', '', '', '', 0, 211, '2023-05-16 14:15:34', 79, '2024-01-30 14:45:59', NULL, NULL, NULL),
(1164, 'Thickness Tester', 2, 0, 2, 479, 274, 1, 'LABTHINK', 'C640M', '2018', '', '<p>This device measures the thickness of packaging materials such as Plastic Films, Sheeting, Foils, Metal sheets (Foil), etc. up to <strong>2 mm thickness.</strong> The material thickness is a measurement which is used during the conception of the packaging product and its specifications.</p>\r\n', '', '', '', 0.00, 1.00, '', '', '', 0, 0, 24, '', '', 1, 'UNIDO ', '', 1, 'Ms Vindya Munasinghe', 'vindyam@iti.lk', '0112379800', '', '                                                                                                                                                                                                                                                      ', NULL, '', '', '', '', 0, 211, '2023-05-16 14:26:15', 79, '2024-01-30 14:52:03', NULL, NULL, NULL),
(1165, 'Environmental Chamber', 2, 0, 2, 479, 275, 1, 'WEWON', 'TH-408', '0000', '', '<p>The environmental test chamber artificially replicates conditions which materials or components might be exposed to. It is also used to accelerate the effects of exposure to the environment. Chamber testing involves exposing packaging materials to various environmental conditions in a controlled setting. Climatic Chamber testing is a broad term used to describe different ways of simulating climate or excessive ambient conditions exposure for a product or a material under laboratory controlled yet accelerated conditions. On the other hand, Thermal Shock testing is used to simulate how materials will react when exposed to changes in extreme climatic conditions, such as going from extremely cold to extremely hot conditions in a very short period of time (usually only few seconds).</p>\r\n', '', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, '', '', 1, 'UNIDO ', '', 1, 'Mr A  A  M  T Adikari', 'dir_ml@iti.lk', '+94 11 237', '', '                                                                                                                                                                                                                                                      ', NULL, '', '', '', '', 0, 211, '2023-05-16 14:35:20', 79, '2024-01-30 16:26:49', NULL, NULL, NULL),
(1166, 'pH meter', 58, 0, 285, 498, 276, 1, '', '', '0000', '', '', '', NULL, '', 0.00, 0.00, '', '', '', 0, 0, 0, '', 'Yes', 1, 'Geological Survey and Mines Bureau', '', 0, 'Mrs. Shamalie Siriwardana', 'analab@gsmb.gov.lk', '0112076582', '0714417525', '                                                                                    ', NULL, NULL, NULL, NULL, NULL, 0, 410, '2023-06-20 14:05:37', NULL, NULL, NULL, NULL, NULL),
(1167, 'ICP-OES', 58, 0, 285, 498, 276, 1, 'Agilant', '5800 ', '0000', '', '', '', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, '', 'Yes ', 1, 'self', '2021-12-30', 1, '', 'analab@gsmb.gov.lk', '0112076582', '0714417505', '                                                                                                                                                                                                                                                                                                                                                                                                                              ', NULL, '', '', '', '', 0, 410, '2023-06-30 11:41:01', 1, '2024-08-22 09:51:42', NULL, NULL, NULL),
