(1169, 'X-Ray Fluorescence Spectrometer ', 58, 0, 285, 498, 277, 1, 'Bruker', 'S8 Tiger', '0000', '', '<p>This wavelength dispersive XRF is used to analyse major trace and some rare earth elements in powdered samples by preparation of fused beads or pressed pellets.</p>\r\n\r\n<p>&nbsp;</p>\r\n', '', NULL, '', 0.00, 0.00, 'Bruker, Germany', '', '', 0, 0, 0, '', 'Yes', 1, 'IAEA/GSMB', '2016-06-07', 0, 'Y P Shamalie Siriwardana', 'analab@gsmb.gov.lk', '0112076582', '0714417505', '                                                                                    ', NULL, NULL, NULL, NULL, NULL, 0, 410, '2023-07-07 13:36:59', NULL, NULL, NULL, NULL, NULL),
(1170, 'X-ray Diffractometer - XRD', 2, 0, 174, 220, 146, 1, 'Rigaku', 'Rigaku Ultima (IV)', '2013', '9022', '<ol>\r\n	<li>Sample analysis (Customer and Research samples)</li>\r\n</ol>\r\n', '', NULL, '', 20.00, 0.00, 'Rigaku Corporation', '+81 3 3479 0618', 'https://www.rigaku.com/', 0, 0, 0, '', 'Yes', 1, 'Capital budget (ITI)', '2023-08-15', 1, 'K S P Karunadasa', 'sujith@iti.lk', '011-237980', '076-710798', '                                                                                    ', NULL, NULL, NULL, NULL, NULL, 0, 211, '2023-07-27 11:17:40', NULL, NULL, NULL, NULL, NULL);
