INSERT INTO `instrument` (`instrument_id`, `instrument_name`, `institute_id`, `faculty_id`, `department_id`, `laboratory_id`, `instrument_type_id`, `condition_id`, `manufacturer`, `model`, `year_of_manufacture`, `accessories`, `inst_description`, `catalog_link`, `catalog_upload`, `catalog_access`, `price`, `service_charge`, `vendor_name`, `vendor_contact`, `vendor_url`, `no_of_samples_per_cycle`, `no_of_samples_per_day`, `total_usage_hour_per_day`, `specification`, `availabiltiy_of_staff`, `external_researchers`, `funding_source`, `date_commencement_operation`, `record_status`, `contact_person_name`, `contact_person_email`, `contact_person_phone_number`, `contact_person_mobile_number`, `inst_keywords`, `p_categories`, `image_upload1`, `image_upload2`, `image_upload3`, `image_upload4`, `isDeleted`, `created_user_id`, `created_date_time`, `updated_user_id`, `updated_date_time`, `deletedBy`, `deleted_date_time`, `record_endDtm`) VALUES
(1282, 'Inductively Coupled Plasma Mass Spectrometer (ICP-MS)', 3, 33, 161, 523, 295, 1, 'Thermo Fisher', 'ICapQc', '2015', '', '<p>Element analyses in any liquid samples (e.g., water, digested solid matter etc.)</p>\r\n', '', '', '', 23971875.00, 0.00, 'Analytical Instruments (Pvt) Ltd', '100, Elvitigala Mawatha, Colombo 8', '', 100, 100, 10, '<p>ICP-MS Thermo ICapQc with Catac ASX 560 autosampler, Thermo flex 2500 Water Chiller, Thermo SC40B1 Vacuum Pump, Dell Computer PC with Monitor&nbsp;&nbsp;</p>\r\n', 'Yes', 1, 'National Research Council (NRC)', '2016-02-03', 1, 'Prof. Rohana Chandrajith', 'rohanac@sci.pdn.ac.lk', '0812394274', '', '                                                                                                                                                                                                                                                                                                                                          water analyses, trace element analyses in any liquid samples,                                                                                                                                                                                                                                                 ', NULL, 'ICPMS(1).jpg', '', '', '', 0, 453, '2024-07-26 11:15:55', 453, '2024-08-02 08:46:22', NULL, NULL, NULL),
(1283, 'Scanning Electron Microscope (SEM)', 3, 33, 161, 524, 296, 1, 'Carl Zeiss', 'EVO LS15', '2014', '', '<p>Observing and obtaining images with magnification over a range of about 6 orders of magnitude from 50 to 200,000 times.</p>\r\n', '', '', '', 57.00, 0.00, 'Analytical Instruments (Pvt) Ltd', '100, Elvitigala Mawatha, Colombo 08', '', 9, 9, 8, '<p>Carl Zeiss EVO LS 15 SEM System, Oxford Inca Xact EDX system, Quorum Gold Coater, Quorum Carbon Coater</p>\r\n', 'Yes', 1, 'University of Peradeniya', '2014-05-20', 1, 'Mr. Danushka Gamage', 'dsashimal@pdn.ac.lk', '0812394270', '', '                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         ', NULL, 'SEM(1).jpg', '', '', '', 0, 453, '2024-07-26 11:35:26', 453, '2024-08-02 07:39:31', NULL, NULL, NULL),
(1284, 'Laser Particle Size Analyzer', 3, 33, 161, 525, 297, 1, 'Anton Paar', 'PSA 1190LD', '2020', '', '<p>Particle size analysis&nbsp;is used to characterise the size distribution of particles in a given sample, such as solid materials, suspensions, emulsions and even aerosols (dry or wet). &nbsp;</p>\r\n', '', '', '', 16000000.00, 0.00, 'Analytical Instruments (Pvt) Ltd', '100, Elvitigala Mawatha, Colombo 08', '', 1, 20, 5, '', 'Yes', 1, 'AHEAD-DOR', '2020-06-18', 1, 'Dr. Nadeesha Koralegedara', 'nadeeshak@sci.pdn.ac.lk', '0981239428', '', '                                                                                                                                                                                                                                                                                                                                                                                                                        ', NULL, 'PSA(1).jpg', '', '', '', 0, 453, '2024-07-26 11:45:18', 453, '2024-08-02 08:40:08', NULL, NULL, NULL),
(1285, 'Epifluorescence Microscope', 3, 33, 161, 525, 296, 1, 'Carl Zeiss', 'Axio Vert with Axio Cam ICC5', '2016', '', '<p>Epifluorescence microscopy is particularly useful when imaging thick samples over 10 &micro;m deep.&nbsp;</p>\r\n', '', '', '', 5786000.00, 0.00, 'Analytical Instruments (Pvt) Ltd', '100, Elvitigala Mawatha, Colombo 08', '', 1, 5, 5, '', 'Yes', 1, 'National Research Council (NRC)', '2016-11-17', 1, 'Prof. Rohana Chandrajith', 'rohanac@sci.pdn.ac.lk', '0812394274', '', '                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             ', NULL, 'EPI(1)1.jpg', '', '', '', 0, 453, '2024-07-26 12:53:26', 453, '2024-08-02 08:43:26', NULL, NULL, NULL),
(1286, 'Microwave Reaction System', 3, 33, 161, 523, 298, 1, 'CEM', 'Mars 6', '2013', '', '<p>Microwave digestion&nbsp;is a technique used to decompose sample material into a solution suitable for quantitative&nbsp;elemental analysis, particularly for heavy metals using ICP-OES, ICP-MS and AAS. &nbsp;</p>\r\n', '', '', '', 5080900.00, 0.00, 'Analytical Instruments (Pvt) Ltd', '100, Elvitigala Mawatha, Colombo 08', '', 12, 12, 6, '<p>CEM MARS 6 digester with EasyPrep Plus High-Pressure vessels operate at 2455 MHz magnetron frequency, output power of 1600W</p>\r\n', 'Yes', 1, 'National Research Council (NRC)', '2013-09-16', 1, 'Prof. Rohana Chandrajith', 'rohanac@sci.pdn.ac.lk', '0812394274', '', '                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ', NULL, 'MWD(1).jpg', '', '', '', 0, 453, '2024-07-26 13:14:19', 453, '2024-08-02 07:38:59', NULL, NULL, NULL),
(1287, 'Atomic Absorption Spectrometer', 36, 79, 248, 352, 199, 3, 'Thermo Fisher Scientific', 'iCE 3000', '0000', '', '<p>The Thermo Scientific&trade; iCE&trade; 3000 Series&nbsp;AAS&nbsp;enables simple measurement of elements in a wide range of samples such as Water, Soil, Sludge, Milk, Fertilizer, Animal Feed, Forages. The flame atomizer is ideal for the measurement of high concentration samples, whilst the furnace atomizer achieves sub ppb detection.</p>\r\n', 'https://assets.thermofisher.com/TFS-Assets/CMD/brochures/br-44364-aas-ice-3000-br44364-en.pdf', '', '', 0.00, 0.00, 'Analytical Instrument (Pvt)Ltd', '', '', 60, 0, 0, '<p>iCE 3300 Spectrometer</p>\r\n\r\n<p>AA Spectrometer with wide range photomultiplier.</p>\r\n\r\n<p>6 Lamp Automatic Carousel.</p>\r\n\r\n<p>Flame and/or Furnace options available.</p>\r\n\r\n<p>Light Source</p>\r\n\r\n<p>Single or multi-element hollow cathode lamps.</p>\r\n\r\n<p>Uncoded and Data Coded hollow cathode lamps.</p>\r\n\r\n<p>6 independent lamp supplies, each providing 0 to 20 mA.</p>\r\n\r\n<p>Wavelength Range</p>\r\n\r\n<p>180 nm to 900 nm.</p>\r\n\r\n<p>Data/Control Systems</p>\r\n\r\n<p>Spectrometer</p>\r\n\r\n<p>512 kB Flash PROM.</p>\r\n\r\n<p>256 kB RAM.</p>\r\n\r\n<p>3 general purpose RS232C ports.</p>\r\n\r\n<p>USB Port</p>\r\n\r\n<p>Monochromator</p>\r\n\r\n<p>Ebert configuation with nominal 0.2, 0.5 and 1.0 nm spectral</p>\r\n\r\n<p>bandwidths.</p>\r\n\r\n<p>Half height slit settings available.</p>\r\n\r\n<p>Reciprocal linear dispersion 1.5 to 2.0 nm/mm.</p>\r\n\r\n<p>Focal length 270 mm.</p>\r\n\r\n<p>Grating</p>\r\n\r\n<p>1800 l/mm</p>\r\n\r\n<p>Absorbance Range</p>\r\n\r\n<p>-0.150 A to 3.000 A (including background signal).</p>\r\n\r\n<p>Background Correction</p>\r\n\r\n<p>Quadline (continuum source) is standard on all spectrometers.</p>\r\n\r\n<p>Background signals &lt;2 A corrected to &lt;2 %.</p>\r\n\r\n<p>Total signal up to 3 A.</p>\r\n\r\n<p>Gas Control</p>\r\n\r\n<p>Fuel Flow Range</p>\r\n\r\n<p>Air/Acetylene - 0.8 to 2.3 l/min.</p>\r\n\r\n<p>Nitrous Oxide/Acetylene - 3.6 to 5.1 l/min.</p>\r\n', 'Yes', 1, 'UGC Special Grant', '', 1, 'HOD- Dr. (Mrs.) H.N.N. Dilrukshi, Technical Officer - Mrs. Wajira Ginigaddara', 'nadeeshadilrukshi@wyb.ac.lk , wajiraginigaddara@gmail.com', '0312299873', '', '                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             ', NULL, 'Screenshot_2024-07-29_at_17_24_21.png', 'Screenshot_2024-07-29_at_17_25_49.png', 'Screenshot_2024-07-29_at_17_26_07.png', '', 0, 344, '2024-07-29 17:15:52', 344, '2024-07-29 17:39:15', NULL, NULL, NULL),
(1288, 'Ion chromatograph,', 3, 33, 161, 523, 299, 1, 'Thermo (Dionex', 'ICS 1100', '2015', '', '<p>Analyses of water samples for anions.</p>\r\n', '', '', '', 2840179.00, 0.00, 'Analytical Instruments (Pvt) Ltd.', '100, Elvitigala Mawatha, Colombo 8', '', 1, 10, 8, '<p>Ion Chromatograph ICS1100; Anion Colum AS12A; Anion Gard Column AG12A; Anion Suppressor AERS 500; Instrument Software_Chromeleon 72</p>\r\n', 'Yes', 1, 'Alexander von Humboldt Foundation (Germany)', '92015-09-10', 1, 'Prof. Rohana Chandrajith', 'rohanac@sci.pdn.ac.lk', '', '', '                                                                                                                                                                      anion analyses, water quality                                                                                ', NULL, 'IC.jpg', '', '', '', 0, 453, '2024-07-31 09:33:41', 453, '2024-07-31 10:14:18', NULL, NULL, NULL),
(1289, 'Atomic Absorption Spectrmeter', 3, 33, 161, 523, 299, 1, 'Varian', '240FS', '2019', '', '<p>Analyses of water samples for major cations and Hg and As in ppb level using hydride generation method</p>\r\n', '', '', '', 40110.00, 0.00, 'Analytical Instruments (Pvt) Ltd', '100, Elvitigala Mawatha, Colombo 8', '', 1, 100, 8, '<p>AAS with hydride generator (VGA 77), Varian Mark 7 burner and 25 HCL (Al, As, Cd, Ca, Cr, Co, Cu, Au, Fe, Pb, Mg, Mn, Hg, Mo, Ni, Nb, K, Rb, Se, Si, Na, Sr, Ti, V, Zn)</p>\r\n', 'Yes', 1, 'Alexander von Humboldt Foundation (Germany)', '2009-07-07', 1, 'Prof. Rohana Chandrajith', 'rohanac@sci.pdn.ac.lk', '', '', '                                                                                                                                                                      water quality analyses, trace metals, cation analyses, hydride generator                                                                                ', NULL, 'AAS(1).jpg', '', '', '', 0, 453, '2024-07-31 09:55:37', 453, '2024-08-02 08:39:08', NULL, NULL, NULL),
(1290, 'Sieve Shaker', 3, 33, 161, 260, 297, 1, 'Matest', 'YGM15418', '2009', '', '<p>Sieving solid samples (soil, sediment etc,) based on grain size</p>\r\n', '', '', '', 328916.00, 0.00, 'Analytical Instruments (Pvt) Ltd', '100, Elvitigala Mawatha, Colombo 8', '', 1, 25, 8, '<p>Shaker with different sieve sizes</p>\r\n', 'yes', 1, 'University of Peradeniya', '2009-11-13', 1, 'Mr. Nishantha Weerakoon', 'nishanthaw@sci.pdn.ac.lk', '0812394276', '', '                                                                                                                                                                   ', NULL, 'SS(1).jpg', '', '', '', 0, 453, '2024-07-31 13:15:38', 453, '2024-08-02 08:38:50', NULL, NULL, NULL),
(1291, 'Planetary Ball Mill', 3, 33, 161, 260, 300, 1, 'Fritsch', 'Pulverisette 6', '2008', '', '<p>Powdering solid samples.</p>\r\n', '', NULL, '', 2196913.98, 0.00, 'Analytical Instruments (Pvt) Ltd', '100, Elvitigala Mawatha, Colombo 8', '', 0, 0, 0, '', 'yes', 1, 'University of Peradeniya', '2008-10-23', 1, 'Mr. Nishantha Weerakoon', 'nishanthaw@sci.pdn.ac.lk', '0812394276', '', '                                                                                    ', NULL, 'ball_mill.jpg', NULL, NULL, NULL, 0, 453, '2024-07-31 13:19:53', NULL, NULL, NULL, NULL, NULL),
(1292, 'Muffle Furnace', 3, 33, 161, 260, 300, 1, 'Hobersal', 'HD230', '2006', '', '<p>Fusing samples at high temperature (upto 1200 C)</p>\r\n', '', NULL, '', 275516.50, 0.00, 'Analytical Instruments (Pvt) Ltd', '100, Elvitigala Mawatha, Colombo 8', '', 20, 20, 8, '', '', 1, 'University of Peradeniya', '2006-08-01', 1, 'Mr. Nishantha Weerakoon ', 'nishanthaw@sci.pdn.ac.lk', '0812394276', '', '                                                                                                                                                                            drying, fusion, decomposition solid samples                                                                                 ', NULL, 'muffle.jpg', NULL, NULL, NULL, 0, 453, '2024-07-31 13:25:36', NULL, NULL, NULL, NULL, NULL),
(1293, 'Isodynamic Magnetic Seperator', 3, 33, 161, 260, 300, 1, 'Frantz', 'Frantz L1', '2017', '', '<p>Separation of minerals based on their magnetic properties.&nbsp;</p>\r\n', '', '', '', 0.00, 0.00, 'Analytical Instruments (Pvt) Ltd ', '100, Elvitigala Mawatha, Colombo 8', '', 0, 0, 0, '', '', 1, 'University of Peradeniya', '2017-08-01', 1, 'Mr. Nishantha Weerakoon ', 'nishanthaw@sci.pdn.ac.lk', '0812384276', '', '                                                              Mineral seperation                                                                                                       ', NULL, 'isodynamic(1).jpg', '', '', '', 0, 453, '2024-07-31 13:29:33', 453, '2024-08-02 08:38:28', NULL, NULL, NULL),
(1294, 'Inverted microscope', 36, 79, 249, 527, 301, 3, 'Carl Zeiss Limited', '', '0000', '', '<p>Inverted microscope is used for observing cells and organisms in cultures, petri dishes, flasks, microplates. This microscope is equipped with brightfield and often phase contrast which allows unstained transparent tissue to be observed more clearly.</p>\r\n', '', '', '', 0.00, 0.00, 'Analytival Instrument (PVT) LTd', '', '', 0, 0, 0, '<ul>\r\n	<li>Viewing Head -&nbsp;Trinocular head upright and unreversed image with camera port with interface 60N.</li>\r\n	<li>Focusing &ndash; Manual coarse and fine focusing.</li>\r\n	<li>Illumination ;Halogen illuminator has a quarts collector lamp mount and heat &ndash;reflecting filter</li>\r\n	<li>Camera &ndash; Axiocam 305 digital color camera with a SONY imx264 Exmor Global Shutter ,Cmos pixel size of 3.45micrometer and USB 3 connectivity.&nbsp;&nbsp;</li>\r\n</ul>\r\n', 'Yes', 1, 'Government', '', 1, 'Dr. WMHK Wijenayake, Head, Department of Aquaculture and Fisheries', 'hiranyakelum@wyb.ac.lk', '0312299874', '0718129770', '                                                                                                                                                                                                                                                                                                                                          ', NULL, '', '', '', '', 0, 362, '2024-08-05 14:28:33', 362, '2024-08-15 10:51:45', NULL, NULL, NULL),
(1295, 'Freeze dryer', 36, 79, 249, 528, 302, 1, '', '', '0000', '', '<p>Freeze Dryer is used to dry products under low temperature and vacuum without damaging their chemical structures.&nbsp;Allowed to use only for food samples.</p>\r\n', '', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, '', 'Yes', 1, 'AHEAD grant', '', 1, 'Dr. WMHK Wijenayake, Head, Department of Aquaculture and Fisheries', 'hiranyakelum@wyb.ac.lk', '0312299874', '0718129770', '                                                                                                                                                                                                                                                                                                                                       ', NULL, '', '', '', '', 0, 362, '2024-08-05 14:32:53', 362, '2024-08-28 21:57:05', NULL, NULL, NULL),
(1296, 'Rotary evaporator', 36, 79, 249, 526, 303, 4, '', '', '0000', '', '<p>The rotary evaporator is used for the evaporation and condensing of solvents using a rotating evaporating flask under vacuum. Distillation under vacuum increases capacity and is gentler on the product. Allowed to use only for food samples.</p>\r\n', '', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, '', '', 1, 'AHEAD grant', '', 1, 'Dr. WMHK Wijenayake, Head, Department of Aquaculture and Fisheries', 'hiranyakelum@wyb.ac.lk', '0312299874', '0718129770', '                                                                                                                                                                                                                                                                                                                                       ', NULL, '', '', '', '', 0, 362, '2024-08-05 14:35:38', 362, '2024-08-15 10:51:00', NULL, NULL, NULL),
(1297, 'Spectrophotometer', 36, 79, 249, 526, 238, 1, 'Thermo Scientific  ', 'DR 2400', '0000', '', '<p>UV-Visible Spectroscopy is based on the absorption of ultraviolet light or visible light by chemical compounds, which results in the production of distinct spectra.&nbsp;</p>\r\n', '', '', '', 0.00, 0.00, 'Analytical Instrument (PVT) Ltd', '', '', 0, 0, 0, '<ul>\r\n	<li>Source lamp -&nbsp; Xenon</li>\r\n	<li>Beam type &ndash; Double</li>\r\n	<li>Min wave length -190nm, Max wave length -1100nm</li>\r\n	<li>Photometric Readout types</li>\r\n	<li>Display type - LCD</li>\r\n	<li>Detector &ndash; Dual silicon Photodiodets</li>\r\n</ul>\r\n', 'Yes', 1, 'Government', '', 1, 'Dr. WMHK Wijenayake, Head, Department of Aquaculture and Fisheries', 'hiranyakelum@wyb.ac.lk', '0312299874', '0718129770', '                                                                                                                                                                     ', NULL, '', '', '', '', 0, 362, '2024-08-05 14:37:17', 362, '2024-08-09 11:20:30', NULL, NULL, NULL),
