(1336, 'Shredder', 47, 81, 256, 388, 316, 1, '', 'PC 500', '0000', '', '<p>A shredder efficiently processes various fibrous materials, breaking them down into smaller, manageable pieces for recycling, disposal, or repurposing, ensuring effective material reduction and improved waste management.</p>\r\n', '', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, '', '', 1, 'UOM', '', 1, 'Harshani Hettiarachchi', 'harshanih@uom.lk', '4622/4100', '', '                                                                                                                                                                     ', NULL, '', '', '', '', 0, 486, '2024-08-26 13:01:53', 486, '2024-08-29 09:33:59', NULL, NULL, NULL),
(1337, 'Hot Press', 47, 81, 256, 388, 316, 1, '', '', '0000', '', '<p>A hot press for rubber and plastic molding uses heat and pressure to shape and bond materials, producing durable, precise molds, ensuring high-quality, consistent results for industrial and manufacturing applications.</p>\r\n', '', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, '', '', 1, 'UOM', '', 1, 'Harshani Hettiarachchi', 'harshanih@uom.lk', '4622/4100', '', '                                                                                                                                                                     ', NULL, '', '', '', '', 0, 486, '2024-08-26 13:06:13', 486, '2024-08-29 09:33:37', NULL, NULL, NULL),
(1338, 'Cooling Press', 47, 81, 256, 388, 316, 1, '', '', '0000', '', '<p>A cooling press for rubber and plastic molding solidifies materials after heating, applying controlled pressure and cooling to ensure molded products retain their shape, strength, and precision during the manufacturing process.</p>\r\n', '', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, '', '', 1, 'UOM', '', 1, 'Harshani Hettiarachchi', 'harshanih@uom.lk', '4622/4100', '', '                                                                                                                                                                     ', NULL, '', '', '', '', 0, 486, '2024-08-26 13:07:49', 486, '2024-08-29 09:34:56', NULL, NULL, NULL),
(1339, 'Laminating Press', 47, 81, 256, 388, 316, 3, '', '', '0000', '', '<p>A laminating press for plastics and fiber bonds layers under heat and pressure, creating durable, uniform composites with enhanced strength, flexibility, and resistance, ideal for industrial, automotive, and construction applications.</p>\r\n', '', '', '', 0.00, 0.00, '', '', '', 0, 0, 0, '', '', 1, 'UOM', '', 1, 'H. Hettiarachchi', 'harshanih@uom.lk', '4622/4100', '', '                                                                                                                                                                     ', NULL, '', '', '', '', 0, 486, '2024-08-26 13:09:46', 486, '2024-08-29 09:32:59', NULL, NULL, NULL),
