(1363, 'Fluorescence and transmitted light microscope.', 4, 3, 50, 567, 337, 1, 'Carl Zeiss ', 'Axioscope A1 ', '2014', '', '<p>Carl Zeiss Axioscope A1 fluorescence and transmitted light microscope.</p>\r\n\r\n<p>HAL 100 illuminator with quartz collector</p>\r\n\r\n<p>Filters :&nbsp;</p>\r\n\r\n<p>EX350/50 EM460/50 nm,</p>\r\n\r\n<p>EX495/25 EM537/29 nm,</p>\r\n\r\n<p>EX546/10 EM572/23 nm</p>\r\n', '', NULL, '', 0.00, 0.00, 'Analytical Instruments Pvt Ltd', '', '', 10, 2, 5, '', 'Yes', 1, 'NRC', '2015-03-12', 1, 'Prof Gayani Galhena', 'gayani@zoology.cmb.ac.lk', '', '', '                                                                                                                             fluorescence imaging, transmitted light microscope, FITC, TRITC, DAPI                                                                                                                            ', NULL, NULL, NULL, NULL, NULL, 0, 556, '2024-08-28 01:58:34', NULL, NULL, NULL, NULL, NULL),
(1364, 'Benchtop EDXRF Spectrometer', 47, 81, 256, 390, 338, 4, 'Rigaku', 'NEX QC', '0000', '', '<p>The EDXRF spectrometer for the elemental analysis of sodium through uranium in solid,liquids and powder samples as well as thin film coatings on solid substrates.</p>\r\n', '', NULL, '', 0.00, 0.00, '', '', '', 0, 0, 0, '<p>Product name-NEX QC</p>\r\n\r\n<p>Technique-X-ray fluorescence</p>\r\n\r\n<p>Benefit-Elemental analysis of solids,liquids,powders,alloys and thin films</p>\r\n\r\n<p>Technology-EDXRF using solid state detector</p>\r\n\r\n<p>&nbsp;</p>\r\n', '', 1, 'University of Moratuwa', '', 1, 'Mrs.Hasini Gunarathna', '', 'Ext:4100', '', '                                                                                    ', NULL, 'xrf.JPG', NULL, NULL, NULL, 0, 488, '2024-08-28 12:52:54', NULL, NULL, NULL, NULL, NULL),
(1365, 'Density balance(Solid and liquid)', 47, 81, 256, 390, 339, 1, 'Axis', 'ALN 220', '0000', '', '<p>ALN series balances are destined for high accuracy weighing in laboratory practice. Balances are equipped with internal calibration system for accuracy control during balance operations. .</p>\r\n', '', NULL, '', 0.00, 0.00, '', '', '', 0, 0, 0, '<p>Capacity (Max) - 220g</p>\r\n\r\n<p>Min load (Min) - 10mg</p>\r\n', '', 1, 'University of Moratuwa', '', 1, 'Mrs.Hasini Gunarathna', '', 'Ext:4100', '', '                                                                                    ', NULL, 'den.JPG', NULL, NULL, NULL, 0, 488, '2024-08-28 15:19:33', NULL, NULL, NULL, NULL, NULL),
