(1464, 'Sole adhesion tester', 11, 65, 0, 112, 307, 1, 'SATRA Technology Centre', 'STD 185', '2018', '', '<p>Determination of sole adhesion strength of a shoes</p>\r\n', 'https://www.satra.com/test_equipment/machine.php?id=26', NULL, '', 0.00, 0.00, '', '', '', 1, 5, 7, '<p>sample mounted on rigid horizontal surface</p>\r\n\r\n<p>&nbsp;</p>\r\n', 'yes', 1, 'SLSI  fund', '2024-09-20', 1, 'Sashika Roshanie', 'sashika@slsi.lk', '0112019631', '0714812195', ' Upper sole adhesion\r\ntoe adhesion strength\r\n                                                  ', NULL, 'Adeshion_tester_2.jpg', 'Adhesion_tester.jpg', NULL, NULL, 0, 478, '2024-09-20 10:39:35', NULL, NULL, NULL, NULL, NULL),
(1465, 'Thickness Tester', 11, 65, 0, 112, 306, 1, 'IKON Industries', '', '0000', '', '<p>fabric cellular products- dead load type thickness tester with dial micrometer with flat pressure foot</p>\r\n', '', NULL, '', 0.00, 0.00, '', '', '', 1, 10, 7, '<p>range:0 -10 mm</p>\r\n\r\n<p>size of pressure foot: 10 mm diameter</p>\r\n\r\n<p>Anvil size: 60 mm diameter</p>\r\n\r\n<p>&nbsp;</p>\r\n', 'yes', 1, 'SLSI  fund', '2024-09-20', 1, 'Sashika Roshanie', 'sashika@slsi.lk', '0112019631', '0714812195', 'Thickness Gauge\r\nMicron thickness\r\nThickness tester                                                                                   ', NULL, 'Thickness_tester.PNG', NULL, NULL, NULL, 0, 478, '2024-09-20 10:50:17', NULL, NULL, NULL, NULL, NULL);
