INSERT INTO `instrument_types` (`instrument_type_id`, `instrument_type`, `parameters`, `description`, `keywords`, `relevant_instruments`, `isDeleted`, `created_user_id`, `updated_user_id`, `created_date_time`, `updated_date_time`, `institute_id`, `faculty_id`, `deletedBy`, `deleted_date_time`) VALUES
(2, 'Water Quality', 'Nitrogen/phosphorus concentration, Turbidity, Temperature, Color, Electrical Conductivity, PH, Acidity, Alkalinity, Chlorine, Hardness, Dissolved Oxygen, Biological Oxygen Demand, ', '          Water quality testing instruments are used to test water for chemical and biological agents, and to measure variables such as clarity and rate of movement. These instruments provide a standard tool that can be used to collect information from various water sources. Water quality testing instruments can monitor water temperature, dissolved oxygen, pH, conductivity, nitrogen/phosphorus concentration, turbidity, macroinvertebrates, and levels of pesticides and toxic chemicals.                                                                          ', 'Dissolved oxygen (DO),  Dissolved carbon dioxide, Chlorophyll/ algal pigments, ,Extreme environment, Filters, Event-triggered, Biological Parameters, Bacteria,', '     Thermo meter, PH meter, Digital Water Tester, Pocket TDS Testers,                                                                                ', 0, 1, NULL, '2022-06-22 01:08:10', NULL, NULL, 0, 0, NULL),
(3, 'Cream', 'Water content, Thermal stability, PH, Peroxide value, Non volatile matter at 105 °C, Heavy metals (Arcenic, Lead, Cadmium, Mercury)', 'Simply put, lotions are lighter with more water content and less oil. Creams are heavier, with more oil content and less H20.                                                                                    ', 'Skin cream & lotions, Skin creams and lotions for babies, Shaving cream, Hair Cream', 'Calibrated oven,  pH meter,  Water bath + Calibrated oven, Calibrated incubator, ICPMS (Major equipment)                                                                        ', 0, 1, NULL, '2022-07-08 10:32:26', NULL, NULL, 0, 0, NULL),
(4, 'Elements in solution', 'Concentration of  Individual elements in ppm and ppb level', 'Atomic absorption spectrometry (AAS) is  used primarily to determine the concentrations of individual elements in solution. As such, AAS is used in food and beverage, water, clinical research, and pharmaceutical analysis. It is also used in mining operations to determine, metal concentration.                                                       ', 'Food and beverage, Water, Pharmaceuticals', 'ICP-OES                                                  ', 0, 17, NULL, '2022-07-12 23:43:09', NULL, 18, 0, 0, NULL),
(5, 'Tea (ISO)', 'Total Polyphenol, Total Amino acid, Total Catechin, Caffeine, TF-TR, Glucose, Fructose, Sucrose', 'ISO Standards                                                                          ', 'Made tea', 'Spectrophotometer, HPLC', 1, 22, NULL, '2022-09-01 15:43:08', NULL, 5, 0, 22, '2022-09-01 15:51:18'),
(6, 'Trace & Heavy metal', 'Concentration of Trace & Heavy metals', 'A trace-level, elemental analysis technique that uses the emission spectra of a sample to identify, and quantify the elements present. Simultaneous, sequential analysis of multiple elements and high number of measurable elements is possible.                                                      ', 'Water, Soil, Sludge, Plant, Milk, Fertilizer', 'Inductively couple Plasma Optical emission spectrometer                                                                                     ', 0, 8, NULL, '2022-08-31 11:42:16', NULL, 7, 0, 0, NULL),
(7, 'Gas composition/chemicals composition', 'Concentration ', ' Chemical components (organic molecules/volatiles/gases)  of a sample mixture identify by separating and then detecting them qualitatively and quantitatively.                                                                ', 'Food, Feed, plant materials ', 'Gas chromatography                                                             ', 1, 34, NULL, '2022-07-15 14:13:18', NULL, 7, 0, 34, '2022-09-01 09:56:22'),
