(301, 'Microscope', 'Live cell observation, Cell screening, Cell sampling and handling ', '<p>Inverted microscope is used for observing cells and organisms in cultures, petri dishes, flasks, microplates. This microscope is equipped with brightfield and often phase contrast which allows unstained transparent tissue to be observed more clearly.</p>\r\n', 'Inverted microscope', 'Inverted microscope', 0, 362, NULL, '2024-08-05 14:20:07', NULL, 36, 0, 0, NULL),
(302, 'Freeze drying', '', '<p>Freeze Dryer is used to dry products under low temperature and vacuum without damaging their chemical structures.&nbsp;Allowed to use only for food samples.</p>\r\n', '', 'Freeze dryer                                                             ', 0, 362, NULL, '2024-08-05 14:23:08', NULL, 36, 0, 0, NULL),
(303, 'Evaporating and condensing solvents and suspensions.', '', '<p>The rotary evaporator is used for the evaporation and condensing of solvents using a rotating evaporating flask under vacuum. Distillation under vacuum increases capacity and is gentler on the product. Allowed to use only for food samples.</p>\r\n', '', 'Rotary evaporator                                                                                                                         ', 0, 362, NULL, '2024-08-05 14:25:17', NULL, 36, 0, 0, NULL);
INSERT INTO `instrument_types` (`instrument_type_id`, `instrument_type`, `parameters`, `description`, `keywords`, `relevant_instruments`, `isDeleted`, `created_user_id`, `updated_user_id`, `created_date_time`, `updated_date_time`, `institute_id`, `faculty_id`, `deletedBy`, `deleted_date_time`) VALUES
(304, 'Product Texture', 'Cohesiveness, Hardness, Chewiness, Gumminess', '<p>TX-700: An advanced, high-precision texture analyzer designed for the rigorous demands of research and quality control in various industries, including food, pharmaceuticals, cosmetics, and materials science. The new TX-700 is entirely equipped with one 7&#39;&#39; color touch screen. It is giving you a greater comfort to work and a clear view of data and results of analysis and curves without external software.&nbsp;</p>\r\n', 'Compression Platens use for test on self supporting products such as Cheese, Ice cream and gels', '                                                                                    ', 0, 358, NULL, '2024-08-15 12:45:17', NULL, 36, 0, 0, NULL),
(305, 'Tissue sectioning', '', '<p>This instrument used&nbsp;to repeatedly slice tissue into thin, uniform sections for downstream laboratory processing and imaging.</p>\r\n', '', 'Microtome', 0, 362, NULL, '2024-08-20 12:34:20', NULL, 36, 0, 0, NULL),
(306, 'Textile/Fabric', 'Breaking force, Tearing Force, GSM, pH, Colour fastness to light, Colour fastness to water, Crease Recovery, Skewness, Shrinkage on washing', '<p>Determination of fabric performance parameters, colour fastness properties. For garments dimensional change in washine, pilling testing.&nbsp;</p>\r\n', 'Garments, Fabric, Towels', 'Tensile testing  machine, Xenon Colour fastness   Tester, pilling tester, pH meter,            ', 0, 478, NULL, '2024-08-20 20:04:41', NULL, 11, 0, 0, NULL),
(307, 'Shoes Testing', 'Abrasion resistance, Bonding Strength(Teo & back),  Whole Shoe flexing , Sole flexing test, Sole material identification', '<p>Determination of performance parameters of shoe such as abrasion, bonding strength and flexing. Determination of upper materials and sole materilas, carryout the dimension test of upper, counter and sole materials.&nbsp;</p>\r\n', 'Leather shoes, Sports/ Deck shoes, Gum boot, Riding boot, School Shoes', '         DIN abrasion tester, Whole shoe testing machine, Whole sole testing machine,  Bonding tester,   Thickness gauge.                                                                        ', 0, 478, NULL, '2024-08-20 20:14:37', NULL, 11, 0, 0, NULL),
(308, 'Coated fabrics', 'Tensile strength, tearing strength, mass per unit area, Thickness, Water penetration test, Water repellence test', '<p>Determination of performance parameter such as tensile, tearing, water penetration and water repellency.</p>\r\n\r\n<p>Carry out thickness and mass per unit area.</p>\r\n', 'Tarpoulin, PU coated Nylon, Umbrella cloth', '  Universal Tensile tester, Bumdusman Rain shower test, Water repellency tester, Thickness gauge.                                                            ', 0, 478, NULL, '2024-08-20 20:19:37', NULL, 11, 0, 0, NULL),
(309, 'Polythene/plastic', 'Thickness, Tensile strength, Tearing Strength, Mass per area, dimension. ', '<p>Determination of performance parameters and dimensions.&nbsp;</p>\r\n', 'polythene garbage bag, Polythene Grocery bag, Lunch sheet, ', '      Universal tensile tester, Micrometer, Analytical balance                                                                 ', 0, 478, NULL, '2024-08-20 20:24:16', NULL, 11, 0, 0, NULL),
(310, 'Sanitary products', 'Absorbency, Re wet under load, pH, Ash content, Moisture content, Total absorption capacity. ', '<p>Determination of all performance parameters for sanitory products as well as micro biological parameters. Issue test report as per the NMRA regulations.&nbsp;</p>\r\n', 'Sanitary napkins, Panty liners, Baby Diapers, adult diapers', ' Analytical balance, Thickness gauge, Electric Oven.                                                         ', 0, 478, NULL, '2024-08-20 20:29:12', NULL, 11, 0, 0, NULL),
(311, 'Umbrella', 'Fabric Tensile strength, tearing strength, Colour fastness to water, Colour fastness to light, construction properties and dimensions of the  umbrella ribs a', '<p>Tesing of Umbrella ribs and umbrella cloth for the SLS and ISO standards.</p>\r\n', 'Umbrella cloth, Umbrella ribs, folding umbrella, non-folding umbrella.', '     Xenon light fastness tester,  Rota wash colour fastness tester,   Universal tensile tester,                                                                    ', 0, 478, NULL, '2024-08-20 20:35:01', NULL, 11, 0, 0, NULL),
(312, 'Petroleum Products', 'Density, Viscosity', '', 'Petrol, Diesel, JET A-1, Kerosene', '                                                                                    ', 0, 549, NULL, '2024-08-20 23:17:49', NULL, 71, 0, 0, NULL),
