(372, 244, 75, 48, 'Hydraulic Engineering Laboratory', '6.817860001472514', '79.89030731129439', 'General Sir John Kotelawala Defence University, Kandawala Rd, Ratmalana.', '0112623027', 'jinadasac@kdu.ac.lk', 'The Hydraulic Engineering Laboratory offers a variety of equipment for experimenting and analyzing various topics in fluid mechanics and hydraulic engineering including engineering properties of fluids, hydrostatics, fluid kinematics.', NULL, NULL, NULL, NULL, 79, NULL, '2023-03-10 10:41:46', NULL, 0, NULL, NULL),
(373, 244, 75, 48, 'Environmental Engineering Laboratory', '6.817902613340374', '79.8903180401302', 'General Sir John Kotelawala Defence University, Kandawala Rd, Ratmalana.', '0112623027', 'dept_civileng@kdu.ac.lk', 'Environmental Engineering Laboratory provides the students with facilities to investigate and observe both chemical and biological parameters related to water quality.', NULL, NULL, NULL, NULL, 79, NULL, '2023-03-10 10:20:00', NULL, 0, NULL, NULL),
