(413, 255, 81, 47, 'Structural Testing Laboratory', '6.798515096604491', '79.90304747219079', 'University of Moratuwa', '0112640051', 'yasithcm@uom.l', '', NULL, NULL, NULL, NULL, 79, NULL, '2023-03-09 13:22:34', NULL, 0, NULL, NULL),
(414, 255, 81, 47, 'Building Materials Laboratory', '6.7987867581476795', '79.90252175922441', 'University of Moratuwa', '0112640051', 'baskaran@uom.lk', 'The Building Materials Laboratory provides facilities for practical and research works, as well as opportunities for instruction in building materials testing methods and their application to engineering problems.', NULL, NULL, NULL, NULL, 79, NULL, '2023-03-09 13:21:19', NULL, 0, NULL, NULL),
(415, 255, 81, 47, 'Structural Dynamics and Health Monitoring', '6.798464492966745', '79.90264514080083', 'University of Moratuwa', '0112640051', 'sujeewa@uom.lk', '', NULL, NULL, NULL, NULL, 79, NULL, '2023-03-09 13:19:45', NULL, 0, NULL, NULL),
