(417, 255, 81, 47, 'Pro Green Laboratory', '6.798647312818776', '79.90247620614349', 'University of Moratuwa', '0112640051', 'rangika@uom.lk', '', NULL, NULL, NULL, NULL, 79, NULL, '2023-03-09 12:48:14', NULL, 0, NULL, NULL),
(418, 255, 81, 47, 'Environmental Engineering Laboratory', '6.798456381125066', '79.90266359478667', 'University of Moratuwa', '0112640051', 'manatunge@uom.lk', 'The Environmental Engineering Laboratory was established in the Environmental Engineering Division, Department of Civil Engineering, University of Moratuwa to facilitate to measure a wide range of environmental parameters in drinking water, wastewater, surface and groundwater, soil, sediments, construction materials, sludge, etc. The laboratory has been fully equipped with modern facilities, sophisticated instruments together with qualified and committed. Therefore, the laboratory has been capable of providing analytical services effectively and efficiently within the lesser time to both the government sector and the private sector.', NULL, NULL, NULL, NULL, 79, NULL, '2023-03-09 12:46:42', NULL, 0, NULL, NULL),
(419, 255, 81, 47, 'Soil Mechanics Laboratory', '6.798403116584739', '79.90311957032358', 'University of Moratuwa', '0112640051', 'nalinds@uom.lk', 'Soil mechanics is a discipline that uses the principles of mechanics to describe the behaviour of soil of engineering scale. Branch of Science dealing with the structure, Engineering properties and reactions (behaviour) of soils under loading and weathering. This studies theoretically and practically soils for building of structures over it. Knowledge of physics, mechanics, and hydraulics applied to study the behaviour of soils. Also called Geo-Technique (Geo-Tech Engineering) Studies the mutual interaction of soils and structure. The practice of Engineering which applies the principles of soil mechanics to the design of engineering structures is called soil mechanics Engineering or Geotechnical Engineering.', NULL, NULL, NULL, NULL, 79, NULL, '2023-03-09 12:45:39', NULL, 0, NULL, NULL),
(420, 255, 81, 47, 'Rock Mechanics Laboratory', '6.798461712731026', '79.90266359482989', 'Rock mechanics is a discipline that uses the principles of mechanics to describe the behaviour of rock of engineering scale. That recognition is an inevitable consequence of new engineering activities in rock, including complex underground installations, deep cuts for spillways, and enormous open pit mines. Rock mechanics deals with the properties of rock and the special methodology required for d', '0112640051', 'nalinds@uom.lk', '', NULL, NULL, NULL, NULL, 79, NULL, '2023-03-09 12:44:29', NULL, 0, NULL, NULL),
(421, 255, 81, 47, 'Hydraulic Engineering Laboratory', '6.798456388485441', '79.9026582304337', 'University of Moratuwa', '0112640051', 'nimalw@uom.lk', '', NULL, NULL, NULL, NULL, 79, NULL, '2023-03-09 12:43:23', NULL, 0, NULL, NULL),
(422, 255, 81, 47, 'Highway Engineering Laboratory', '6.798424430743334', '79.90276015439396', 'University of Moratuwa', '0112640051', 'pasindu@uom.lk', '', NULL, NULL, NULL, NULL, 79, NULL, '2023-03-09 12:41:43', NULL, 0, NULL, NULL),
