(575, 199, 22, 4, 'Parasitology Laboratory', '6.905121270473732', '79.86996135538563', 'Faculty of Medicine', '0112695300', 'sashika@parasit.cmb.ac.lk', '', NULL, NULL, NULL, NULL, 659, NULL, '2025-03-03 14:28:37', NULL, 0, NULL, NULL),
