(617, 323, 90, 12, 'Tissue Culture Laboratory', '6.905121270473732', '79.86996135538563', 'Tissue Culture Laboratory, Department of Biosystems Technology, Faculty of Technology,  South Eastern University of Sri Lanka,  University Park,  Oluvil, 32360, Sri Lanka ', '0774659839', 'shanuke@seu.ac.lk', '<p>Tissue Culture Laboratory&nbsp;</p>', 'No', '', NULL, NULL, 743, NULL, '2026-06-08 08:28:22', NULL, 0, NULL, NULL),
(618, 323, 90, 12, 'Microbiology Laboratory', '6.905121270473732', '79.86996135538563', 'Microbiology Laboratory, Department of Biosystems Technology, Faculty of Technology,  South Eastern University of Sri Lanka,  University Park,  Oluvil, 32360, Sri Lanka ', '0774659839', 'shanuke@seu.ac.lk', '<p>Microbiology Laboratory&nbsp;</p>', 'No', '', NULL, NULL, 743, NULL, '2026-06-08 08:33:51', NULL, 0, NULL, NULL),
(619, 50, 3, 4, 'Synthetic Biology Laboratory', '6.905121270473732', '79.86996135538563', 'Synthetic Biology Research Laboratory (SynBioLab)', '0777851528', 'icperera@sci.cmb.ac.lk', '<p>The <strong>Synthetic Biology Research Laboratory (SynBioLab)</strong>, based in the Department of Zoology and Environment Sciences at the University of Colombo, Sri Lanka, operates under the theme <i>\"Biology meets design.\" </i><a href=\"https://synbiolab.cmb.ac.lk/\"><i>https://synbiolab.cmb.ac.lk/</i></a><i>&nbsp;</i></p><p>The laboratory focuses on studying the regulation of genes at the molecular level to design novel drug targets and engineer biological systems for industrial and environmental applications.</p><p>Key pillars of SynBioLab\'s diverse research include:</p><p><strong>Pathogenic Bacteria &amp; Drug Discovery:</strong> A major focus lies in understanding the transcriptional regulation machinery of critical pathogens like <i>Mycobacterium tuberculosis</i> and <i>Pseudomonas aeruginosa</i> to discover novel antibiotic targets.</p><p><strong>Genomic Surveillance &amp; Infectious Diseases:</strong> Tracking extra-pulmonary tuberculosis, evaluating zoonotic viruses in wildlife (such as bats, rodents, and mosquitoes), and monitoring avian respiratory viruses in migratory birds.</p><p><strong>Biomedical &amp; Cancer Research:</strong> Exploring organometallic and peptide anticancer drug leads, identifying cancer biomarkers, and studying metabolic disorders like MASLD within the Sri Lankan population.</p><p><strong>Environmental &amp; Industrial Solutions:</strong> Bioengineering model organisms for tasks like alkane degradation (pollution mitigation), developing biosensors to detect environmental contaminants, and studying microbial communities in traditional food production.</p><p>Through national and international collaborations, SynBioLab combines molecular biology, genetics, and bioengineering to create actionable biological tools that address pressing healthcare, agricultural, and environmental challenges.</p>', 'No', '', '', '', 556, NULL, '2026-06-17 09:18:04', NULL, 0, NULL, NULL),
(620, 0, 0, 46, 'Plant Lab', '6.905121270473732', '79.86996135538563', '', '0112552528', 'anoma@ibmbb.cmb.ac.lk', '', 'No', '', NULL, NULL, 550, NULL, '2026-06-23 10:07:22', NULL, 0, NULL, NULL),
