(626, 0, 0, 46, 'Protein Lab', '6.905121270473732', '79.86996135538563', '', '0112552528', 'anoma@ibmbb.cmb.ac.lk', '', '', '', NULL, NULL, 550, NULL, '2026-06-23 14:02:42', NULL, 0, NULL, NULL),
(627, 0, 0, 46, 'Sensitive DNA Typing Lab', '6.905121270473732', '79.86996135538563', '', '0112552528', 'anoma@ibmbb.cmb.ac.lk', '', '', '', NULL, NULL, 550, NULL, '2026-06-23 14:21:52', NULL, 0, NULL, NULL),
(628, 117, 62, 27, 'Histology Laboratory', '6.905121270473732', '79.86996135538563', 'Department of Anatomy, Faculty of Medical sciences, University of Sri Jayewardenepura, Gangodawila, Nugegoda ', '0716090858', 'edirisinghe@sjp.ac.lk', '', '', '', '', '', 551, NULL, '2026-06-23 22:24:04', NULL, 0, NULL, NULL),
(629, 60, 29, 24, 'Applied Mechanics and Control Laboratory', '6.905121270473732', '79.86996135538563', 'Department of Mechanical and Manufacturing Engineering, Faculty of Engineering, University of Ruhuna', '0912245765', 'hod@mme.ruh.ac.lk', '<p>The Applied Mechanics and Control Laboratory supports teaching and research in mechanics, control systems, automation, PLCs, robotics, and mechatronics. Equipped with facilities including a <strong>Workstation computer with GV100 GPU</strong>, <strong>Inverted Pendulum Control System</strong>, and a <strong>6-DOF research robot</strong>, the laboratory provides practical experience in system modeling, feedback control, automation, and advanced engineering applications. hosts equipment related to teaching and research. Furthermore, this laboratory hosts projects and research related to UAV and Drone systems.</p>', 'No', '', NULL, NULL, 769, NULL, '2026-06-30 07:02:19', NULL, 0, NULL, NULL),
(630, 304, 88, 17, 'Control And Automation Laboratory', '6.905121270473732', '79.86996135538563', 'Uva wellassa University Passara Road Badulla', '0553137505', 'det@uwu.ac.lk', '', 'No', '', NULL, NULL, 555, NULL, '2026-07-08 11:12:00', NULL, 0, NULL, NULL),
